SELECT (x->>'id')::uuid,(x->>'document_id')::uuid,x->>'file_type',x->>'storage_path',x->>'download_filename',
       x->>'mime_type',(x->>'file_size')::bigint,x->>'sha256',(x->>'page_count')::integer,
       (x->>'is_downloadable')::boolean,x->>'download_block_reason'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT DO NOTHING;

COMMIT;

SELECT 'moj-all-verified-judgments-review-002-chunk-053' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"da852891-115b-5d08-885f-5a3b8491da92","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حد املسكر -تلفظ على رجال األمن -قيادة السيارة حتت تأثير املسكر -ال يحد برائحة املسكر -درء احلد بالشبهة -تداخل التعازير -التعزير باجللد والسجن .","document_number":"3457183","case_number":"33493910","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/7","year":"1434","subject":"مسكر -شرب املسكر -حد املسكر -تلفظ على رجال األمن -قيادة السيارة حتت تأثير املسكر -ال يحد برائحة املسكر -درء احلد بالشبهة -تداخل التعازير -التعزير باجللد والسجن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫رقم الصك‪ 3457183 :‬تاريخه‪1434/3/7:‬هـ‬\n                  ‫رقم الدعوى‪33493910:‬‬\n            ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34210684:‬تاريخه‪1434/05/11:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬حــد املســكر ‪ -‬تلفــظ علــى رجــال األمــن ‪ -‬قيــادة‬\n‫الســيارة حتــت تأثيــر املســكر ‪ -‬ال يحــد برائحــة املســكر ‪ -‬درء احلــد‬\n           ‫بالشــبهة ‪ -‬تداخــل التعازيــر ‪ -‬التعزيــر باجللــد والســجن ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه صلــى اهلل عليــه وســلم ( مــن شــرب اخلمــر فاجلــدوه ) أخرجــه‬\n                                                          ‫أحمــد وأبــو داود ‪.‬‬\n‫‪ -2‬مــا نــص عليــه أهــل العلــم مــن أنــه ال يحــد بوجــود رائحــة اخلمــر‬\n‫منــه الحتمــال أنــه متضمــض بهــا أو ظنهــا مــاء فلمــا صــارت يف فيــه‬\n‫مجهــا ونحــو ذلــك واحلــد يــدرأ بالشــبهة لكــن يعــزر كحاضــر شــربها‬\n                                             ‫( كشــاف القنــاع ‪. )101/14‬‬\n       ‫‪ -3‬ما نص عليه أهل العلم من أن العقوبات التعزيرية تتداخل‬\n                                      ‫( كشاف القناع ‪. )113/14‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهــم بشــرب املســكر ‪ ،‬وبقيــام‬\n‫املدعــى عليــه الثانــي والثالــث بالتلفــظ علــى رجــال األمــن وقيــادة املدعــى‬\n‫عليــه الثانــي الســيارة حتــت تأثيــر املســكر وطلــب إثبــات مــا أســند إليهم‬\n‫واحلكــم عليهــم بحــد املســكر وبعقوبــة تعزيريــة لقــاء عــدم جتاوبهــم مع‬\n\n                                                                                      ‫‪92‬‬\n\f     ‫رجــال األمــن وعقوبــة تعزيريــة علــى الثانــي والثالــث لقــاء تلفظهــم علــى‬\n     ‫موظفــي اجلــوزات وإفهــام املدعــى عليــه الثانــي بــأن عقوبتــه لقــاء قيــادة‬\n     ‫الســيارة حتــت تأثيــر املســكر عائــدة للجهــة املختصــة وفــق األنظمــة‬\n     ‫والتعليمــات حيــث ورد بــاغ للدوريــات األمنيــة مــن قبــل جــوازات جســر‬\n     ‫امللــك فهــد عــن قيــام املدعــى عليــه الثانــي والثالــث بالتلفــظ علــى رجــل‬\n     ‫األمــن بألفــاظ غيــر الئقــة ثــم قامــا بالرقــص يف ســاحة اجلــوازات كمــا‬\n     ‫قــام املدعــى عليــه األول بعمــل حركــة ال أخالقيــة بيــده أمــام اجلنــدي‬\n     ‫وقــد اشــتبه بأنهــم يف حالــة ســكر وباستشــمامهم تبــن انبعــاث رائحــة‬\n     ‫املســكر مــن أنفاســهم جميعــا وتعــذر اســتجوابهم كونهــم يف حالــة‬\n     ‫ســكر شــديدة ‪ ،‬أنكــر األول شــرب املســكر ‪ ،‬كمــا أنكــر الثانــي‬\n     ‫شــرب املســكر وقيــادة الســيارة حتــت تأثيــره والتلفــظ على رجــال األمن‬\n     ‫‪ ،‬أقــر الثالــث بشــرب املســكر والرقــص يف ســاحة اجلــوازات والتلفــظ‬\n     ‫علــى رجــال األمــن ‪ ،‬أقــر الرابــع بشــرب املســكر وأنكــر التلفــظ علــى‬\n     ‫رجــال األمــن والرقــص ‪ ،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة علــى‬\n     ‫املدعــى عليــه الثالــث بجلــده حــد املســكر ثمانــن جلــدة وســجنه عشــرة‬\n     ‫أيــام وإثبــات إدانــة الرابــع بشــرب املســكر واحلكــم عليــه بجلــده حــد‬\n     ‫املســكر ثمانــن جلــدة ‪ ،‬عــدم ثبــوت إدانــة املدعى عليهمــا األول والثاني‬\n     ‫بشــرب املســكر أو قيــادة الثانــي للســيارة حتــت تأثيــره ‪،‬احلكــم بــدرء‬\n     ‫حــد املســكر عنهمــا وجلــد كل واحــد منهمــا تعزيــر ًا لتهمــة شــرب‬\n     ‫املســكر ســبعني جلــدة وصــرف النظــر عــن بقيــة طلبــات املدعــي العــام‬\n     ‫وقنــع املدعــى عليهــم باحلكــم واعتــرض املدعــي العــام مكتفيـ ًا بــأوراق‬\n                           ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬   ‫املعاملــة ُ‬\n\n\n\n‫‪93‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/02/17‬ه ـ لــدي‬\n‫ـاء علــى املعاملــة‬\n                 ‫أنــا ‪..........‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n‫احملالــة إلينــا مــن رئيــس احملكمــة برقــم (‪ )33493910‬وتاريــخ‬\n‫‪1433/07/29‬ه ـ افتتحــت اجللســة وفيهــا قــدم املدعــي العام‪.....‬الئحــة‬\n‫االدعــاء املتضمنــة بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام مبدينــة‬\n‫الدمــام أدعــي علــى ‪..... -1‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪.......... -2 ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪).....‬‬\n‫‪..... -3‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪.......... -4 ).....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬حيــث إنــه يف يــوم‬\n‫‪1433/5/14‬ه ـ ورد بــاغ لغرفــة العمليــات يف الدوريــات األمنيــة مــن‬\n‫قبــل جــوازات جســر امللــك فهــد عــن قيــام املدعــو ‪...../‬واملدعــو‪..... /‬‬\n‫بالتلفــظ علــى اجلنــدي ‪..... /‬بألفــاظ غيــر الئقــة مــن ســب وغيــره وعنــد‬\n‫محاولــة إعادتهــم لقســم القــدوم قامــوا بالنــزول مــن الســيارة والرقــص‬\n‫يف ســاحة اجلــوازات بطريقــة غيــر الئقــة وأثنــاء محاولــة ســحب إثباتاتهــم‬\n‫قــام املدعــو ‪..... /‬بعمــل حركــة ال أخالقيــة بيــده وذلــك أمــام اجلنــدي أول‬\n‫‪.......... /‬وقــد اشــتبه بأنهــم يف حالــة ســكر وذلــك لقــول املدعــى عليــه‬\n‫الثانــي املدعــو ‪(...../‬بأنهــم ســوف يرجعــون ليكملــوا الشــراب ) ويقصــد‬\n‫املســكر وباستشــمامهم تبــن انبعــاث رائحــة املســكر مــن أنفاســهم‬\n‫جميعـ ًا وقــد تعــذر اســتجوابهم كونهــم يف حالة ســكر شــديدة وبســماع‬\n‫أقوالهــم أقــروا بصحــة واقعــة القبــض وأقــر كل مــن املدعــى عليــه األول‬\n‫‪..... /‬واملدعــى عليــه الثانــي ‪..... /‬بتناولهــم للمســكر وأقــر املدعــى عليــه‬\n\n                                                                                      ‫‪94‬‬\n\f     ‫الثانــي ‪...../‬أنــه كان يقــود الســيارة عنــد القبــض عليــه وانتهــى التحقيــق‬\n     ‫إلــى توجيــه االتهــام للمدعــى عليهــم بشــرب املســكر وقيــام املدعــى‬\n     ‫عليــه الثانــي ‪...../‬واملدعــى عليــه الثالــث ‪..... /‬بالتلفــظ علــى رجــال‬\n     ‫األمــن وقيــادة املدعــى عليــه الثانــي ‪...../‬للســيارة حتــت تأثيــر املســكر‬\n     ‫وذلــك لألدلــة والقرائــن التاليــة ‪1:‬ـ مــا جــاء بأقوالهــم أثنــاء اســتجوابهم‬\n     ‫املدونــة علــى الصفحــات رقــم (‪10‬ــ‪11‬ــ‪12‬ــ‪13‬ــ‪ 14‬ــ‪ )15‬لفــة رقــم (‪2)1‬ـ مــا‬\n     ‫جــاء يف محضــر االستشــمام املــدون علــى الصفحــة رقــم (‪ )6‬لفــة رقــم‬\n     ‫(‪3 )1‬ـ مــا جــاء يف محضــر القبــض املرفــق لفــة رقــم (‪4)5‬ـ مــا جــاء يف‬\n     ‫خطــاب مديــر جــوازات جســر امللــك فهــد املرفــق علــى اللفــة رقــم (‪)30‬‬\n     ‫وبالبحــث يف ســوابق املدعــى عليهــم تبــن وجــود ســابقة واحــدة مســجلة‬\n     ‫علــى املدعــى عليــه األول ‪...../‬وهــي (حيــازة واســتعمال مخــدرات ) وعــدم‬\n     ‫وجــود ســوابق علــى الباقــن وحيــث أن مــا قــام بــه املدعــى عليهــم وهــم‬\n     ‫ا محــرم ومعاقــب عليــه شــرع ًا‬    ‫بكامــل أهليتهــم املعتبــرة شــرع ًا فع ـ ً‬\n     ‫ونظامـ ًا أطلــب إدانتهــم مبــا أســند إليهــم واحلكــم عليهــم باآلتــي ‪1:‬ـ ـ حــد‬\n     ‫املســكر لقــاء شــربهم إياه‪2‬ـ ـ عقوبــة تعزيريــة تزجرهــم وتــردع غيرهــم‬\n     ‫لقــاء عــدم جتاوبهــم مــع رجــال األمــن ‪3‬ـ ـ عقوبــة تعزيريــة للمدعــى عليــه‬\n     ‫الثانــي والثالــث لقــاء تلفظهــم علــى موظفــن اجلــوازات ‪4‬ـ إثبــات قيــادة‬\n     ‫(املدعــى عليــه الثانــي) للســيارة وهــو يف حالــة ســكر وفق ـ ًا للفقــرة (‪)8‬‬\n     ‫مــن اجلــدول رقــم (‪ )1‬امللحــق بنظــام املــرور وإفهامــه بــأن عقوبتــه الــواردة‬\n     ‫يف الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )68‬واملــادة (‪ )76‬مــن ذات النظــام‬\n     ‫عائــد ًا للجهــة املختصــة وفقـ ًا للفقــرة (‪ )2‬مــن قــرار مجلــس الــوزراء رقــم‬\n     ‫(‪)315‬يف ‪1428/10/24‬ه ـ وبــاهلل التوفيــق ويف اجللســة حضــر املدعــى‬\n     ‫ال‬‫عليهــم الثانــي ‪.....‬والثالــث ‪.....‬والرابــع ‪.....‬املــدون اســم كل منهم كام ً‬\n\n\n‫‪95‬‬\n\f‫وهويتــه أعــاه ولــم يحضــر املدعى عليــه األول ‪.....‬وبتالوة الدعوى العامة‬\n‫علــى املدعــى عليهــم احلاضريــن وســؤالهم اإلجابــة عليهــا أجــاب الثانــي‬\n‫بقولــه مــا ذكــره املدعــي العــام مــن شــربي للمســكر وقيــادة الســيارة‬\n‫حتــت تأثيــره والتلفــظ علــى رجــال األمــن فهــذا كلــه غيــر صحيــح هــذه‬\n‫إجابتــي كمــا أجــاب املدعــى عليــه الثالــث ‪.....‬بقولــه مــا ذكــره املدعــي‬\n‫العــام مــن شــربي للمســكر والرقــص يف ســاحة اجلــوازات بطريقــة غيــر‬\n‫الئقــة فهــذا صحيــح ومــا ذكــره مــن التلفــظ علــى رجــل األمــن فهــذا‬\n‫صحيــح ألنــه رمــى البطاقــة يف وجهــي وأنــا نــادم علــى مــا حصــل منــي‬\n‫هــذه إجابتــي كمــا أجــاب الرابــع ‪.....‬بقولــه مــا ذكــره املدعــي العــام‬\n‫مــن شــرب املســكر فهــذا صحيــح فقــد شــربت املســكر وأمــا مــا‬\n‫ذكــره مــن الرقــص أو التلفــظ علــى رجــال األمــن فهــذا غيــر صحيــح‬\n‫هــذه إجابتــي وبســؤال املدعــي العــام عــن البينــة املثبتــة لصحــة التهمــة‬\n‫املنســوبة للمدعــى عليهــم أجــاب بقولــه لقــد أشــرت إلــى األدلــة والقرائــن‬\n‫يف الئحــة االدعــاء وعليــه رفعــت اجللســة للدراســة والتأمــل ولطلــب‬\n‫إحضــار املدعــى عليــه ‪.....‬وســماع مــا لديــه مــن إجابــة ويف يــوم الســبت‬\n‫املوافــق ‪1434/3/7‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــى عليهــم‬\n‫ا وهويتــه يف اجللســة الســابقة‬ ‫‪.....‬و‪.....‬و‪.....‬املــدون اســم كل منهــم كامـ ً‬\n‫كمــا حضــر املدعــى عليــه ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ( ‪ ).....‬وبتــاوة الدعــوى العامــة عليــه و ســؤاله اإلجابــة عليهــا أجــاب‬\n‫بقولــه مــا ذكــره املدعــي العــام مــن شــربي للمســكر فهــذا غيــر صحيــح‬\n‫هــذه إجابتــي هــذا و قــد جــرت مخاطبــة هيئــة التحقيــق واالدعــاء العــام‬\n‫إلحضــار البينــة املثبتــة لصحــة التهــم املنســوبة للمدعــى عليهــم وذلــك‬\n‫باخلطــاب رقــم ( ‪ )34392880‬وتاريــخ ‪1434/2/17‬ه ـ إال إنــه لــم يحصــل‬\n\n\n                                                                                      ‫‪96‬‬\n\f     ‫جتــاوب وبعــد تدويــن مــا ســبق جــرى االطــاع علــى أقــوال املدعــى عليهــم‬\n     ‫أثنــاء اســتجوابهم واملدونــة علــى الصفحــات مــن (‪ )10‬وحتــى (‪ )15‬مــن‬\n     ‫ملــف التحقيــق األول فلــم أجــد فيهــا اعتراف ـ ًا للمدعــى عليهــم ‪.....‬و ‪.....‬‬\n     ‫بشــرب املســكر كمــا جــرى االطــاع علــى محضــر االستشــمام املــدون‬\n     ‫علــى الصفحــة السادســة مــن ملــف التحقيــق واملتضمــن أنــه مت استشــمام‬\n     ‫ال مــن ‪ .....‬و ‪ ......‬و ‪ .....‬و‪ .......‬وقــد تبــن انبعــاث رائحــة املســكر‬‫ك ً‬\n     ‫مــن أنفاســهم وأنهــم جميع ـ ًا بحالــة ســكر كمــا جــرى االطــاع علــى‬\n     ‫محضــر القبــض املــدون علــى اللفــة اخلامســة أنــه مت القبــض علــى املدعــى‬\n     ‫عليهــم بعــد حصــول ســوء تفاهــم بينهــم وبــن موظــف اجلــوازات ولــم‬\n     ‫يتضمــن هــذا احملضــر إثبــات كــون املدعــى عليهــم يف حالــة ســكر‬\n     ‫مــن عدمــه كمــا جــرى االطــاع علــى نســخة خطــاب مديــر جــوازات‬\n     ‫جســر امللــك فهــد املرفقــة علــى اللفــة رقــم (‪ )30‬فوجــدت أنهــا مجــرد‬\n     ‫نســخة خلطــاب ال ميكــن االســتناد عليهــا يف اإلثبــات مــن عدمــه فبنــاء‬\n     ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه الثالــث‬\n     ‫‪.....‬بشــرب املســكر والرقــص يف ســاحة اجلــوازات بطريقــة غيــر الئقــة‬\n     ‫والتلفــظ علــى رجــل األمــن واملــرء مؤاخــذ بإقــراره كمــا أقــر املدعــى‬\n     ‫عليــه الرابــع ‪.....‬بشــرب املســكر واملــرء مؤاخــذ بإقــراره ولقولــه صلــى‬\n     ‫اهلل عليــه وســلم « مــن شــرب اخلمــر فاجلــدوه « أخرجــه أحمــد وأبــو داوود‬\n     ‫وألن عمــر رضــي اهلل عنــه جلــد يف حــد اخلمــر ثمانــن جلــدة وكان ذلــك‬\n     ‫مبحضــر مــن املهاجريــن واألنصــار فلــم ينكــره أحــد فيهــم وحيــث إن‬\n     ‫العقوبــات التعزيريــة تتداخــل ( كشــاف القنــاع ‪ ) 113 / 14‬وحيــث‬\n     ‫أنكــر املدعــى عليهمــا األول والثانــي شــرب املســكر وال توجــد لهــم يف‬\n     ‫املعاملــة أي اعترافــات بذلــك وبنــاء علــى محضــر االستشــمام املرصــود‬\n\n\n‫‪97‬‬\n\f‫بعاليــة وبنــاء علــى مــا نــص عليــه أهــل العلــم مــن أنــه ال يحــد بوجــود رائحة‬\n‫اخلمــر منــه الحتمــال أنــه متضمــض بهــا أو ظنهــا مــاء فلمــا صــارت يف فيــه‬\n‫مجهــا ونحــو ذلــك واحلــد يــدرأ بالشــبهة لكــن يعــزر كحاضــر شــربها (‬\n‫كشــاف القنــاع ‪ ) 101 / 14‬وحيــث إنــه لــم يثبــت شــرب املدعــى عليــه‬\n‫الثاني‪.....‬للمســكر وبالتالــي فإنــه ال يثبــت قيامــه بقيــادة الســيارة حتــت‬\n‫تأثيــره لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه الثالــث ‪..........‬بشــرب‬\n‫املســكر والرقــص يف ســاحة اجلمــارك بطريقــة غيــر الئقــة والتلفــظ‬\n‫علــى رجــل األمــن وحكمــت عليــه لقــاء ذلــك بجلــده حــد املســكر‬\n‫ثمانــن جلــدة وســجنه عشــرة أيــام حتتســب منهــا املــدة التــي أوقــف فيهــا‬\n‫علــى ذمــة هــذه القضيــة كمــا ثبــت لــدي إدانــة املدعــى عليــه الرابــع‬\n‫‪..........‬بشــرب املســكر وحكمــت عليــه لقــاء ذلــك بجلــده حــد املســكر‬\n‫ثمانــن جلــدة ولــم يثبــت لــدي إدانــة املدعــى عليهمــا األول والثانــي بشــرب‬\n‫املســكر أو قيــادة الثانــي للســيارة حتــت تأثيــره وحكمــت بــدرء حــد‬\n‫املســكر عنهمــا وجلــد كل واحــد منهمــا تعزيــر ًا لقــاء تهمــة شــرب‬\n‫املســكر ســبعني جلــدة وصرفــت النظــر عــن بقيــة طلبــات املدعــي العــام‬\n‫وبعــرض احلكــم علــى املدعــى عليهــم قــرروا قناعتهــم بــه وقــرر املدعــي‬\n‫العــام االعتــراض واالكتفــاء مبــا يف أوراق املعاملــة فأجيــب لطلبه وباهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وبــه حــرر يف ‪1434/3/7‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام املكلــف برقــم‬\n‫‪ 33/1429529‬وتاريــخ ‪1434/3/17‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n‫‪ 34715102‬وتاريــخ ‪1434/3/22‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n\n\n                                                                                          ‫‪98‬‬\n\f     ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪.....‬املســجل برقــم ‪3457183‬‬\n     ‫وتاريــخ ‪1434/3/7‬ه ـ اخلــاص بدعوى‪/‬املدعــى العام ضــد‪-2.......... -1/‬‬\n     ‫‪ ..... -4.......... -3.....‬يف قضيــة مســكر وتلفــظ علــى رجــال االمــن وقــد‬\n     ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة‬\n     ‫القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n     ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n                                                                  ‫‪1434/5/8‬ه ـ ‪.‬‬\n\n\n\n\n‫‪99‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":92,"source_page_end":99,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"68eb3c68b74ec29c352bc34e5bd28c7913e44b6e23d1751f99c903e83548fb62","normalized_text_hash":"5c83ac1efdc5ee70c1716e368ab3c8ca7f9cd24770d007bd74d77a123a431aac","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p92-3457183"},{"id":"d9186bdb-e12d-5f35-b3d0-5c2516c6bfbf","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حيازة بقصد الشرب -قيادة السيارة حتت تأثير املسكر -هروب من رجال األمن -املدعى عليه مريض نفسي -التوقف يف نظر الدعوى حتى يتم التأكد من مسؤولية املدعى عليه اجلنائية-ورود تقرير املستشفى مبسؤولية املدعى عليه عن تصرفاته -تعزير املدعى عليه بالسجن واجللد .","document_number":"3442764","case_number":"33504822","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية وبرفقها قرار أصحاب الفضيلة قضاة الدائرة اجلزائية األولى وهم فضيلة القاضي","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/20","year":"1434","subject":"مسكر -شرب املسكر -حيازة بقصد الشرب -قيادة السيارة حتت تأثير املسكر -هروب من رجال األمن -املدعى عليه مريض نفسي -التوقف يف نظر الدعوى حتى يتم التأكد من مسؤولية املدعى عليه اجلنائية-ورود تقرير املستشفى مبسؤولية املدعى عليه عن تصرفاته -تعزير املدعى عليه بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫رقم الصك‪ 3442764:‬تاريخه‪1434/2/20:‬هـ‬\n                   ‫رقم الدعوى‪33504822:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34387291:‬تاريخه‪1434/12/25:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬حيــازة بقصــد الشــرب ‪ -‬قيــادة الســيارة حتــت‬\n‫تأثيــر املســكر ‪ -‬هــروب مــن رجــال األمــن ‪ -‬املدعــى عليــه مريــض نفســي‬\n‫‪ -‬التوقــف يف نظــر الدعــوى حتــى يتــم التأكــد مــن مســؤولية املدعــى‬\n‫عليــه اجلنائيــة‪-‬ورود تقريــر املستشــفى مبســؤولية املدعــى عليــه عــن‬\n                    ‫تصرفاتــه ‪ -‬تعزيــر املدعــى عليــه بالســجن واجللــد ‪.‬‬\n\n\n\n\n             ‫‪ -1‬املادة الثالثة والثمانني من نظام املرافعات الشرعية ‪.‬‬\n ‫‪ -2‬املادة الرابعة والتسعني بعد املائة من نظام اإلجراءات اجلزائية ‪.‬‬\n‫‪ -3‬املــادة اخلامســة والتســعني بعــد املائــة مــن نظــام اإلجــراءات‬\n                                                        ‫الـجــزائـ ــية ‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحيازتــه‬\n‫بقصــد الشــرب وقيــادة الســيارة حتــت تأثيــر املســكر والهــروب مــن‬\n‫رجــال األمــن و طلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد املســكر‬\n‫وتعزيــره وتشــديد العقوبــة لقــاء تعــدد ســوابقه‪ ،‬حيــث تلقــت الدوريــات‬\n‫األمنيــة بالغ ـ ًا عــن مركبــة بقيــادة املدعــى عليــه تقــوم مبضايقــة املــارة‬\n‫يف الطريــق ويحــاول صدمهــم أثنــاء الســير ومت متابعتــه مــن قبــل الدوريــة‬\n\n                                                                                      ‫‪100‬‬\n\f      ‫وقــام باملراوغــة بــن املركبــات بســرعة عاليــة فتــم اســتيقافه وكان يف‬\n      ‫حالــة غيــر طبيعيــة وبتفتيشــه لــم يعثــر علــى أي ممنوعــات معــه وبتفتيــش‬\n      ‫املركبــة عثــر علــى قــارورة فيهــا مــادة مســكرة فتــم القبــض عليــه‬\n      ‫وجــرى إتــاف القــارورة وباستشــمامه تبــن انبعــاث رائحــة املســكر‬\n      ‫مــن أنفاســه‪ ،‬تبــن لناظــر القضيــة مــن خــال تصرفــات املدعــى عليــه‬\n      ‫أثنــاء اجللســة أنــه يعانــي مــن أمــراض نفســية ‪ ،‬جــرى الكتابــة ملجمــع‬\n      ‫األمــل للصحــة النفســية للكشــف علــى املدعــى عليــه واإلفــادة عــن‬\n      ‫أهليتــه ومســؤوليته اجلنائيــة ‪ ،‬لــم يــرد جوابهــم بعــد مضــي مــدة طويلــة‪،‬‬\n      ‫قــرر القاضــي التوقــف يف نظــر الدعــوى حتــى ورود التقريــر‪ ،‬بعــد ورود‬\n      ‫التقريــر املثبــت عــدم وجــود أعــراض مرضية نفســية وأنه بحالتــه الراهنة‬\n      ‫مســؤول عــن تصرفاتــه جــرى عرض الدعوى علــى املدعى عليه‪،‬فأنكر‬\n      ‫شــرب املســكر وقيــادة الســيارة حتــت تأثيــر املســكر‪ ،‬وصــادق علــى‬\n      ‫حيازتــه وهروبــه مــن رجــال األمــن ‪ ،‬إثبــات إدانــة املدعــى عليــه بحيــازة‬\n      ‫املســكر وهروبــه مــن رجــال األمــن ‪ ،‬وبنــاء علــى مــا تقــدم حكمــت‬\n      ‫احملكمــة بتعزيــره لقــاء ذلــك كلــه بســجنه تعزيــرا مــدة ســنة وجلــده‬\n      ‫مائــة جلــدة علــى دفعتــن كل دفعــة خمســون جلــدة وقنــع املدعــى عليــه‬\n      ‫واعتــرض املدعــي العــام بالئحــة لــم يقدمهــا يف املــدة املقــررة نظام ـاً‪،‬‬\n           ‫ُصـ ّـدق احلكــم مــن الدائــرة اجلزائيــة األولــى مبحكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪..........‬القاضــي باحملكمــة اجلزئيــة بالدمــام ففــي يــوم الثالثــاء‬\n      ‫املوافــق ‪1434/2/19‬ه ـ افتتحــت اجللســة الســاعة التاســعة والنصــف‬\n\n‫‪101‬‬\n\f‫صباح ـ ًا بنــاء علــى املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزئيــة بالدمــام برقــم ‪ 331969046‬وتاريــخ ‪1433/11/1‬ه ـ واملقيــدة‬\n‫بــوارد مكتبنــا برقــم ‪ 331464654‬وتاريــخ ‪1433/ 8 /4‬ه ـ واملتعلقــة‬\n                                            ‫بدعــوى املدعــي العــام ضــد ‪..... /‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ ..... /‬وادعــى على احلاضر معه ‪..... /‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي ‪ .....‬قائــا يف دعــواه فباالطــاع علــى‬\n‫محضــر تنفيــذ مهمــة املعــد مــن قبــل رجــال الضبــط اجلنائــي بالدوريــات‬\n‫األمنيــة بالدمــام تبــن أنــه يف يــوم الســبت ‪1433/7/12‬ه ـ تلقــت‬\n‫الدوريــات األمنيــة بالغ ـ ًا مــن العمليــات عــن مركبــة تقــوم مبضايقــة‬\n‫املــارة يف الطريــق ويحــاول صدمهــم أثنــاء الســير قبــل كبــري ‪.....‬جنوبـ ًا‬\n‫ثــم دخــل أحــد احملطــات وقــام بالتشــاجر مــع بعــض العمالــة وبعدهــا‬\n‫خــرج بســيارته ‪ ،‬فتــم متابعــة الدوريــة لــه إلــى أن وصــل إلــى طريــق‬\n‫رأس تنــورة جنوب ـ ًا ولــم يقــف وقــام باملراوغــة بــن املركبــات بســرعة‬\n‫عاليــة ومتهــورة ومت متابعتــه مــن قبــل الدوريــة ورفــض الوقــوف ثــم دخــل‬\n‫طريــق إلــى طريــق مقابــل معــارض الســيارات ثــم نــزل مــع كبــري علــى‬\n‫طريــق باجتــاه فتــم اســتيقافه بعــد إشــارة حــي (‪ )..‬مقابــل مســجد وكان‬\n‫الشــخص يف حالــة غيــر طبيعيــة وبتفتيشــه لــم ُيعثــر علــى أي ممنوعــات‬\n‫معــه وبتفتيــش املركبــة ُعثــر علــى قــارورة صغيــرة فيهــا أقــل مــن الربــع‬\n‫مــن احملتمــل أن تكــون مــادة مســكرة فتــم القبــض عليــه ‪ ،‬وقــد جــرى‬\n‫إتــاف القــارورة املضبوطــة مــع املذكــور وفــق احملضــر املــدون مــن قبــل‬\n‫جهــة الضبــط ‪ ،‬وباستشــمامه تبــن انبعــاث رائحــة املســكر من أنفاســه‪.‬‬\n                            ‫وبسماع أقواله أنكر شربه للمسكر وحيازته‪.‬‬\n‫وانتهــى التحقيــق إلــى اتهــام املدعــى عليــه بشــرب املســكر وحيازتــه‬\n\n\n                                                                                    ‫‪102‬‬\n\f      ‫لقــارورة مــاء صحــة صغيــرة بهــا الربــع مــن املســكر بقصــد الشــرب ‪،‬‬\n                    ‫وقيــادة الســيارة حتــت تأثيــره ‪ ،‬والهــروب مــن رجــال األمــن‪.‬‬\n                                                         ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n                                 ‫‪ -1‬محضر تنفيذ املهمة املرفق على اللفة رقم (‪.)2‬‬\n      ‫‪ -2‬محضــر االستشــمام املــدون علــى الصفحــة رقــم (‪ )8‬مــن دفتــر‬\n                                    ‫األحــوال األمنيــة املوحــد املرفــق لفــة رقــم (‪.)1‬‬\n      ‫‪ -3‬محضــر اإلتــاف املــدون علــى الصفحــة رقــم (‪ )10‬مــن دفتــر األحــوال‬\n                                                    ‫األمنيــة املوحــد املرفــق لفــة رقــم (‪.)1‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه ‪ -‬وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫ـب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب مــا يلــي ‪:‬‬‫شــرع ًا ‪ -‬فعــلٌ محــرم ومعاقـ ٌ‬\n      ‫أو ًال ‪ /‬إثبــات إدانتــه مبــا ُنســب إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n      ‫تزجــره وتــردع غيــره ‪ ،‬وتشــديد العقوبــة لقــاء ســوابقه املتكــررة التــي‬\n      ‫لــم تردعــه عقوباتهــا الســابقة وفــق تعميــم نائــب وزيــر الداخليــة رقــم‬\n                                                   ‫(‪ )93958‬وتاريــخ ‪1429/8/23‬هــ‪.‬‬\n      ‫ثاني ـ ًا ‪ /‬إثبــات قيادتــه للســيارة حتــت تأثيــر املســكر وفــق الفقــرة رقــم‬\n      ‫(‪ )8‬مــن اجلــدول رقــم (‪ )1‬امللحــق بنظــام املــرور وإفهامــه بــأن عقوبتــه‬\n      ‫الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )68‬مــن نظــام املــرور تقــرر مــن‬\n      ‫اجلهــة املختصــة وفــق الفقــرة (‪ )2‬مــن قــرار مجلــس الوزراء رقــم (‪ )315‬يف‬\n      ‫‪1428/10/24‬ه ـ هــذه دعــواي وعليــه فقــد جــرى إحضــار املدعــى عليــه‬\n      ‫عــدة جلســات إال أنــه ظهــر لــي وتبــن لــي مــن خــال جتاوبــه يف اجللســة‬\n      ‫ومــن خــال بعــض تصرفاتــه أثنــاء اجللســة أن املدعــى عليــه يعانــي مــن‬\n      ‫أمــراض نفســية وإبــراء للذمــة جــرى الكتابــة ملجمــع للصحــة النفســية‬\n      ‫بكتابنــا رقــم ‪ 33/1576223‬وتاريــخ ‪1433/8/20‬ه ـ للكشــف علــى‬\n\n\n‫‪103‬‬\n\f‫املدعــى وبيــان أهليتــه ومســؤوليته اجلنائيــة إال أنــه لــم تــرد إلينــا إفــادة‬\n‫مــن مجمــع األمــل للصحــة النفســية حتــى تاريــخ ‪1434/2/19‬ه ـ وهــذه‬\n‫مــدة طويلــة تلحــق الضــرر باملدعــى عليــه وخصوصــا كــون املدعــى‬\n‫عليــه ســجينا وبنــاء علــى املــادة الثالثــة والثمانــن مــن نظــام املرافعــات‬\n‫الشــرعية ولوائحــه التنفيذيــة ونظــرا إلــى أن التأكــد مــن قبــل القاضــي‬\n‫علــى ســامة املدعــى عليــه واالطمئنــان إلــى كمــال قــواه العقليــة‬\n‫والنفســية مــن األمــور املهمــة والضروريــة ونظــرا إلــى أن إطالــة املــدة يف‬\n‫القضيــة يلحــق الضــرر باملدعــى عليــه ألنــه ســجني والتقريــر الطبــي لــم‬\n‫يــرد والشــريعة اإلســامية جــاءت برفــع الضــرر وال ضــرر وألن الفصــل‬\n‫يف هــذه القضيــة متوقــف علــى التقريــر الطبــي لــذا ولــكل مــا ســبق فقــد‬\n‫قــررت التوقــف يف هــذه القضيــة وبذلــك حكمــت وبعــرض احلكــم علــى‬\n‫املدعــي العــام قــرر املدعــي العــام االعتــراض علــى احلكــم بــدون الئحــة‬\n‫اعتراضيــة ورفعــه حملكمــة االســتئناف مكتفيــا مبــا يف أوراق املعاملــة‬\n‫وعليــه فقــد قــررت رفــع املعاملــة كاملــة حملكمــة االســتئناف لتدقيــق‬\n‫احلكــم وختمــت يف الســاعة العاشــرة وعلــى ذلــك جــرى التوقيــع وبــاهلل‬\n‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                         ‫‪ .‬حــرر يف ‪1434/2/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/5/ 19‬ه ـ‬\n‫افتتحــت اجللســة الســاعة التاســعة والنصــف صباحـ ًا وفيهــا عــادت إلينــا‬\n‫املعاملــة مــن مقــام محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا‬\n‫قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة األولــى وهــم فضيلــة‬\n      ‫القاضــي ‪ ..... /‬وفضيلــة القاضــي ‪ ..... /‬وفضيلــة القاضــي ‪..... /‬‬\n‫الصــادر منهــم برقــم ‪34199521‬وتاريــخ ‪1434/04/28‬ه ـ ونــص احلاجــة‬\n\n\n                                                                                        ‫‪104‬‬\n\f      ‫منــه بعــد املقدمــة مــا يلــي ‪ ( :‬لوحــظ أن فضيلتــه أوقــف النظــر يف هــذه‬\n      ‫القضيــة ولــم يحــدد مــدة اإليقــاف حســب منطــوق املــادة املشــار إليهــا‬\n      ‫ملالحظــة مــا ذكــر وإكمــال الــازم ومــن ثــم إعــادة املعاملــة ) ونظــرا‬\n      ‫لوجاهــة مــا ذكــره أصحــاب الفضيلــة وعليــه فيكــون قــرار التوقــف‬\n      ‫يف هــذه القضيــة مبــا يلــي‪ :‬قــررت التوقــف عــن النظــر يف هــذه القضيــة‬\n      ‫إلــى حــن ورود التقريــر الطبــي للمدعــى عليــه‪ .‬وبذلــك حكمــت وأمــرت‬\n      ‫بإحلــاق ذلــك بالقــرار وســجله وإعــادة املعاملــة ألصحــاب و أحيــط‬\n      ‫أصحــاب الفضيلــة علم ـ ًا بأنــي قمــت بالكتابــة مــرة أخــرى ألجــراء‬\n      ‫الفحــص علــى املدعــى عليــه وذلــك بتاريــخ ‪1434/04/14‬ه ـ وحتــى‬\n      ‫تاريخ‪1434/05/19‬ه ـ لــم يردنــا التقريــر الطبــي واهلل املوفــق وصلــى‬\n                     ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                   ‫‪1434/5/ 19‬هـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هذا اليوم اخلميــس املوافق ‪1434/08/25‬هـ‬\n      ‫افتتحــت اجللســة يف الســاعة العاشــرة والنصــف صباحــا وفيهــا حضــر‬\n      ‫الطرفــان وقــد افتتحــت بنــاء علــى مــا وردنــا مــن مجمــع للصحــة النفســية‬\n      ‫بالدمــام تقريــر اللجنــة النفســية برقــم (‪ ).....‬وتاريــخ ‪1434/7/26‬ه ـ‬\n      ‫املتضمــن مــا نصــه ‪ « :‬اســم املريــض ‪..... /‬رقــم الهويــة (‪ ).....‬بالفحــص‬\n      ‫علــى املذكــور مــن قبــل اللجنــة النفســية يف يــوم األحــد وتاريــخ‬\n                                                                    ‫‪1434/07/23‬ه ـ‬\n      ‫تبــن عــدم وجــود أعــراض مرضيــة نفســية أو عقليــة يف الوقــت الراهــن‬\n                                      ‫وهــو بحالتــه الراهنــة مســئول عــن تصرفاتــه ‪.‬‬\n      ‫عضــو اللجنــة د‪..... /‬توقيعــه ‪ ،‬عضــو اللجنــة أ‪ ،..... /‬توقيعــه ‪ ،‬عضــو‬\n      ‫اللجنــة د‪..... /‬توقيعــه ‪ ،‬رئيــس اللجنــة الطبيــة د‪..... /‬توقيعــه ‪. ».‬أ‪.‬ه ـ‬\n\n\n‫‪105‬‬\n\f‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائــا مــا ذكره‬\n‫املدعــي مــن قيامــي بشــرب املســكر وأننــي قمــت بقيــادة الســيارة حتــت‬\n‫تأثيــره كل ذلــك غيــر صحيــح ومــا ذكــره مــن وجــود قــارورة مــاء صحــة‬\n‫صغيــرة بهــا مســكر بالســيارة فصحيــح إال أنهــا ليســت لــي فهــي‬\n‫لصاحــب الســيارة والســيارة ليســت لــي ومــا ذكــره املدعــي العــام مــن‬\n‫هروبــي مــن رجــال األمــن فصحيــح هكــذا أجــاب كمــا جــرى اطالعــي‬\n‫علــى ســوابق املدعــى عليــه وهــي (‪ )3‬شــرب املســكر وعــدد(‪ )1‬ســرقة‬\n‫ســيارات وعــدد (‪ )1‬حيــازة واســتعمال مخــدرات وبعرضهــا علــى املدعــى‬\n‫عليــه صــادق علــى صحتهــا ثــم جــرى ســؤال املدعــي العــام هــل لديــك بينة‬\n‫علــى دعــواك فيمــا يتعلــق بشــرب املســكر وقيــادة الســيارة حتــت تأثيــر‬\n‫املســكر فأجــاب قائــا ليــس لــدي بينــة علــى ذلــك ســوى مــا يف أوراق‬\n‫املعاملــة هكــذا أجــاب ثــم جــرى اطالعــي علــى أوراق املعاملــة كمــا‬\n‫جــرى اطالعــي علــى محضــر تنفيــذ مهمــة وتســليمها جلهــة االختصــاص‬\n                    ‫املرفــق باملعاملــة لفــة رقــم (‪ )4-3‬واملتضمــن مــا نصــه ‪:‬‬\n‫« أثنــاء مســح الدوريــة تلقينــا بــاغ مــن عمليــات أمــان عــن مركبــة‬\n‫والشــخص املوضــح بعاليــه أنــه يضايــق املــارة يف الطريــق ويجــول أثنــاء‬\n‫الســير قبــل كبــري جنــوب ثــم دخــل محطــة ‪.....‬عشــرين وقــام مبهاوشــت‬\n‫العمــال داخــل احملطــة ثــم حلظــه الدوريــة قبــل تنــورة جنــوب وتابعــه ولــم‬\n‫يقــف وثــم يــراوغ بــن املركبــات بســرعة عاليــة ومتهــور ومت متابعتــه‬\n‫مــن قبــل الدوريــة ورفــض الوقــف وحــول اســتيقافه ورفــض ثــم دخــل مــع‬\n‫مخــرج ومت متابعتــه حتــى نــزل مــع طريــق مقابــل املعــارض جنــوب ثــم نــزل‬\n‫مــع كبــري علــى طريــق امللــك فهــد باجتــاه الدمــام ومت اســتيقافه بعــد‬\n‫إشــارة (‪ )..‬مقابــل مســجد وكان الشــخص مــن احملتمــل يف حالــة غيــر‬\n\n\n                                                                                     ‫‪106‬‬\n\f      ‫طبيعيــة كان يســبب خطــر علــى املاريــن واملرتاديــن للطريــق ومت رفــع‬\n      ‫الشــخص واملركبــة للعمليــات بــدون ملخصــات ومت تفتيــش املركبــة‬\n      ‫والشــخص عثــر علــى قــارورة صغيــرة عصيــر فيهــا أقــل مــن الربــع‬\n      ‫محتمــل مــادة مســكرة « أ‪.‬هــ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n      ‫قائــا مــا جــاء يف احملضــر مــن أنــي كنــت يف حالــة غيــر طبيعيــة فغيــر‬\n      ‫صحيــح هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫ونظــرا ملــا قــرره الطرفــان ومــا مت رصــده وضبطــه أعــاه وبنــاء علــى‬\n      ‫إقــرار املدعــى عليــه بوجــود قــارورة مــاء صحــة صغيــرة بهــا مســكر‬\n      ‫وهروبــه مــن رجــال األمــن واملــرء مؤاخــذ بإقــراره وال عــذر ملــن أقــر‬\n      ‫ونظــرا إلــى أن دفعــه بــأن القــارورة ليســت لــه دفــع غيــر معتبــر وذلــك‬\n      ‫لوجــود قرينــة وهــي هروبــه مــن رجــال األمــن ونظــرا إلــى لتوجــه التهمــة‬\n      ‫ضــد يف شــربه للمســكر وقيادتــه للســيارة حتــت تأثيــر املســكر وتتمثل‬\n      ‫الشــبهة يف إقــراره بوجــود قــارورة املســكر وهروبــه مــن رجــال األمــن‬\n      ‫وســوابقه املماثلــة لشــرب املســكر وكل هــذه قرائــن تــدل علــى الشــبهة‬\n      ‫القويــة ضــده يف شــرب املســكر وتوجــه التهمــة يف شــرب املســكر‬\n      ‫هــو توجــه التهمــة يف عودتــه لشــرب املســكر ونظــرا إلــى أن احلــدود‬\n      ‫تــدرأ بالشــبهات ونظــرا إلــى أن ســوابق املدعــى عليــه املذكــورة أعــاه‬\n      ‫تســتوجب التشــديد يف عقوبــة املدعــى عليــه لــذا ولــكل مــا ســبق ‪ :‬فقــد‬\n      ‫ثبــت لــدي إدانــة املدعــى عليــه مبــا نســب إليــه مــن حيــازة قــارورة مــاء‬\n      ‫صحــة صغيــرة بهــا مســكر بقصــد الشــرب وهروبــه مــن رجــال األمــن‬\n      ‫وبذلــك حكمــت وتوجهــت التهمــة يف شــربه للمســكر وقيــادة الســيارة‬\n      ‫حتــت تأثيــر املســكر وعودتــه لشــرب املســكر وبذلــك وحكمــت عليــه‬\n      ‫لقــاء ذلــك بســجنه تعزيــرا مــدة ســنة يحتســب منهــا مــا أمضــاه موقوفــا‬\n\n\n‫‪107‬‬\n\f‫يف هــذه القضيــة وجلــده تعزيــرا مائــة جلــدة علــى دفعتــن كل دفعــة‬\n                  ‫خمســون جلــدة بــن كل دفعــة والتــي تليهــا عشــرة أيــام ‪.‬‬\n‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه قناعتــه باحلكــم‬\n‫وقــرر املدعــي العــام االعتــراض علــى احلكــم بالئحــة اعتراضيــة فأجبتــه‬\n‫لطلبــه وأفهمــت املدعــي العــام بــأن عليهــم مراجعــة احملكمــة يف يــوم‬\n‫األربعــاء املوافــق ‪1434/ 09 /02‬ه ـ الســتالم نســخة مــن احلكــم لتقــدمي‬\n‫الئحتــه االعتراضيــة خــال ثالثــن يومــا مــن تاريــخ االســتالم وإال ســقط‬\n‫حقــه يف طلــب االســتئناف وختمــت يف الســاعة احلاديــة عشــرة صباحــا‬\n‫وعلــى ذلــك جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n         ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/ 08 /25‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده و بعــد ففــي يــوم األربعــاء املوافــق ‪ 1434/09/02‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09:00‬وهــذا اليــوم هــو اليــوم احملــدد لتســليم‬\n‫املدعــي العــام نســخة مصــورة مــن قــرار احلكــم إال أنــه لــم يحضــر وقــد‬\n‫مت االنتهــاء مــن قــرار احلكــم وعليــه فقــد مت إيــداع نســخة مصــورة مــن‬\n‫قــرار احلكــم يف املعاملــة يف هــذا اليــوم نفســه ويعــد اإليــداع بدايــة مليعــاد‬\n‫الثالثــن يومـ ًا املقــررة لطلــب اســتئناف احلكــم وللمعلوميــة فقــد جــرى‬\n‫حتريــره وختمــت يف الســاعة ‪ 09:30‬وعلــى ذلــك جــرى التوقيــع وبــاهلل‬\n‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                        ‫حــرر يف ‪1434/09/02‬ه ـ‬\n‫احلمــد هلل وحــده و بعــد ففــي يــوم الثالثــاء املوافــق ‪1434/10/06‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09:00‬و قــد انتهــت املــدة املنصــوص عليهــا يف‬\n‫املــادة الرابعــة والتســعني بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة ولــم‬\n‫يتقــدم املدعــي العــام بالئحتــه االعتراضيــة خــال هــذه املــدة لــذا قــررت‬\n\n\n                                                                                         ‫‪108‬‬\n\f      ‫رفــع كامــل املعاملــة حملكمــة االســتئناف وفقــا ملــا نصــت عليه اخلامســة‬\n      ‫والتســعون بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة و للمعلوميــة فقــد‬\n      ‫جــرى حتريــره وختمــت يف الســاعة ‪ 09:30‬وعلــى ذلــك جــرى التوقيــع‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم حــرر يف ‪ 1434/10/06‬ه ـ‬\n      ‫احلمد هلل وحده وبعد ‪ . . .‬فقد اطلعنـا نحن قـضـاة الدائـرة اجلـزائيـة األولى‬\n      ‫يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم ‪34/1669414‬‬\n      ‫وتاريــخ ‪1434/10/27‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪342502891‬‬\n      ‫وتاريــخ ‪1434/11/4‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ ‪.....‬املســجل برقــم ‪ 3442764‬وتاريــخ ‪1434/2/20‬ه ـ‬\n      ‫اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪........../‬يف قضيــة مســكر والهــروب‬\n      ‫مــن رجــال األمــن وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه ‪ .‬حيــث ســبق دراســة القــرار وصــورة ضبطــه وباالطــاع‬\n      ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء‬\n      ‫علــى قرارنــا رقــم‪ 34251453‬يف ‪1434/6/26‬ه ـ قررنــا املصادقــة علــى‬\n      ‫احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                  ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/12/23‬ه ـ ‪.‬‬\n\n\n\n\n‫‪109‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":100,"source_page_end":109,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"61147a8715644cb1428af5da7379b605012864604301d846c9db509ee7cf7d22","normalized_text_hash":"50a510323af4c3a19d93b6734720f394bf82ab5edc688b2e861dce02824866fb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p100-3442764"},{"id":"f173d19c-192e-5f0b-a6bf-ad03539bb4ac","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -وفاة املدعى عليه -رد الدعوى -انقضاء الدعوى بوفاة املدعى عليه .","document_number":"3447361","case_number":"33547013","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/25","year":"1434","subject":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -وفاة املدعى عليه -رد الدعوى -انقضاء الدعوى بوفاة املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3447361 :‬تاريخه‪1434/2/25 :‬هـ‬\n                    ‫رقم الدعوى‪33547013:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34203125:‬تاريخه‪1434/05/01:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬قيــادة ســيارة حتــت تأثيــر املســكر ‪ -‬وفــاة املدعــى‬\n             ‫عليــه ‪ -‬رد الدعــوى ‪ -‬انقضــاء الدعــوى بوفــاة املدعــى عليــه ‪.‬‬\n\n\n\n\n                 ‫‪ -1‬األصل براءة الذمة وال يعدل عن ذلك إال بدليل ‪.‬‬\n‫‪ -2‬الفقــرة الرابعــة مــن املــادة الثانيــة والعشــرين مــن نظــام اإلجــراءات‬\n                                                                    ‫اجلزائيــة ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا بتنــاول األول املســكر وقيــادة‬\n‫املركبــة حتــت تأثيــره والثانــي بتنــاول املســكر وطلــب إثبــات مــا أســند‬\n‫إليهمــا واحلكــم عليهمــا بحــد املســكر وإفهــام املدعــى عليــه األول بــأن‬\n‫عقوبتــه عائــدة للجهــة املختصــة لقيــادة املركبــة حتــت تأثيــر املســكر‬\n‫‪،‬حيــث قبــض علــى املدعــى عليهمــا إثــر ورود بــاغ مــن أحــد املواطنــن‬\n‫باســتيقافه وهــو يقــود ســيارته برفقــة أهلــه مــن قبــل املدعــى عليهمــا وقــد‬\n‫اتضــح أنهمــا بحالــة غيــر طبيعيــة وبحوزتهما قارورة بداخلهــا مادة العرق‬\n‫املســكر كمــا اتضــح انبعــاث رائحــة املســكر منهمــا ‪ ،‬أنكــر املدعــى‬\n‫عليــه الثانــي الدعــوى وأفــاد بــأن املدعــى عليــه األول قــد تــويف وصــدرت‬\n‫لــه شــهادة وفــاة وأبــرز نســختها لــدى القاضــي ‪،‬وحيــث إن املدعــى عليــه‬\n\n                                                                                      ‫‪110‬‬\n\f      ‫الثانــي أنكــر الدعــوى وليــس للمدعــي العــام بينــة عليــه ســوى محضــر‬\n      ‫القبــض وإثبــات احلالــة ولــم يتضمنــا بــأن املدعــى عليــه الثانــي بحالــة غيــر‬\n      ‫طبيعيــة ‪،‬ومبــا أن األصــل بــراءة الذمــة حكمــت احملكمــة بــرد دعــوى‬\n      ‫املدعــي العــام ضــده لعــدم كفايــة األدلــة وقنــع املدعــى عليــه واعتــرض‬\n      ‫املدعــي العــام بالئحــة ‪ ،‬أمــا املدعــى عليــه األول فقــد ورد جواب األحوال‬\n      ‫املدنيــة باملدينــة املنــورة وبرفقــة نســخة موثقــة مــن شــهادة وفــاة املدعــى‬\n      ‫عليــه األول ‪،‬وبنــاء علــى الفقــرة الرابعــة مــن املــادة الثانيــة والعشــرين مــن‬\n      ‫نظــام اإلجــراءات اجلزائيــة ‪،‬فــإن الدعــوى العامــة تكــون منقضيــة بحــق‬\n                 ‫املدعــى عليــه األول وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n      ‫‪.....‬القاضــي باحملكمــة اجلزئيــة باملدينــة املنــورة حــاال وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة الرئيــس برقــم ‪1433/8/25 33547013‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331603329‬وتاريــخ ‪1433/8/25‬هـ افتتحت‬\n      ‫اجللســة اخلاصــة بالئحــة الدعــوى العامــة مــن املدعــي العــام ‪ .....‬ضــد‬\n      ‫املدعــى عليهمــا ‪ ..... -1‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪..... -2).....‬ســعودي اجلنســية بالســجل املدنــي رقــم (‪ ).....‬املتضمنــة أنــه‬\n      ‫بتاريــخ ‪1433/6/30‬ه ـ قبــض علــى املدعــى عليهمــا مــن قبــل دوريــات‬\n      ‫األمــن مبوجــب محضرهــم رقــم ‪.....‬املتضمــن دعــوى املواطــن ‪.....‬ضدهمــا‬\n      ‫باســتيقافه أثنــاء ســيره بســيارته مــع أهلــه وقــد اتضــح أن املدعــى عليهمــا‬\n      ‫بحالــة غيــر طبيعيــة وبحوزتهمــا قــارورة عصيــر بداخلهــا مــادة العــرق‬\n      ‫املســكر وجــرى إثبــات حالــة املدعــى عليهمــا واتضــح أن رائحــة العــرق‬\n\n‫‪111‬‬\n\f‫املســكر تنبعــث منهمــا وانتهــى التحقيــق إلــى توجيــه االتهــام إلى املدعى‬\n‫عليــه األول بتنــاول العــرق املســكر وقيــادة املركبــة حتــت تأثيــر العــرق‬\n‫املســكر واتهــام املدعــى عليــه الثانــي بتنــاول العــرق املســكر وبالبحــث‬\n‫عــن ســوابقهما لــم يعثــر للمدعــى عليــه األول ‪.....‬علــى ســوابق مســجلة‬\n‫عليــه وعثــر للمدعــى عليــه الثانــي ‪.....‬علــى أربــع ســوابق ( فاحشــة لــواط‬\n‫‪ -‬مضاربــة ‪ -‬حيــازة أدوات اســتعمال أدوات مخــدرات ‪ -‬اســتعمال‬\n‫مخــدرات ) ويطلــب إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بإقامــة‬\n‫حــد املســكر وإثبــات إدانــة املدعــى عليــه األول ‪.....‬بقيــادة الســيارة حتــت‬\n‫تأثيــر املســكر وإفهامــه أن عقابــه علــى ذلــك عائــد للجهــة املختصــة‬\n‫ويف هــذه اجللســة حضــر املدعــى عليــه الثانــي ‪ .....‬املذكــور ولــم يحضــر‬\n‫املدعــى عليــه األول ‪.....‬املذكــور ثــم جــرى ســؤال املدعــى عليــه الثانــي‬\n‫‪.....‬عمــا جــاء يف دعــوى املدعــي العــام أجــاب صحيــح الســوابق املســجلة‬\n‫علــي وقــد أخــذت جزائــي عليهــا مــن الســابق وصحيــح أننــي كنــت‬\n‫راكبــا مــع املدعــى عليــه ‪.....‬يف الســيارة التــي كان يقودهــا و أمــا‬\n‫مــا جــاء يف دعــوى املدعــي العــام مــن اتهامــه لــي بتنــاول مــادة العــرق‬\n‫ا كمــا أن املدعــى عليــه ‪.....‬‬     ‫املســكر فغيــر صحيــح جملــة وتفصي ـ ً‬\n‫قــد تــويف رحمــه اهلل بعــد هــذه القضيــة يف شــهر رجــب مــن هــذا العــام‬\n‫هــذا مــا لــدي وعليــه أوقــع فســألت املدعــي العــام هــل لديــك بينــة علــى‬\n‫دعــواك وعمــا يذكــره املدعــى عليــه ‪.....‬مــن وفــاة املدعــى عليــه ‪.....‬قــال‬\n‫أمــا وفــاة املدعــى عليــه ‪.....‬فــا علــم لــي بذلــك وأطلــب حتديــد جلســة‬\n‫أخــرى حتــى نتحقــق ممــا ذكــره املدعــى عليــه احلاضــر عــن وفــاة املدعــى‬\n‫عليــه ‪.....‬وحتــى أحضــر بينتــي علــى املدعــى عليــه ‪.....‬فأجيــب لطلبــه‬\n‫وبتاريــخ ‪1434/1/25‬ه ـ حضــر املدعــي العــام واملدعــى عليــه ‪.....‬وقــدم‬\n\n\n                                                                                     ‫‪112‬‬\n\f      ‫لنــا املدعــى عليــه نســخة مــن شــهادة وفــاة برقــم ‪ .....‬يف ‪1433/7/29‬ه ـ‬\n      ‫مكتــوب فيهــا أســم املتوفــى ‪ ..........‬وتاريــخ الوفــاة يف ‪1433/7/21‬ه ـ‬\n      ‫وهــي نســخة غيــر موثقــة وبعــرض ذلــك علــى املدعــي العــام قــال لــم نبلــغ‬\n      ‫بوفــاة املدعــى عليــه ‪.....‬رســميا هــذا مــا لــدي فســألت املدعــي العــام هــل‬\n      ‫لديــك بينــة علــى املدعــى عليــه ‪.....‬قــال بينتــي مــا هــو مذكــور يف الئحــة‬\n      ‫الدعــوى العامــة مــن محضــر القبــض ومحضــر إثبــات حالــة هــذا مــا لــدي‬\n      ‫وبالرجــوع إلــى أوراق املعاملــة وجدنــا علــى اللفــة (‪ )2‬محضــر القبــض‬\n      ‫وليــس فيــه مــا يتضمــن تعاطــي املدعــى عليــه ‪.....‬للمســكر ســوى أنــه‬\n      ‫وجــدوا داخــل الســيارة علبــة بهــا مــادة غيــر طبيعيــة كمــا وجدنــا علــى‬\n      ‫الصحيفــة (‪ )11‬مــن ملــف التحقيــق (‪ )1‬محضــر إثبــات حالــة مــن قبــل‬\n      ‫شــخص واحــد واملتضمــن أنــه بإثبــات حالــة املدعــى عليهمــا اتضــح‬\n      ‫أنهمــا بحالــة طبيعيــة ومتزنــن يف كالمهــم وتصرفاتهــم وتنبعــث مــن‬\n      ‫أفواههــم رائحــة كريهــة احتمــال أن تكــون رائحــة العــرق املســكر‬\n      ‫وقــد وجدنــا علــى الصحيفــة (‪ )12‬مــن ذات امللــف اعترافــات املدعــى‬\n      ‫عليــه ‪.....‬وقــد تضمنــت اعترافــه بتعاطــي املســكر وحيازتــه لــه بغــرض‬\n      ‫الســكر وقيــادة الســيارة حتــت تأثيــر املســكر وأن املدعــى عليــه ‪.....‬‬\n      ‫لــم يتنــاول أي مــادة مســكرة وقــد اقتضــى النظــر التحقــق مــن صحــة‬\n      ‫نســخة شــهادة الوفــاة عــن طريــق مكاتبــة األحــوال املدنيــة فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وكامــل مجريــات القضيــة وحيــث‬\n      ‫أنكــر املدعــى عليــه ‪.....‬تعاطــي املســكر ولــم يكــن للمدعــي العــام مــن‬\n      ‫بينــة علــى املدعــى عليــه ‪.....‬ســوى مــا أورده مــن محضــر القبــض وإثبــات‬\n      ‫احلالــة وحيــث لــم يتضمــن احملضــران وجــود املدعــى عليــه ‪.....‬بحالــة‬\n      ‫غيــر طبيعيــة وإمنــا تضمــن محضــر إثبــات احلالــة انبعــاث رائحــة يحتمــل‬\n\n\n‫‪113‬‬\n\f‫أن تكــون رائحــة العــرق املســكر وهــو محضــر معــد مــن شــخص‬\n‫واحــد ولــم يجــزم معــده بوجــود رائحــة املســكر وإذا تطــرق االحتمــال‬\n‫بطــل االســتدالل وتلــك القرائــن ال ترقــى إلثبــات إدانــة املدعــى عليــه وال‬\n‫حتــى توجــه التهمــة ألن األصــل البــراءة وال يعــدل عــن ذلــك إال بدليــل‬\n‫ولــم يوجــد هــا هنــا ال ســيما وأن أقــوال املدعــى عليــه األول ‪.....‬قائــد‬\n‫الســيارة تضمنــت أن املســكر املضبــوط بالســيارة لــه وأنــه تعاطــاه وأن‬\n‫املدعــى عليــه ‪.....‬لــم يتعاطــى املســكر ولــكل مــا ســلف فلــم يثبــت لــدي‬\n‫إدانــة املدعــى عليــه ‪.....‬بتنــاول العــرق املســكر وحكمــت بــرد دعــوى‬\n‫املدعــي العــام ضــد املدعــى عليــه ‪.....‬لعــدم كفايــة األدلــة وأمــا مــا يخــص‬\n‫املدعــى عليــه ‪.....‬فقــد اقتضــى النظــر حتديــد جلســة أخــرى بعــد ورود‬\n‫اإلفــادة فيمــا يخــص شــهادة الوفــاة مــن األحــوال املدنيــة وســتكون‬\n‫اجللســة القادمــة مبشــيئة اهلل تعالــى يــوم الثالثــاء املوافــق ‪1434/2/26‬ه ـ‬\n‫الســاعة ‪ 11،15‬وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n‫القناعــة وقــرر املدعــي العــام املعارضــة وأســتعد بتقــدمي الئحــة اعتراضيــة‬\n‫وأفهــم باملراجعــة يف اجللســة القادمــة لتســليمه نســخة احلكــم حتتســب‬\n‫لــه بعــد ذلــك مــدة ثالثــن يومــا لتقــدمي الئحتــه فــإن انقضــت ولــم يتقــدم‬\n‫بالئحتــه فســيتم بعــث القــرار مــع كامــل متعلقــات حملكمــة االســتئناف‬\n‫بــدون الئحــة اعتراضيــة وبتاريــخ ‪1434/2/19‬ه ـ حضــر املدعــي العــام‬\n‫وقــد وردنــا كتــاب مديــر مكتــب األحــوال املدنيــة باملدينــة املنــورة‬\n‫فــرع العاليــة مــول رقــم ‪.....‬يف ‪1434/2/5‬ه ـ واملقيــد باحملكمــة برقــم‬\n‫‪ 34/236074‬يف ‪1434/2/16‬ه ـ واملتضمــن أنــه مت إكمــال الــازم وقد‬\n‫وجدنــا برفقــه نســخة موثقــة مــن شــهادة الوفــاة اخلاصــة باملدعــى عليــه‬\n‫‪.....‬املذكــور وأن تاريــخ الوفــاة يف ‪1433/7/21‬ه ـ فبنــاء علــى مــا تقــدم‬\n\n\n                                                                                       ‫‪114‬‬\n\f      ‫ومــا مت مؤخــرا وبنــاء علــى الفقــرة الرابعــة مــن املــادة الثانيــة والعشــرين‬\n      ‫مــن نظــام اإلجــراءات اجلزائيــة فــإن هــذه الدعــوى العامــة منقضيــة بحــق‬\n      ‫املدعــى عليــه األول ‪.....‬لوفاتــه وبذلــك حكمــت فقــرر املدعــي العــام‬\n      ‫القناعــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                    ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/19‬ه ـ‬\n                  ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪:‬‬\n      ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف‬\n      ‫مبكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى‬\n      ‫هــذه احملكمــة بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة باملدينــة‬\n      ‫املنــورة رقــم(‪ )34198733‬وتاريــخ (‪1434/3/21‬هــ) املرفــق بهــا‬\n      ‫القــرار رقم(‪)3447361‬وتاريخ(‪1432/2/25‬هـ)الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪...../‬القاضي احملكمــة اجلزائيــة باملدينــة املنــورة‪ ،‬املتضمــن‬\n      ‫دعــوى املدعــي العــام ضد‪...../‬ورفيقــه ســعوديي اجلنســية ‪ ،‬املتهمــن‬\n      ‫بتنــاول العــرق املســكر وقيــادة الســيارة حتــت تأثيــره ‪ ،‬احملكــوم فيــه‬\n      ‫مبــا دون باطنــه‪ ،‬وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة‬\n      ‫تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                                ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪115‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":110,"source_page_end":115,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e1eacbbfad8f45dbf048ed19d45c99037ead575db3217ebbb7a10f2cd14cea50","normalized_text_hash":"6666d145a5f2baac25ae672aba31e6be6e747e180bafa23be8743b72c44c193b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p110-3447361"},{"id":"8746e4a5-40b9-5140-9624-b57445e44931","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب مسكر -تعاطي حشيش -قيادة السيارة حتت تأثير املسكر -اشتراك احلشيش مع اخلمر يف مناط احلكم -إقامة حد املسكر -املنع من السفر .","document_number":"33455738","case_number":"33552912","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/25","year":"1434","subject":"مسكر -شرب مسكر -تعاطي حشيش -قيادة السيارة حتت تأثير املسكر -اشتراك احلشيش مع اخلمر يف مناط احلكم -إقامة حد املسكر -املنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33455738 :‬تاريخه‪1434/1/25 :‬هـ‬\n                    ‫رقم الدعوى‪33552912:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n  ‫االستئناف‪ 3410025:‬تاريخه‪1434/01/25:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب مســكر ‪ -‬تعاطــي حشــيش ‪ -‬قيــادة الســيارة حتــت تأثيــر‬\n‫املســكر ‪ -‬اشــتراك احلشــيش مــع اخلمــر يف منــاط احلكــم ‪ -‬إقامــة حــد‬\n                                              ‫املســكر ‪ -‬املنــع مــن الســفر ‪.‬‬\n\n\n\n\n                   ‫‪ -1‬قوله صلى اهلل عليه وسلم ( كل مسكر حرام ) ‪.‬‬\n            ‫‪ -2‬املادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n            ‫‪ -3‬املادة ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                                          ‫‪ -4‬املادة ‪ 68‬من نظام املرور ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وتعاطــي‬\n‫احلشــيش املخــدر وقيــادة الســيارة حتــت تأثيرهمــا وطلــب إثبــات مــا‬\n‫أســند إليــه واحلكــم عليــه بحــد املســكر ومعاقبتــه وتشــديد العقوبــة‬\n‫لقــاء قيــادة الســيارة حتــت تأثيــر املســكر وعــدم مباالتــه بــأرواح‬\n‫اآلخريــن ومنعــه مــن الســفر ‪،‬حيــث قبــض علــى املدعــى عليــه مــن قبــل‬\n‫الدوريــة األمنيــة إثــر وقــوع حــادث اصطــدام ســيارة بقيــادة املدعــى عليــه‬\n‫وأثبــت تقريــر الســموم الشــرعي إيجابيــة عينــة ســوائل املدعــى عليــه‬\n‫ملركبــات احلشــيش وصــادق املدعــى عليــه علــى الدعــوى ‪،‬وبنــاء علــى‬\n\n                                                                                    ‫‪116‬‬\n\f      ‫مــا تقــدم حكمــت احملكمــة بجلــده حــد املســكر ثمانــون جلــدة دفعــة‬\n      ‫واحــدة ومنعــه مــن الســفر ور ّد دعــوى املدعــي العــام بخصــوص معاقبــة‬\n      ‫املدعــى عليــه وإفهامــه أن عقوبــة قيــادة الســيارة حتــت تأثيــر املســكر‬\n      ‫عائــد للجهــة املختصــة وقنــع املدعــى عليــه واعتــرض املدعــي العــام بــدون‬\n                               ‫‪،‬وصــدق احلكــم محكمــة االســتئناف ‪.‬‬     ‫الئحــة ُ‬\n\n\n\n\n      ‫اجلزائيــة‬\n         ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة‬\n      ‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة يف محافظــة االحســاء برقــم ‪ 33552912‬وتاريــخ‬\n      ‫‪1433/08/27‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331622202‬وتاريــخ‬\n      ‫‪1433/08/27‬ه ـ ففــي يــوم الثالثــاء املوافق‪1433/11/09‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 10 : 00‬وفيهــا حضــر املدعــي العــام وادعــى ضــد‬\n      ‫احلاضــر ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬إنــه بتاريــخ‬\n      ‫‪1432/11/21‬ه ـ مت القبــض علــى املدعــى عليــه مــن قبــل إحــدى فــرق‬\n      ‫الدوريــات األمنيــة مبحافظــة االحســاء وذلــك إثــر وقــوع حــادث اصطــدام‬\n      ‫ســيارة مــن نــوع (‪ ).....‬ســنة صنعهــا(‪2009‬م) حتمــل اللوحــة رقــم (‪).....‬‬\n      ‫بقيــادة املدعــى عليــه (مت فــرز أوراق مســتقله للحــادث ومعاجلتهــا مــن‬\n      ‫قبــل جهــة االختصــاص) وقــد أثبــت تقريــر الســموم الشــرعي رقــم( ‪).....‬‬\n      ‫لعام‪1433‬ه ـ ايجابيــة عينــة ســوائله ملركبــات احلشــيش املخــدر و املــدرج‬\n      ‫مــن ضمــن املــواد احملظــورة يف اجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة و للمــواد الكحوليه (االيثيلي)‪.‬‬\n      ‫وباســتجوابه ‪ /‬أقــر بشــربه اخلمــر املســكر وتعاطيــه للحشــيش املخــدر‬\n\n‫‪117‬‬\n\f                                                ‫و قيادتــه الســيارة حتــت تأثيرهمــا‪.‬‬\n‫وقــد أســفر التحقيــق عــن توجيــه االتهــام لــه بشــرب اخلمــر املســكر‬\n‫وتعاطــي احلشــيش املخــدر وقيادتــه للســيارة حتــت تأثيرهمــا لألدلــة‬\n                                                                   ‫والقرائــن اآلتيــة‪:‬‬\n‫‪1‬ـ إقــراره املــدون علــى الصفحــة رقــم (‪ )3-1‬مــن ملــف التحقيــق املرفــق‬\n                                                              ‫علــى اللفــة رقــم (‪. )25‬‬\n                      ‫‪2‬ـ تقرير السموم الشرعي املرفق على اللفة رقم (‪. )13‬‬\n                    ‫‪3‬ـ محضر القبض املرفق صوره منه على اللفة رقم (‪. )5‬‬\n                        ‫وبالبحث عن سوابقه لم يعثر له على سوابق مسجلة ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكور ‪ -‬وهو بكامل أهليته املعتبرة شــرع ًا‬\n‫‪ -‬فعــل محــرم ومعاقــب علي ــه شــرع ًا نظامـ ًا يف ضــوء الفقــرة الثانيــة مــن‬\n‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n‫باملرســوم امللكــي الكــرمي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هـ ـ اطلــب‬\n                                  ‫إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪:‬‬\n                                                     ‫‪ .1‬بحد املسكر لقاء شربه له ‪.‬‬\n‫‪ .2‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن النظــام املشــار‬\n‫إليــه أعــاه لقــاء تعاطيــه احلشــيش املخــدر‪ ،‬وتشــديد العقوبــة عليــه لقــاء‬\n‫قيادتــه الســيارة حتــت تأثيــر شــرب اخلمــر املســكر و تعاطــي احلشــيش‬\n‫املخــدر وعــدم مباالتــه بــأرواح اآلخريــن اســتنادا لتعميــم صاحــب الســمو‬\n         ‫امللكــي أميــر املنطقــة الشــرقية رقــم (‪ )8019‬يف ‪1433/2/24‬ه ـ‬\n‫‪ .3‬منعــه مــن الســفر خــارج البــاد بعــد تنفيــذ محكوميتــه اســتناد ًا‬\n                           ‫للفقــرة األولــى مــن املــادة (‪ )56‬مــن ذات النظــام ‪.‬‬\n                     ‫‪ .4‬تأثير شرب اخلمر املسكر و تعاطي احلشيش املخدر‬\n\n\n                                                                                            ‫‪118‬‬\n\f      ‫‪ .4‬إثبــات قيادتــه للســيارة حتــت تأثيــر شــرب اخلمــر املســكر و تعاطــي‬\n      ‫احلشــيش املخــدر وإفهامــه بــأن عقابــه عائــد للجهــة املختصــة عمــا‬\n      ‫بالفقــرة األولــى مــن املــادة (‪ )68‬مــن نظــام املــرور الصــادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )85/‬و تاريــخ ‪1428/10/26‬هــ‪ .‬هــذه دعــواي وبســؤال‬\n      ‫املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي العــام مــن أنــه بتاريــخ‬\n      ‫‪1432/11/21‬ه ـ قبــض علــي مــن قبــل الدوريــات األمنيــة باألحســاء‬\n      ‫وذلــك إثــر وقــوع حــادث تصــادم وأنــه مت التحليــل لــي وأننــي أشــرب‬\n      ‫املســكر وأتعاطــى احلشــيش وأننــي قمــت قيــادة الســيارة حتــت تأثيرهما‬\n      ‫فهــذا كلــه صحيــح وأنــا تائــب هكــذا أجــاب وباالطــاع علــى املعاملــة‬\n      ‫وجــد فيهــا علــى لفــه ‪ 13‬تقريــر الســموم الشــرعية رقــم ‪.....‬واملتضمــن‬\n      ‫إيجابيــة عينــة البــول للمــواد الكحوليــة وملركبــات احلشــيش املخــدر‬\n      ‫واحملظــور دوليــا أ‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإقــرار‬\n      ‫املدعــى عليــه وحيــث إن املــرء مؤاخــذ بإقــراره وللتقريــر الشــرعي ولقــول‬\n      ‫النبــي صلــى اهلل عليــة وســلم (كل مســكر حــرام ) وحيــث إن احلشــيش‬\n      ‫يشــترك مــع اخلمــر يف منــاط احلكــم لذلــك كلــه فقــد ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه بشــرب اخلمــر وتعاطــي احلشــيش املخــدر وقيــادة الســيارة‬\n      ‫حتــت تأثيرهمــا ولــم يثبــت لــدي احليــازة لهمــا لذلــك كلــه فقــد حكمــت‬\n                                                                            ‫مبــا يلــي أوال‪:‬‬\n                        ‫جلد املدعى عليه ثمانون جلدة دفعة واحدة حد املسكر‬\n      ‫ثانيــا‪ :‬رد دعــوى املدعــي العــام بخصــوص معاقبــة املدعــى عليــه مبوجــب‬\n      ‫املــادة ‪ 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لعــدم ثبــوت‬\n                                                                                    ‫احليازة‬\n      ‫ثالثــا‪ :‬منــع املدعــى عليــه مــن الســفر خــارج اململكــة بعــد تنفيــذ‬\n\n\n‫‪119‬‬\n\f‫محكوميــة مــدة ســنتني وذلــك مبوجــب املــادة ‪ 56‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة رابعــا‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بقيادة‬\n‫الســيارة حتــت تأثيــر اخلمــر واحلشــيش وأفهمتــه بــأن عقابــه عائــد إلــى‬\n‫اجلهــة املختصــة وبنــاء علــى املــادة ‪ 68‬مــن نظــام املــرور هــذا مــا ظهــر لــي‬\n‫وبــه حكمــت وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليــه قــرر‬\n‫املدعــي العــام اعتراضــه وطلــب رفــع املعاملــة إلــى محكمــة االســتئناف‬\n‫بــدون الئحــة وأمــا املدعــى عليــه فقــرر قناعتــه بــه وبــه ختمــت اجللســة يف‬\n‫متــام الســاعة ‪ 10.30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/09‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قضــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء برقــم‬\n‫‪ 331943304‬وتاريــخ ‪1433/11/20‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n‫‪/33/2095075‬ج‪ 1‬وتاريــخ ‪1433/11/23‬ه ـ املرفــق بهــا القرار الصادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬املســجل برقــم ‪33455738‬‬\n‫وتاريــخ ‪1433/11/16‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪...../‬يف‬\n‫قضيــة مخــدرات ومســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه ؛ وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                             ‫وآلــه وصحبــه وســلم حــرر يف ‪1434 /1/11‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                         ‫‪120‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":116,"source_page_end":120,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1da277e5ed9a8faf74cfda5de6c3b7caebfb42c3de25bf3ca099fda927d64950","normalized_text_hash":"3405b1f8aca604e09b2dcca3f4a9ec21e9ef986ce86146ca7a95382212185278","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p116-33455738"},{"id":"e06f18c4-f0bb-55fe-b7eb-e5564fe3fc41","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب مسكر -تعاطي حشيش -قيادة السيارة حتت تأثير املسكر -إقامة حد املسكر على متعاطي احلشيش -حترمي كل ما أسكر ولو لم يكن شراب ا كاحلشيش .","document_number":"34177873","case_number":"33581555","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/2","year":"1434","subject":"مسكر -شرب مسكر -تعاطي حشيش -قيادة السيارة حتت تأثير املسكر -إقامة حد املسكر على متعاطي احلشيش -حترمي كل ما أسكر ولو لم يكن شراب ا كاحلشيش .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"         ‫رقم الصك‪ 34177873 :‬تاريخه‪1434/4/2:‬هـ‬\n                         ‫رقم الدعوى‪33581555 :‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 34214858:‬تاريخه‪1434/05/18 :‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب مســكر ‪ -‬تعاطــي حشــيش ‪ -‬قيــادة الســيارة حتــت تأثيــر‬\n      ‫املســكر ‪ -‬إقامــة حــد املســكر علــى متعاطــي احلشــيش ‪ -‬حتــرمي كل مــا‬\n                                  ‫أســكر ولــو لــم يكــن شــراب ًا كاحلشــيش ‪.‬‬\n\n\n\n\n      ‫‪ -1‬لعــن رســول اهلل صلــى اهلل عليــه وســلم يف اخلمــر ثمانيــة ( شــاربها‬\n      ‫وســاقيها وحاملهــا واحملمولــة إليــه وعاصرهــا ومعتصرهــا وبائعهــا‬\n                                                                 ‫وآكل ثمنهــا ) ‪.‬‬\n      ‫‪ -2‬قــال ابــن حجــر يف فتــح البــاري ‪ (45/10‬واســتدل مبطلــق قولــه صلــى‬\n      ‫اهلل عليــه وســلم ( كل مســكر حــرام ) علــى حتــرمي مــا يســكر ولــو لــم‬\n      ‫يكــن شــراب ًا فيدخــل يف ذلــك احلشيشــة وغيرهــا وقــد جــزم النــووي‬\n                                                           ‫وغيــره بأنــه مســكره ) ‪.‬‬\n                   ‫‪ -3‬املادة ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n      ‫ادعى املدعي العام ضد املدعى عليه بشرب املسكر وتعاطي احلشيش‬\n      ‫املخــدر وقيــادة الســيارة حتــت تأثيــر املســكر ‪ ،‬وطلــب إثبــات مــا أســند‬\n      ‫إليــه واحلكــم عليــه بحــد املســكر وســجنه ومنعــه مــن الســفر ‪،‬حيــث مت‬\n      ‫االشــتباه باملدعــى عليــه مــن قبــل الدوريــة األمنيــة وباستشــمامه اتضــح‬\n\n‫‪121‬‬\n\f‫أن رائحــة كريهــة تفــوح مــن أنفاســه ومت أخــذ عينــة مــن ســوائله أثبــت‬\n‫تقريــر الســموم الشــرعي إيجابيــة عينــة بــول املدعــى عليــه ملركبــات‬\n‫احلشــيش املخــدر ‪،‬وصــادق املدعــى عليــه علــى الدعــوى ‪،‬ولثبــوت شــرب‬\n‫املدعــى عليــه للمســكر واســتعمال احلشــيش املخــدر ‪،‬وبنــاء علــى مــا‬\n‫تقــدم حكمــت احملكمــة بجلــده حــد املســكر ثمانــن جلــدة ومنعــه‬\n‫مــن الســفر مــدة ســنتني بعــد تنفيــذ العقوبــة ‪،‬وثبــوت قيــادة املدعــى‬\n‫عليــه للســيارة حتــت تأثيــر املســكر وإفهامــه أن عقوبتــه عائــدة للجهــة‬\n‫املختصــة وعــدم إجابــة املدعــي العــام يف باقــي طلبــه ‪،‬وقنــع املدعــى‬\n‫‪،‬وصــدق‬\n      ‫ُ‬     ‫عليــه ‪،‬واعتــرض املدعــي العــام مكتفي ـ ًا بالئحــة الدعــوى‬\n                                       ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد لدي أنا ‪.....‬‬\n‫القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة يف محافظــة اخلبــر برقــم ‪33581555‬‬\n‫وتاريــخ ‪1433/09/19‬ه ـ املقيــدة باحملكمة برقــم ‪ 331730199‬وتاريخ‬\n‫‪1433/09/19‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1434/04/02‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 9 : 20‬وفيهــا قــدم املدعــي العــام ‪.....‬الئحــة دعــوى عامــه‬\n‫ا‬\n‫ضــد ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪).....‬قائ ـ ً‬\n‫فيهــا حيــث أنــه باالطــاع علــى خطــاب مديــر شــرطة محافظــة اخلبــر‬\n‫رقــم (‪ ).....‬وتاريــخ ‪1433/8/14‬ه ـ املرفــق بــه محضــر تنفيــذ املهمــة املعد‬\n‫مــن قبــل رجــال الضبــط اجلنائــي بالدوريــات األمنيــة مبحافظــة اخلبــر‬\n‫املتضمــن أنــه يف يــوم اخلميــس املوافــق ‪1432/7/28‬ه ـ لوحــظ املدعــى‬\n\n                                                                                        ‫‪122‬‬\n\f      ‫عليــه وشــخص آخــر يدعــى ‪ (..... /‬مت إطــاق ســراحه مــن قبــل شــرطة‬\n      ‫الدمــام لعــدم صلتــه بالقضيــة ) حيــث كان الشــخصني يف وضــع اشــتباه‬\n      ‫فتــم تســليمهما ملركــز شــرطة شــمال اخلبــر وباستشــمام املدعــى عليــه‬\n      ‫اتضــح أن رائحــة كريهــة تفــوح مــن أنفاســه ومت اإلفــراج عنــه بكفالــة‬\n      ‫احلضوريــة وببعــث عينــة مــن ســوائله (الــدم والبــول) ورد تقريــر املركــز‬\n      ‫اإلقليمــي ملراقبــة الســموم الشــرعية رقــم (‪ )..........‬وتاريــخ ‪1432/8/3‬هـ‬\n      ‫متضمن ـ ًا ايجابيــة عينــة البــول املأخــوذة مــن املدعــى عليــه ملركبــات‬\n      ‫احلشــيش املخــدر املــدرج باجلــدول األول فئــة ( أ ) مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة ‪ ،‬وبتاريــخ ‪1433/8/14‬ه ـ مت إعــادة‬\n      ‫إيقــاف املدعــى عليــه بشــعبة مكافحــة املخــدرات بالدمــام علــى ذمــة‬\n      ‫القضيــة وأفــرج عنــه بتاريــخ ‪1433/8/19‬ه ـ وباســتجواب املدعــى عليــه‬\n      ‫اقــر بشــربه للمســكر يف ‪ ........‬وبقيادتــه للســيارة بداخــل الســعودية ‪،‬‬\n      ‫وبســماع أقوالــه األوليــة مــن قبــل شــعبة مكافحــة املخــدرات بالدمــام‬\n      ‫أفــاد بــأن كان بحالــة ســكر يف ‪ ........‬وال يعلــم إذا كان وقتهــا قــد‬\n      ‫اســتعمل احلشــيش وانتهــى التحقيــق إلــى توجيــه االتهــام ل‪.....‬بشــرب‬\n      ‫املســكر وتعاطــي احلشــيش املخــدر وقيــادة الســيارة حتــت تأثيــر شــرب‬\n          ‫املســكر وتعاطــي احلشــيش املخــدر وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n      ‫‪ -1‬اعتــراف مبــا نــوه عنــه املرفــق علــى اللفــة رقــم (‪ )12‬من ملــف التحقيق‬\n                                                                        ‫املرفــق لفه (‪)1‬‬\n      ‫‪ -2‬محضــر تنفيــذ املهمــة املنــوه عنــه املرفــق علــى اللفــة رقــم ( ‪)2‬‬\n      ‫‪-3‬محضــر االستشــمام املنــوه عنــه املــدون علــى ص(‪ )11‬مــن ملــف‬\n                                                         ‫التحقيــق املرفــق لفــه (‪)1‬‬\n      ‫‪-4‬اعتــراف املدعــى عليــه بشــربه للمســكر وقيادتــه للســيارة بداخــل‬\n\n\n‫‪123‬‬\n\f‫الســعودية وظهــور رائحــة املســكر مــن أنفاســه بعــد استشــمامه مــع ورود‬\n‫ايجابيــة حتليلــه ملركبــات احلشــيش املخــدر دليــل علــى قيادتــه الســيارة‬\n                      ‫حتــت تأثيــر شــرب املســكر وتعاطــي احلشــيش املخــدر‬\n‫‪ -5‬تقريــر املركــز اإلقليمــي ملراقبــة الســموم الشــرعية املنــوه عنــه‬\n‫واملرفــق علــى لفــه رقــم (‪ )3‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر‬\n‫لــه علــى ســوابق جنائيــة مســجلة وحيــث إن مــا أقــدم عليــه املدعــى عليــه‬\n‫‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪ -‬فعــل محــرم شــرع ًا ومجــرم‬\n                                                        ‫نظام ـ ًا أطلــب مــا يلــي‪:‬‬\n‫أوالً‪ :‬احلكــم عليــه بحــد الســكر لقــاء شــربه للمســكر ثانيــا‪ :‬إثبات ما‬\n‫أســند إليــه وفــق الفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة‬\n                                  ‫املخــدرات واملؤثــرات العقليــة واحلكم عليه‪:‬‬\n‫‪ -1‬بعقوبــة الســجن الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن النظــام‬\n                  ‫ووفق ـ ًا للمــادة (‪ )30‬مــن الالئحــة التنفيذيــة لــذات النظــام‬\n             ‫‪ -2‬منعه من السفر وفق الفقرة (‪ )1‬من املادة (‪ )56‬من النظام‬\n‫ثالثــا ‪ :‬إثبــات قيادتــه للســيارة حتــت تأثيــر شــرب املســكر وتعاطــي‬\n‫احلشــيش املخــدر وفق ـ ًا للفقــرة رقــم (‪ )8‬مــن اجلــدول رقــم (‪ )1‬امللحــق‬\n‫بنظــام املــرور وإفهامــه أن عقوبتــه الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة‬\n‫رقــم (‪ )68‬مــن نظــام املــرور تقــرر مــن اجلهــة املختصــة وفــق الفقــرة (‪)2‬‬\n‫مــن قــرار مجلــس الــوزراء رقــم (‪ )315‬يف ‪1428/10/24‬ه ـ هــذه دعــواي‬\n‫وبســؤال املدعــى عليــه عــن الدعــوى أجــاب بقولــه مــا جــاء يف الدعــوى‬\n‫مــن شــربي ملســكر واســتعمالي احلشــيش املخــدر وقيادتــي الســيارة‬\n‫حتــت تأثيــر املســكر واســتعمال احلشــيش املخــدر هــذا كلــه صحيــح‬\n‫ففــي تاريــخ ‪1433/7/28‬ه ـ كنــت متواجــد ًا يف ‪ ........‬وشــربت اخلمــر‬\n\n\n                                                                                       ‫‪124‬‬\n\f      ‫هنــاك كمــا أنــي اســتعملت احلشــيش املخــدر وقمــت بقيــادة الســيارة‬\n      ‫حتــت تأثيــر املســكر واحلشــيش املخــدر ورجعــت للســعودية ومت القبــض‬\n      ‫علــي يف اخلبــر اجلنوبيــة عنــد الســاعة احلاديــة عشــر مســاء تقريب ـ ًا حيــث‬\n      ‫كنــت أقــود الســيارة حتــت تأثيــر املســكر واحلشــيش املخــدر هــذا مــا‬\n      ‫ـاء علــى مــا تقــدم مــن‬\n                              ‫حصــل وأنــا نــادم علــى فعلــي هكــذا أجــاب فبنـ ً‬\n      ‫الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه بشــرب اخلمــر واســتعمال‬\n      ‫احلشــيش املخــدر وحيــث إن فعــل املدعــى عليــه مــن كبائــر الذنــوب‬\n      ‫فقــد لعــن رســول اهلل صلــى اهلل عليــه وســلم يف اخلمــر ثمانيــة ((شــاربها‬\n      ‫وســاقيها وحاملهــا واحملمولــة إليه وعاصرهــا ومعتصرها وبائعها واكل‬\n      ‫ثمنهــا)) واللعــن ال يكــون إال علــى كبيــرة مــن كبائــر الذنــوب وملــا نص‬\n      ‫عليــه أهــل العلــم مــن إقامــة حــد املســكر علــى متنــاول احلشــيش املخــدر‬\n      ‫قــال ابــن حجــر رحمــه اهلل تعالــى يف فتــح البــاري(‪(( )45/10‬واســتدل‬\n      ‫مبطلــق قولــه صلــى اهلل عليــه وســلم ((كل مســكر حرام))علــى حتــرمي‬\n      ‫مــا يســكر ولــو لــم يكــن شــرابا فيدخــل يف ذلــك احلشيشــة وغيرهــا‬\n      ‫وقــد جــزم النــووي وغيــره بأنهــا مســكره))وحيث أقــر املدعــى عليــه‬\n      ‫بقيــادة الســيارة حتــت تأثيــر املســكر واحلشــيش املخــدر وملــا جــاء يف‬\n      ‫املــادة السادســة واخلمســن مــن نظــام مكافحــة املخــدرات وحيــث إن‬\n      ‫املــادة احلاديــة واألربعــن مــن ذات النظــام غيــر منطبقــة يف حــق املدعــى‬\n      ‫عليــه فهــي خاصــة باحليــازة لــذا فقــد قــررت مــا يلــي أو ًال ثبــت لــدي شــرب‬\n      ‫املدعــى عليــه للمســكر واســتعماله احلشــيش املخــدر وقــررت أن يجلــد‬\n      ‫لقــاء ذلــك حــد املســكر ثمانــن جلــدة دفعــة واحــدة كمــا قــررت أن‬\n      ‫مينــع املدعــى عليــه مــن الســفر خــارج اململكــة مــدة ســنتني بعــد تنفيــذ‬\n      ‫عقوبتــه لقــاء اســتعماله احلشــيش املخــدر ثانيـ ًا ثبــت لــدي قيــادة املدعــى‬\n\n\n‫‪125‬‬\n\f‫عليــه للســيارة حتــت تأثيــر املســكر واحلشــيش املخــدر وأفهمتــه أن‬\n‫عقابــه علــى ذلــك عائــد للجهــة املختصــة ثالثـ ًا عــدم إجابــة املدعــي العــام‬\n‫فيمــا طلبــه مــن تطبيــق املــادة احلاديــة واألربعــن مــن نظــام مكافحــة‬\n‫املخــدرات علــى املدعــى عليــه ومبــا تقــدم حكمــت وبعــرض احلكــم‬\n‫قنــع املدعــى عليــه ولــم يقنــع املدعــي العــام مكتفيـ ًا مبــا قــدم يف الئحــة‬\n‫الدعــوى وأقفلــت اجللســة الســاعة العاشــرة إال خمــس دقائــق وصلــى اهلل‬\n                                                         ‫وســلم علــى نبينــا محمــد‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولى مبحكمة االســتئناف باملنطقة الشــرقية على املعاملة الواردة من‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم ‪34/1730199‬‬\n‫وتاريــخ ‪1434/4/8‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪34/883938‬‬\n‫وتاريــخ ‪1434/4/10‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ ‪.....‬املســجل برقــم ‪ 34177873‬وتاريــخ ‪1434/4/2‬ه ـ‬\n‫اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد‪...../‬يف قضيــة مســكر وقــد تضمــن‬\n‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم واهلل‬\n‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                   ‫‪1434/5/14‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                         ‫‪126‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":121,"source_page_end":126,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cc56160f34167d6d17538819757fb455611dba3061f58ab93bb5e1f454103c85","normalized_text_hash":"1a2559dd2921379637d760ef2a7d0c39328bb6e4450790d499a58ff07c8b3d30","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p121-34177873"},{"id":"ddc28b19-12a4-5962-ad65-7a67bdc98f2b","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حد املسكر -قيادة سيارة حتت تأثير املسكر -هروب من رجال األمن -تهجم على منزل -التعزير بالسجن واجللد -تعهد .","document_number":"34189034","case_number":"33612613","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/15","year":"1434","subject":"مسكر -شرب املسكر -حد املسكر -قيادة سيارة حتت تأثير املسكر -هروب من رجال األمن -تهجم على منزل -التعزير بالسجن واجللد -تعهد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34189034:‬تاريخه‪1434/4/15 :‬هـ‬\n        ‫رقم الدعوى‪ 33612613:‬رقم قرار التصديق‬\n           ‫من محكمة االستئناف‪/34223117:‬ج‪2‬‬\n                         ‫تاريخه‪1434/06/07:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬حــد املســكر ‪ -‬قيــادة ســيارة حتــت تأثيــر املســكر‬\n      ‫‪ -‬هــروب مــن رجــال األمــن ‪ -‬تهجــم علــى منــزل ‪ -‬التعزيــر بالســجن‬\n                                                           ‫واجللــد ‪ -‬تعهــد ‪.‬‬\n\n\n\n\n                    ‫‪ -1‬قوله تعالى ( وال تفسدوا يف األرض بعد إصالحها ) ‪.‬‬\n                       ‫‪ -2‬قوله تعالى ( وال تعتدوا إن اهلل ال يحب املعتدين ) ‪.‬‬\n      ‫‪ -3‬قولــه صلــى اهلل عليــه وســلم ( كل املســلم عــل املســلم حــرام دمــه‬\n                                                              ‫ومالــه وعرضــه) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليهــم األول والثانــي والثالــث‬\n      ‫بشــرب املســكر وقيــادة األول حتــت تأثيــر املســكر وتســتر الرابــع‬\n      ‫علــى زمالئــه واالجتمــاع معهــم علــى منكــر وهروبهــم مــن رجــال األمــن‬\n      ‫ودخــول منــزل أحــد املواطنــن واللجــوء إلــى ســطحه وطلــب إثبــات مــا‬\n      ‫أســند إليهــم واحلكــم علــى األول والثانــي والثالــث بحــد املســكر‬\n      ‫وعقوبــة تعزيريــة للرابــع لقــاء مــا أســند إليــه ولقــاء هروبهــم مــن رجــال‬\n      ‫األمــن ولــأول كونــه أحــد رجــال األمــن ‪،‬حيــث قبــض علــى املدعــى‬\n      ‫عليهــم مــن قبــل الدوريــات األمنيــة إثــر ورود بــاغ مــن أحــد املواطنــن‬\n\n‫‪127‬‬\n\f‫بتهجــم املدعــى عليهــم علــى منزلــه حيــث قدمــوا علــى ســيارة وباالنتقــال‬\n‫للموقــع الذوا بالهــروب مترجلــن وقــد جلــأوا إلــى ســطح منــزل مواطــن‬\n‫آخــر ومت اســتخراجهم والقبــض عليهــم وكانــوا بحالــة غيــر طبيعيــة‬\n‫‪،‬أجــاب األول باإلنــكار وأجــاب الثانــي والثالــث والرابــع باملصادقــة‬\n‫علــى الدعــوى ‪،‬ومبــا أن املدعــى عليــه األول أنكــر الدعــوى وأقــر بهــا‬\n‫الثانــي والثالــث والرابــع ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بعــدم‬\n‫إدانــة املدعــى عليــه األول وبإقامــة حــد املســكر علــى املدعــى عليهــم‬\n‫الثانــي والثالــث والرابــع وتعزيرهــم بالســجن واجللــد ‪ ،‬صــدق احلكــم‬\n                                                ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫ـدي‬\n ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد فلـ َّ‬\n‫ـاء علــى املعاملــة‬\n                   ‫أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫الــواردة إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء‬\n‫برقــم ه ـ ف ‪ 11497/2/2‬وتاريخ‪1433/10/18‬ه ـ واملقيــدة بهــذه‬\n‫احملكمــة برقم‪331848080‬وتاريخ‪1433/10/21‬ه ـ واحملالــة إلينــا من‬\n‫فضيلــة الرئيــس برقم‪33612613‬وتاريخ‪1433/10/21‬ه ـ فتحــت‬\n‫اجللســة األولــى يــوم األربعــاء ‪1433/11/24‬هـ الســاعة التاســعة والنصف‬\n‫وفيهــا حضــر املدعــي العــام ‪.....‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا‬\n‫مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n‫ا‪:‬‬  ‫األحســاء ذي الرقــم ‪.....‬والتاريــخ ‪1431/1/5‬ه ـ وقـ ّـرر دعــواه قائ ـ ً‬\n‫فبصفتــي مدعيـ ًا عامـ َا بدائــرة االدعــاء العــام مبحافظــة االحســاء أدعــي‬\n‫علــى كل مــن ‪ 27..... -1 :‬عام ـ ًا العمــل عســكري ســعودي اجلنســية‬\n\n                                                                                        ‫‪128‬‬\n\f      ‫مبوجــب الســجل املدنــي رقــم ‪.....‬أوقــف بتاريــخ ‪1433/04/29‬ه ـ وأفــرج‬\n      ‫عنــه بالكفالــة بتاريــخ ‪1433/05/01‬ه ـ يقيــم يف محافظــة االحســاء‬\n      ‫حــي ‪20..... -2......‬عامـ ًا املهنــة طالــب ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪.....‬أوقــف بتاريــخ ‪1433/04/29‬ه ـ وأفــرج عنــه بكفالــة‬\n      ‫بتاريــخ ‪1433/05/01‬ه ـ يقيــم يف محافظــة االحســاء حــي ‪19..... -3.....‬‬\n      ‫عام ـ ًا عاطــل عــن العمــل ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪.....‬أوقــف بتاريــخ ‪1433/04/29‬ه ـ وأفــرج عنــه بالكفالــة بتاريــخ‬\n      ‫‪1433/05/01‬ه ـ يقيــم يف محافظــة االحســاء حــي ‪20..... -4.....‬عام ـ ًا‬\n      ‫عاطــل عــن العمــل ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n      ‫أوقــف بتاريــخ ‪1433/04/29‬ه ـ وأفــرج عنــه بالكفالــة بتاريــخ‬\n      ‫‪1433/05/01‬ه ـ يقيــم يف محافظــة االحســاء حــي ‪ ......‬حيــث انــه بتاريخ‬\n      ‫‪1433/04/29‬ه ــتم القبــض علــى املدعــى عليهــم مــن قبــل رجــال‬\n      ‫الدوريــات األمنيــة مبحافظــة األحســاء إثــر ورود بــاغ مــن املدعــو ‪..... /‬‬\n      ‫يفيــد فيــه بقيــام أربعــة أشــخاص بالتهجــم علــى منزلــه يف حــي ‪.....‬حيــث‬\n      ‫قدمــوا علــى ســيارة مــن صنــع ‪1999‬م حتمــل اللوحــة رقــم (‪ ).....‬بقيــادة‬\n      ‫املدعــى عليــه األول وباالنتقــال للموقــع الذوا جميعـ ًا بالهــروب مترجلــن‬\n      ‫فــور مشــاهدتهم للدوريــات األمنيــة وقــد جلئــوا إلــى ســطح منــزل املدعــو ‪/‬‬\n      ‫‪.....‬حينهــا مت اســتخراجهم مــن املنــزل مــن قبــل أبــن املبلــغ وأحــد اجليــران‬\n      ‫وتســليمهم للدوريــات األمنيــة ولوحــظ بأنهــم يف حالــة غيــر طبيعيــة‬\n      ‫ســكر ‪ .‬وبضبــط إفــادة املبلــغ املدعــو ‪..... /‬أفــاد بقيــام املدعــى عليهــم‬\n      ‫بطــرق بــاب املنــزل وبعــد فتــح البــاب طلبــوا منــه إخــراج أبنائــه لســبب‬\n      ‫غيــر معــروف والذوا بالهــرب بعــد قيامــه بتبليــغ الدوريــات األمنيــة ‪.‬‬\n      ‫وبضبــط إفــادة املدعــو ‪..... /‬أفــاد مبشــاهدة املدعــى عليهــم يهربــون مــن‬\n\n\n‫‪129‬‬\n\f‫الدوريــات األمنيــة وقــد جلئــوا إلــى ســطح منزلــه كونــه ســكن دبلكــس‬\n‫والــدرج مفتــوح مباشــرة علــى الســطح وباستشــمام املدعــى عليــه اتضــح‬\n‫انبعــاث رائحــة املســكر مــن األول والثانــي والثالــث ‪ .‬وباســتجواب‬\n‫املدعــى عليهــم أقــر الثانــي بشــربه ملــادة الكلونيــا املســكرة داخــل‬\n‫املنــزل بعــد مزجهــا باملــاء ‪ .‬وقــد أســفر التحقيــق عــن توجيــه االتهــام‬\n‫لــأول والثانــي والثالــث بشــرب املســكر وقيــادة األول للســيارة حتــت‬\n‫تأثيــره وتســتر الرابــع عــن زمالئــه واالجتمــاع معهــم علــى منكــر‬\n‫وهروبهــم مــن رجــال األمــن ودخــول منــزل أحــد املواطنــن واللجــوء إلــى‬\n‫ســطح منزلــه وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬أقوالهــم املدونــة علــى‬\n‫الصفحــة رقــم (‪ )5-2‬مــن دفتــر التحقيــق لفــه رقــم (‪ )1‬والصفحــة رقــم‬\n‫(‪ )16-13‬مــن دفتــر التحقيــق لفــه رقــم (‪ -2 )2‬محضــر االستشــمام‬\n‫املــدون علــى الصفحــة رقــم (‪ )6‬مــن دفتــر التحقيــق لفــه رقــم (‪-3 . )2‬‬\n‫محضــر القبــض املرفــق علــى لفــه رقــم (‪ -4 . )3‬أقــوال املبلغــن املدونــة‬\n‫علــى الصفحــة رقــم (‪ )12-9‬مــن دفتــر التحقيــق لفــه رقــم (‪ . )2‬وبالبحــث‬\n‫عمــا إذا كان لهــم ســوابق لــم يعثــر علــى ســوابق جنائيــة مســجلة بحــق‬\n‫املدعــى عليهــم األول والثالــث والربــع أمــا الثانــي فقــد عثر على ســابقتني‬\n‫مســجلتني عليــه مــن نــوع ســرقة ‪ .‬وحيــث إن مــا أقــدم عليــه املدعــى عليهم‬\n‫املذكوريــن وهــم بكامــل أهليتهــم املعتبــرة شــرع ًا فعــل محــرم ومعاقــب‬\n‫عليــه شــرع ًا ونظام ـ ًا أطلــب إثبــات مــا أســند إليهــم واحلكــم عليهــم‬\n‫باالتــي ‪ -1 :‬بحــد املســكر لــأول والثانــي والثالــث لقــاء شــربهم لــه ‪.‬‬\n‫‪ -2‬بعقوبــة تعزيريــة للرابــع لقــاء مــا أســند إليــه مــن اتهــام ولقــاء هروبهــم‬\n‫مــن رجــال األمــن ولــأول كونــه احــد رجــال االمــن املؤمــل فيــه حفــظ‬\n‫النظــام ال مخالفتــه اســتناد ًا لتعميــم ولــي العهــد ونائــب رئيــس مجلــس‬\n\n\n                                                                                         ‫‪130‬‬\n\f      ‫الــوزراء ووزيــر الداخليــة ( رحمــه اهلل ) رقــم ( ‪ )19371‬وتاريــخ‬\n      ‫‪1429/03/24‬ه ـ ‪ -3 .‬إثبــات قيــادة األول للســيارة وهــو حتــت تأثيــر‬\n      ‫شــرب املســكر وإفهامــه بــأن عقابــه علــى ذلــك عائــد للجهــة املختصــة‬\n      ‫اســتناد ًا للفقــرة ( أوال ) مــن املــادة ( ‪ )68‬مــن نظــام املــرور ‪ .‬علم ـ ًا بــأن‬\n      ‫احلــق اخلــاص انتهــى بالتنــازل ‪ .‬هكــذا ا َّدعــى ‪ ،‬عليــه فقــد حضــر املدعــى‬\n      ‫عليهــم جميعـ ًا وبعــد التأكــد مــن هوياتهــم جــرى عــرض دعــوى املدعــي‬\n      ‫ا ‪ :‬مــا ذكــره املدعــي‬     ‫العــام عليهــم فأجــاب املدعــى عليــه األول ‪.....‬قائـ ً‬\n      ‫العــام مــن اتهامــي بشــرب املســكر وقيادتــي للســيارة حتــت تأثيــره‬\n      ‫وهروبــي مــن رجــال األمــن ودخــول منــزل أحــد املواطنــن واللجــوء إلــى‬\n      ‫ســطح منزلــه كل ذلــك غيــر صحيــح والصحيــح أننــا ذهبنــا لزيــارة أحــد‬\n      ‫األصدقــاء يف حــي ‪.....‬وكان الطريــق ترابــي فغــرزت ســيارتي وجــاء‬\n      ‫أحــد املواطنــن فقــال ‪ :‬إنكــم ســكرانني فهــرب رفاقــي وأنــا جلســت‬\n      ‫يف ســيارته حتــى جــاءت الدوريــة وســلمت نفســي هكــذا أجــاب كمــا‬\n      ‫ا ‪ :‬مــا ذكــره املدعــي العــام مــن‬      ‫أجــاب املدعــى عليــه الثانــي ‪.....‬قائ ـ ً‬\n      ‫اتهامــي بشــرب املســكر وهروبــي مــن رجــال األمــن ودخولــي منــزل أحــد‬\n      ‫املواطنــن واللجــوء إلــى ســطح منزلــه فصحيــح وصحيــح أيض ـ ًا نســبة‬\n      ‫الســابقتني لــي وقــد أخــذت محكوميتهمــا هكــذا أجــاب كمــا أجــاب‬\n      ‫ا ‪ :‬مــا ذكــره املدعــي العــام مــن اتهامــي‬       ‫املدعــى عليــه الثالــث ‪.....‬قائ ـ ً‬\n      ‫بشــرب املســكر وهروبــي مــن رجــال األمــن ودخولــي منــزل أحــد‬\n      ‫املواطنــن واللجــوء إلــى ســطح منزلــه فصحيــح وأنــا نــادم علــى مــا بــدر‬\n      ‫ا ‪ :‬مــا‬ ‫منــي هكــذا أجــاب كمــا أجــاب املدعــى عليــه الرابــع ‪.....‬قائ ـ ً‬\n      ‫ذكــره املدعــي العــام مــن اتهامــي بالتســتر علــى زمالئــي واالجتمــاع‬\n      ‫معهــم علــى منكــر وهروبــي مــن رجــال األمــن ودخــول منــزل أحــد‬\n\n\n‫‪131‬‬\n\f‫املواطنــن واللجــوء إلــى ســطح منزلــه كل ذلــك صحيــح وقــد هربــت مــن‬\n‫ـب ونــادم علــى مــا بــدر‬  ‫الدوريــة بســبب أننــي كنــت ســكران ًا وأنــا تائـ ٌ‬\n‫منــي هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام هــل لديــه بينــة علــى‬\n‫ـدي ســوى مــا يف أوراق املعاملــة‬   ‫مــا نفــاه املدعــى عليــه األول قــال ‪ :‬ليــس لـ َّ‬\n‫وأطلــب الرجــوع إليهــا هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع‬\n‫أوراق املعاملــة ومنهــا ‪ :‬تقريــر ســموم شــرعية الصــادرة مــن قســم‬\n‫الكيميــاء الشــرعية باملركــز اإلقليمــي ملراقبة الســموم التابع للمديرية‬\n‫العامــة للشــؤون الصحيــة باملنطقــة الشــرقية برقــم (‪).....‬و( ‪ ).....‬و( ‪).....‬‬\n‫لعــام ‪1433‬ه ـ املتضمنــة ســلبية العينــات املأخــوذة مــن املدعــى عليهــم‬\n‫األول والثانــي والثالــث للمــواد الكحوليــة وللمــواد املخــدرة كمــا جــرى‬\n‫االطــاع علــى إقــرار املدعــى عليــه األول فلــم أجــد فيــه مــا يدينــه مبــا‬\n‫نســب إليــه كمــا جــرى االطــاع علــى كــروت ســوابق املدعــى عليهــم‬\n‫املتضمنــة عــدم وجــود ســوابق عليهــم ســوى الثانــي فلديــه ســابقتي ســرقة‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى‬    ‫فبنـ ً‬\n‫عليهــم والتأكــد مــن أهليتهــم وبعــد دراســة أوراق املعاملــة ودراســتها‬\n‫أن املدعــى عليــه األول ‪.....‬أنكــر دعــوى املدعــي العــام باتهامــه‬         ‫ومبــا َّ‬\n‫بشــرب املســكر وقيادتــه للســيارة حتــت تأثيــره وهروبــه مــن رجــال‬\n‫األمــن ودخولــه منــزل أحــد املواطنــن واللجــوء إلــى ســطح منزلــه وال بينــة‬\n‫للمدعــي العــام علــى ذلــك ممــا يســتوجب عــدم إثبــات إدانتــه بذلــك وال‬\n‫أن املدعــى عليهــم‬ ‫ا ومبــا َّ‬  ‫تعزيــره للتهمــة لعــدم توجــه التهمــة عليــه أص ـ ً‬\n‫الثانــي والثالــث والرابــع أقـ ُّـروا بشــرب املســكر وحـ ُّـد املســكر أن يجلــد‬\n‫ـتقر عليــه عمــل األمــة ممــا يســتوجب‬        ‫صاحبــه ثمانــن جلــدة كمــا اسـ َّ‬\n‫أن املدعــى عليهمــا‬   ‫إقامــة حـ ّـد املســكر علــى كل واحــد منهــم ومبــا َّ‬\n\n                                                                                             ‫‪132‬‬\n\f      ‫الثانــي والثالــث أقـ َّـرا بالهــروب مــن رجــال األمــن ودخولهمــا ملنــزل أحــد‬\n      ‫أن املدعــى عليــه الرابــع أقـ َّـر‬            ‫املواطنــن واللجــوء إلــى ســطح منزلــه ومبــا َّ‬\n      ‫بالتســتر علــى زمالئــه واالجتمــاع معهــم علــى منكــر وهروبــه مــن رجــال‬\n      ‫أن‬‫األمــن ودخــول منــزل أحــد املواطنــن واللجــوء إلــى ســطح منزلــه ومبــا َّ‬\n      ‫ض‬         ‫(و َل ُت ْف ِسـ ُـدوا ِف ْ َ‬\n           ‫ال ْر ِ‬                             ‫مــا صــدر منهــم مــن احملــرم شــرع ًا قــال تعالــى ‪َ :‬‬\n                                           ‫(وال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n      ‫الل ال ُي ِحـ ُّـب ْال ُْع َتدِ يـ َـن )‬                           ‫َب ْعـ َـد ِإ ْص َلحِ َهــا ) وقــال تعالــى ‪َ :‬‬\n      ‫دم ـ ُه‬\n            ‫ـرام ُ‬‫وقــال صلــى اهلل عليــه وســلم ‪(( :‬كلُّ املســلم علــى املســلم حـ ٌ‬\n      ‫وعرضــه)) ممــا يســتوجب تعزيرهــم ويتوجــه أن يكــون املدعــى‬                                ‫ُ‬       ‫وما ُل ـ ُه‬\n      ‫عليــه الثانــي أشــدهم عقوبــة لعــدم ارتداعــه بالعقوبــات الســابقة عليــه‬\n      ‫لــذا كلــه وألجــل احلــق العــام حكمــت علــى املدعــى عليهــم مبــا يلــي ‪:‬‬\n      ‫ـدي إدانــة املدعــى عليــه األول ‪.....‬بشــرب املســكر وال‬                          ‫أوالً‪ /‬لــم يثبــت لـ َّ‬\n      ‫قيادتــه للســيارة حتــت تأثيــره وال هروبــه مــن رجــال األمــن وال دخولــه‬\n      ‫منــزل أحــد املواطنــن واللجــوء إلــى ســطح منزلــه ر َّد دعــوى املدعــي العــام‬\n      ‫ـدي إدانــة املدعــى عليهــم الثانــي ‪.....‬‬                ‫بإثبــات إدانتــه بذلــك ‪ .‬ثانيـ ًا ‪ /‬ثبــت لـ َّ‬\n      ‫والثالــث ‪.....‬والرابــع ‪.....‬بشــرب املســكر ويجلــد كل واحــد منهمــا حـ َّـد‬\n      ‫ـدي إدانــة‬   ‫املســكر ثمانــون جلــدة دفعــة واحــدة علن ـ ًا ‪ .‬ثالث ـ ًا ‪ /‬ثبــت لـ َّ‬\n      ‫املدعــى عليهمــا الثانــي والثالــث بالهــروب مــن رجــال األمــن ودخولهمــا‬\n      ‫ملنــزل أحــد املواطنــن واللجــوء إلــى ســطح منزلــه ويعــزر املدعــى عليــه‬\n      ‫الثانــي بســجنه ملــدة ســتة أشــهر مــن تاريــخ انتهــاء محكوميتــه يف‬\n      ‫القضيــة املســجون ألجلهــا وبجلــده مائــة وخمســون جلــدة مفرقــة علــى‬\n      ‫ثــاث دفعــات كل دفعــة خمســون جلــدة وبــن كل دفعــة وأخــرى مــدة‬\n      ‫ال تقــل عــن عشــرة أيــام وبــن جلــد احلــد وجلــد التعزيــر مــدة ال تقــل عــن‬\n      ‫عشــرة أيــام ويكــون جلــد احلــد هــو املقــدم ‪ .‬ويعــزر املدعــى عليــه الثالــث‬\n\n\n‫‪133‬‬\n\f‫‪.....‬بســجنه ملــدة أربعــة أشــهر حتتســب منهــا املــدة التــي أوقــف فيهــا علــى‬\n‫ذمــة القضيــة وبجلــده مائــة وعشــرون جلــدة مفرقــة علــى ثــاث دفعــات‬\n‫كل دفعــة أربعــون جلــدة وبــن كل دفعــة وأخــرى مــدة ال تقــل عن عشــرة‬\n‫أيــام وبــن جلــد احلــد وجلــد التعزيــر مــدة ال تقــل عــن عشــرة أيــام ويكــون‬\n‫ـدي إدانــة املدعــى عليــه الرابــع‬‫جلــد احلــد هــو املقــدم ‪ .‬رابع ـ ًا ‪ /‬ثبــت لـ َّ‬\n‫بالتســتر علــى زمالئــه واالجتمــاع معهــم علــى منكــر وهروبــه مــن رجــال‬\n‫األمــن ودخــول منــزل أحــد املواطنــن واللجــوء إلــى ســطح منزلــه بســجنه‬\n‫ملــدة أربعــة أشــهر حتتســب منهــا املــدة التــي أوقــف فيهــا على ذمــة القضية‬\n‫وبجلــده مائــة وعشــرون جلــدة مفرقــة علــى ثــاث دفعــات كل دفعــة‬\n‫أربعــون جلــدة وبــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام وبــن‬\n‫جلــد احلــد وجلــد التعزيــر مــدة ال تقــل عــن عشــرة أيــام ويكــون جلــد احلــد‬\n‫هــو املقــدم ‪ .‬خامسـ ًا ‪ /‬يؤخــذ عليهــم التعهــد بعــدم العــودة ملثــل مــا صــدر‬\n‫منهــم ‪ .‬وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعــى عليهــم بحقهــم يف‬\n‫التمييــز قــرروا قناعتهــم باحلكــم عــدا املدعــى عليــه الثانــي فقــد قــرر‬\n‫عــدم القناعــة دون الئحــة اعتراضيــة وطلــب املدعــي العــام رفــع احلكــم‬\n‫للتمييــز وأن الئحتــه االعتراضيــة هــي الئحــة الدعــوى وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر احلكــم يف‬\n                                                                  ‫‪1434/04/15‬هـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/341172187‬ج‪ 2‬وتاريــخ ‪1434/5/13‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n‫املكلــف برقــم ‪ 34/923343‬وتاريــخ ‪1434/5/7‬ه ـ املرفــق بهــا القــرار‬\n\n\n                                                                                           ‫‪134‬‬\n\f      ‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪...../‬املســجل برقــم‬\n      ‫‪ 34189034‬وتاريــخ ‪1434/4/15‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضد‬\n      ‫كل مــن‪...../1‬و‪...../2‬و‪ ....../3‬و‪...../4‬يف قضيــة ســكر وقــد تضمــن‬  ‫ٍ‬\n      ‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‪ .‬واهلل‬\n      ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                 ‫‪1434/5/26‬ه ـ ‪.‬‬\n\n\n\n\n‫‪135‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":127,"source_page_end":135,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c7a0e8ab8cd32ba3c1610b35aaa9eec8bb29b442ee12f518c87dc2071f5842c2","normalized_text_hash":"3d8805f462142bb777a22cd995e98f3e94bcdf4f8b3263ce05eb075876c9c28f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p127-34189034"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"da852891-115b-5d08-885f-5a3b8491da92","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حد املسكر -تلفظ على رجال األمن -قيادة السيارة حتت تأثير املسكر -ال يحد برائحة املسكر -درء احلد بالشبهة -تداخل التعازير -التعزير باجللد والسجن .","document_number":"3457183","case_number":"33493910","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/7","year":"1434","subject":"مسكر -شرب املسكر -حد املسكر -تلفظ على رجال األمن -قيادة السيارة حتت تأثير املسكر -ال يحد برائحة املسكر -درء احلد بالشبهة -تداخل التعازير -التعزير باجللد والسجن .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫رقم الصك‪ 3457183 :‬تاريخه‪1434/3/7:‬هـ‬\n                  ‫رقم الدعوى‪33493910:‬‬\n            ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34210684:‬تاريخه‪1434/05/11:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬حــد املســكر ‪ -‬تلفــظ علــى رجــال األمــن ‪ -‬قيــادة‬\n‫الســيارة حتــت تأثيــر املســكر ‪ -‬ال يحــد برائحــة املســكر ‪ -‬درء احلــد‬\n           ‫بالشــبهة ‪ -‬تداخــل التعازيــر ‪ -‬التعزيــر باجللــد والســجن ‪.‬‬\n\n\n\n\n‫‪ -1‬قولــه صلــى اهلل عليــه وســلم ( مــن شــرب اخلمــر فاجلــدوه ) أخرجــه‬\n                                                          ‫أحمــد وأبــو داود ‪.‬‬\n‫‪ -2‬مــا نــص عليــه أهــل العلــم مــن أنــه ال يحــد بوجــود رائحــة اخلمــر‬\n‫منــه الحتمــال أنــه متضمــض بهــا أو ظنهــا مــاء فلمــا صــارت يف فيــه‬\n‫مجهــا ونحــو ذلــك واحلــد يــدرأ بالشــبهة لكــن يعــزر كحاضــر شــربها‬\n                                             ‫( كشــاف القنــاع ‪. )101/14‬‬\n       ‫‪ -3‬ما نص عليه أهل العلم من أن العقوبات التعزيرية تتداخل‬\n                                      ‫( كشاف القناع ‪. )113/14‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهــم بشــرب املســكر ‪ ،‬وبقيــام‬\n‫املدعــى عليــه الثانــي والثالــث بالتلفــظ علــى رجــال األمــن وقيــادة املدعــى‬\n‫عليــه الثانــي الســيارة حتــت تأثيــر املســكر وطلــب إثبــات مــا أســند إليهم‬\n‫واحلكــم عليهــم بحــد املســكر وبعقوبــة تعزيريــة لقــاء عــدم جتاوبهــم مع‬\n\n                                                                                      ‫‪92‬‬\n\f     ‫رجــال األمــن وعقوبــة تعزيريــة علــى الثانــي والثالــث لقــاء تلفظهــم علــى‬\n     ‫موظفــي اجلــوزات وإفهــام املدعــى عليــه الثانــي بــأن عقوبتــه لقــاء قيــادة‬\n     ‫الســيارة حتــت تأثيــر املســكر عائــدة للجهــة املختصــة وفــق األنظمــة‬\n     ‫والتعليمــات حيــث ورد بــاغ للدوريــات األمنيــة مــن قبــل جــوازات جســر‬\n     ‫امللــك فهــد عــن قيــام املدعــى عليــه الثانــي والثالــث بالتلفــظ علــى رجــل‬\n     ‫األمــن بألفــاظ غيــر الئقــة ثــم قامــا بالرقــص يف ســاحة اجلــوازات كمــا‬\n     ‫قــام املدعــى عليــه األول بعمــل حركــة ال أخالقيــة بيــده أمــام اجلنــدي‬\n     ‫وقــد اشــتبه بأنهــم يف حالــة ســكر وباستشــمامهم تبــن انبعــاث رائحــة‬\n     ‫املســكر مــن أنفاســهم جميعــا وتعــذر اســتجوابهم كونهــم يف حالــة‬\n     ‫ســكر شــديدة ‪ ،‬أنكــر األول شــرب املســكر ‪ ،‬كمــا أنكــر الثانــي‬\n     ‫شــرب املســكر وقيــادة الســيارة حتــت تأثيــره والتلفــظ على رجــال األمن‬\n     ‫‪ ،‬أقــر الثالــث بشــرب املســكر والرقــص يف ســاحة اجلــوازات والتلفــظ‬\n     ‫علــى رجــال األمــن ‪ ،‬أقــر الرابــع بشــرب املســكر وأنكــر التلفــظ علــى‬\n     ‫رجــال األمــن والرقــص ‪ ،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة علــى‬\n     ‫املدعــى عليــه الثالــث بجلــده حــد املســكر ثمانــن جلــدة وســجنه عشــرة‬\n     ‫أيــام وإثبــات إدانــة الرابــع بشــرب املســكر واحلكــم عليــه بجلــده حــد‬\n     ‫املســكر ثمانــن جلــدة ‪ ،‬عــدم ثبــوت إدانــة املدعى عليهمــا األول والثاني‬\n     ‫بشــرب املســكر أو قيــادة الثانــي للســيارة حتــت تأثيــره ‪،‬احلكــم بــدرء‬\n     ‫حــد املســكر عنهمــا وجلــد كل واحــد منهمــا تعزيــر ًا لتهمــة شــرب‬\n     ‫املســكر ســبعني جلــدة وصــرف النظــر عــن بقيــة طلبــات املدعــي العــام‬\n     ‫وقنــع املدعــى عليهــم باحلكــم واعتــرض املدعــي العــام مكتفيـ ًا بــأوراق‬\n                           ‫‪،‬وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬   ‫املعاملــة ُ‬\n\n\n\n‫‪93‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/02/17‬ه ـ لــدي‬\n‫ـاء علــى املعاملــة‬\n                 ‫أنــا ‪..........‬القاضــي باحملكمــة اجلزائيــة بالدمــام وبنـ ً‬\n‫احملالــة إلينــا مــن رئيــس احملكمــة برقــم (‪ )33493910‬وتاريــخ‬\n‫‪1433/07/29‬ه ـ افتتحــت اجللســة وفيهــا قــدم املدعــي العام‪.....‬الئحــة‬\n‫االدعــاء املتضمنــة بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء العــام مبدينــة‬\n‫الدمــام أدعــي علــى ‪..... -1‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪.......... -2 ).....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪).....‬‬\n‫‪..... -3‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪.......... -4 ).....‬‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪ ).....‬حيــث إنــه يف يــوم‬\n‫‪1433/5/14‬ه ـ ورد بــاغ لغرفــة العمليــات يف الدوريــات األمنيــة مــن‬\n‫قبــل جــوازات جســر امللــك فهــد عــن قيــام املدعــو ‪...../‬واملدعــو‪..... /‬‬\n‫بالتلفــظ علــى اجلنــدي ‪..... /‬بألفــاظ غيــر الئقــة مــن ســب وغيــره وعنــد‬\n‫محاولــة إعادتهــم لقســم القــدوم قامــوا بالنــزول مــن الســيارة والرقــص‬\n‫يف ســاحة اجلــوازات بطريقــة غيــر الئقــة وأثنــاء محاولــة ســحب إثباتاتهــم‬\n‫قــام املدعــو ‪..... /‬بعمــل حركــة ال أخالقيــة بيــده وذلــك أمــام اجلنــدي أول‬\n‫‪.......... /‬وقــد اشــتبه بأنهــم يف حالــة ســكر وذلــك لقــول املدعــى عليــه‬\n‫الثانــي املدعــو ‪(...../‬بأنهــم ســوف يرجعــون ليكملــوا الشــراب ) ويقصــد‬\n‫املســكر وباستشــمامهم تبــن انبعــاث رائحــة املســكر مــن أنفاســهم‬\n‫جميعـ ًا وقــد تعــذر اســتجوابهم كونهــم يف حالة ســكر شــديدة وبســماع‬\n‫أقوالهــم أقــروا بصحــة واقعــة القبــض وأقــر كل مــن املدعــى عليــه األول‬\n‫‪..... /‬واملدعــى عليــه الثانــي ‪..... /‬بتناولهــم للمســكر وأقــر املدعــى عليــه‬\n\n                                                                                      ‫‪94‬‬\n\f     ‫الثانــي ‪...../‬أنــه كان يقــود الســيارة عنــد القبــض عليــه وانتهــى التحقيــق‬\n     ‫إلــى توجيــه االتهــام للمدعــى عليهــم بشــرب املســكر وقيــام املدعــى‬\n     ‫عليــه الثانــي ‪...../‬واملدعــى عليــه الثالــث ‪..... /‬بالتلفــظ علــى رجــال‬\n     ‫األمــن وقيــادة املدعــى عليــه الثانــي ‪...../‬للســيارة حتــت تأثيــر املســكر‬\n     ‫وذلــك لألدلــة والقرائــن التاليــة ‪1:‬ـ مــا جــاء بأقوالهــم أثنــاء اســتجوابهم‬\n     ‫املدونــة علــى الصفحــات رقــم (‪10‬ــ‪11‬ــ‪12‬ــ‪13‬ــ‪ 14‬ــ‪ )15‬لفــة رقــم (‪2)1‬ـ مــا‬\n     ‫جــاء يف محضــر االستشــمام املــدون علــى الصفحــة رقــم (‪ )6‬لفــة رقــم‬\n     ‫(‪3 )1‬ـ مــا جــاء يف محضــر القبــض املرفــق لفــة رقــم (‪4)5‬ـ مــا جــاء يف‬\n     ‫خطــاب مديــر جــوازات جســر امللــك فهــد املرفــق علــى اللفــة رقــم (‪)30‬‬\n     ‫وبالبحــث يف ســوابق املدعــى عليهــم تبــن وجــود ســابقة واحــدة مســجلة‬\n     ‫علــى املدعــى عليــه األول ‪...../‬وهــي (حيــازة واســتعمال مخــدرات ) وعــدم‬\n     ‫وجــود ســوابق علــى الباقــن وحيــث أن مــا قــام بــه املدعــى عليهــم وهــم‬\n     ‫ا محــرم ومعاقــب عليــه شــرع ًا‬    ‫بكامــل أهليتهــم املعتبــرة شــرع ًا فع ـ ً‬\n     ‫ونظامـ ًا أطلــب إدانتهــم مبــا أســند إليهــم واحلكــم عليهــم باآلتــي ‪1:‬ـ ـ حــد‬\n     ‫املســكر لقــاء شــربهم إياه‪2‬ـ ـ عقوبــة تعزيريــة تزجرهــم وتــردع غيرهــم‬\n     ‫لقــاء عــدم جتاوبهــم مــع رجــال األمــن ‪3‬ـ ـ عقوبــة تعزيريــة للمدعــى عليــه‬\n     ‫الثانــي والثالــث لقــاء تلفظهــم علــى موظفــن اجلــوازات ‪4‬ـ إثبــات قيــادة‬\n     ‫(املدعــى عليــه الثانــي) للســيارة وهــو يف حالــة ســكر وفق ـ ًا للفقــرة (‪)8‬‬\n     ‫مــن اجلــدول رقــم (‪ )1‬امللحــق بنظــام املــرور وإفهامــه بــأن عقوبتــه الــواردة‬\n     ‫يف الفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )68‬واملــادة (‪ )76‬مــن ذات النظــام‬\n     ‫عائــد ًا للجهــة املختصــة وفقـ ًا للفقــرة (‪ )2‬مــن قــرار مجلــس الــوزراء رقــم‬\n     ‫(‪)315‬يف ‪1428/10/24‬ه ـ وبــاهلل التوفيــق ويف اجللســة حضــر املدعــى‬\n     ‫ال‬‫عليهــم الثانــي ‪.....‬والثالــث ‪.....‬والرابــع ‪.....‬املــدون اســم كل منهم كام ً‬\n\n\n‫‪95‬‬\n\f‫وهويتــه أعــاه ولــم يحضــر املدعى عليــه األول ‪.....‬وبتالوة الدعوى العامة‬\n‫علــى املدعــى عليهــم احلاضريــن وســؤالهم اإلجابــة عليهــا أجــاب الثانــي‬\n‫بقولــه مــا ذكــره املدعــي العــام مــن شــربي للمســكر وقيــادة الســيارة‬\n‫حتــت تأثيــره والتلفــظ علــى رجــال األمــن فهــذا كلــه غيــر صحيــح هــذه‬\n‫إجابتــي كمــا أجــاب املدعــى عليــه الثالــث ‪.....‬بقولــه مــا ذكــره املدعــي‬\n‫العــام مــن شــربي للمســكر والرقــص يف ســاحة اجلــوازات بطريقــة غيــر‬\n‫الئقــة فهــذا صحيــح ومــا ذكــره مــن التلفــظ علــى رجــل األمــن فهــذا‬\n‫صحيــح ألنــه رمــى البطاقــة يف وجهــي وأنــا نــادم علــى مــا حصــل منــي‬\n‫هــذه إجابتــي كمــا أجــاب الرابــع ‪.....‬بقولــه مــا ذكــره املدعــي العــام‬\n‫مــن شــرب املســكر فهــذا صحيــح فقــد شــربت املســكر وأمــا مــا‬\n‫ذكــره مــن الرقــص أو التلفــظ علــى رجــال األمــن فهــذا غيــر صحيــح‬\n‫هــذه إجابتــي وبســؤال املدعــي العــام عــن البينــة املثبتــة لصحــة التهمــة‬\n‫املنســوبة للمدعــى عليهــم أجــاب بقولــه لقــد أشــرت إلــى األدلــة والقرائــن‬\n‫يف الئحــة االدعــاء وعليــه رفعــت اجللســة للدراســة والتأمــل ولطلــب‬\n‫إحضــار املدعــى عليــه ‪.....‬وســماع مــا لديــه مــن إجابــة ويف يــوم الســبت‬\n‫املوافــق ‪1434/3/7‬ه ـ افتتحــت اجللســة وفيهــا حضــر املدعــى عليهــم‬\n‫ا وهويتــه يف اجللســة الســابقة‬ ‫‪.....‬و‪.....‬و‪.....‬املــدون اســم كل منهــم كامـ ً‬\n‫كمــا حضــر املدعــى عليــه ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ( ‪ ).....‬وبتــاوة الدعــوى العامــة عليــه و ســؤاله اإلجابــة عليهــا أجــاب‬\n‫بقولــه مــا ذكــره املدعــي العــام مــن شــربي للمســكر فهــذا غيــر صحيــح‬\n‫هــذه إجابتــي هــذا و قــد جــرت مخاطبــة هيئــة التحقيــق واالدعــاء العــام‬\n‫إلحضــار البينــة املثبتــة لصحــة التهــم املنســوبة للمدعــى عليهــم وذلــك‬\n‫باخلطــاب رقــم ( ‪ )34392880‬وتاريــخ ‪1434/2/17‬ه ـ إال إنــه لــم يحصــل‬\n\n\n                                                                                      ‫‪96‬‬\n\f     ‫جتــاوب وبعــد تدويــن مــا ســبق جــرى االطــاع علــى أقــوال املدعــى عليهــم‬\n     ‫أثنــاء اســتجوابهم واملدونــة علــى الصفحــات مــن (‪ )10‬وحتــى (‪ )15‬مــن‬\n     ‫ملــف التحقيــق األول فلــم أجــد فيهــا اعتراف ـ ًا للمدعــى عليهــم ‪.....‬و ‪.....‬‬\n     ‫بشــرب املســكر كمــا جــرى االطــاع علــى محضــر االستشــمام املــدون‬\n     ‫علــى الصفحــة السادســة مــن ملــف التحقيــق واملتضمــن أنــه مت استشــمام‬\n     ‫ال مــن ‪ .....‬و ‪ ......‬و ‪ .....‬و‪ .......‬وقــد تبــن انبعــاث رائحــة املســكر‬‫ك ً‬\n     ‫مــن أنفاســهم وأنهــم جميع ـ ًا بحالــة ســكر كمــا جــرى االطــاع علــى‬\n     ‫محضــر القبــض املــدون علــى اللفــة اخلامســة أنــه مت القبــض علــى املدعــى‬\n     ‫عليهــم بعــد حصــول ســوء تفاهــم بينهــم وبــن موظــف اجلــوازات ولــم‬\n     ‫يتضمــن هــذا احملضــر إثبــات كــون املدعــى عليهــم يف حالــة ســكر‬\n     ‫مــن عدمــه كمــا جــرى االطــاع علــى نســخة خطــاب مديــر جــوازات‬\n     ‫جســر امللــك فهــد املرفقــة علــى اللفــة رقــم (‪ )30‬فوجــدت أنهــا مجــرد‬\n     ‫نســخة خلطــاب ال ميكــن االســتناد عليهــا يف اإلثبــات مــن عدمــه فبنــاء‬\n     ‫علــى مــا تقــدم مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه الثالــث‬\n     ‫‪.....‬بشــرب املســكر والرقــص يف ســاحة اجلــوازات بطريقــة غيــر الئقــة‬\n     ‫والتلفــظ علــى رجــل األمــن واملــرء مؤاخــذ بإقــراره كمــا أقــر املدعــى‬\n     ‫عليــه الرابــع ‪.....‬بشــرب املســكر واملــرء مؤاخــذ بإقــراره ولقولــه صلــى‬\n     ‫اهلل عليــه وســلم « مــن شــرب اخلمــر فاجلــدوه « أخرجــه أحمــد وأبــو داوود‬\n     ‫وألن عمــر رضــي اهلل عنــه جلــد يف حــد اخلمــر ثمانــن جلــدة وكان ذلــك‬\n     ‫مبحضــر مــن املهاجريــن واألنصــار فلــم ينكــره أحــد فيهــم وحيــث إن‬\n     ‫العقوبــات التعزيريــة تتداخــل ( كشــاف القنــاع ‪ ) 113 / 14‬وحيــث‬\n     ‫أنكــر املدعــى عليهمــا األول والثانــي شــرب املســكر وال توجــد لهــم يف‬\n     ‫املعاملــة أي اعترافــات بذلــك وبنــاء علــى محضــر االستشــمام املرصــود‬\n\n\n‫‪97‬‬\n\f‫بعاليــة وبنــاء علــى مــا نــص عليــه أهــل العلــم مــن أنــه ال يحــد بوجــود رائحة‬\n‫اخلمــر منــه الحتمــال أنــه متضمــض بهــا أو ظنهــا مــاء فلمــا صــارت يف فيــه‬\n‫مجهــا ونحــو ذلــك واحلــد يــدرأ بالشــبهة لكــن يعــزر كحاضــر شــربها (‬\n‫كشــاف القنــاع ‪ ) 101 / 14‬وحيــث إنــه لــم يثبــت شــرب املدعــى عليــه‬\n‫الثاني‪.....‬للمســكر وبالتالــي فإنــه ال يثبــت قيامــه بقيــادة الســيارة حتــت‬\n‫تأثيــره لــذا فقــد ثبــت لــدي إدانــة املدعــى عليــه الثالــث ‪..........‬بشــرب‬\n‫املســكر والرقــص يف ســاحة اجلمــارك بطريقــة غيــر الئقــة والتلفــظ‬\n‫علــى رجــل األمــن وحكمــت عليــه لقــاء ذلــك بجلــده حــد املســكر‬\n‫ثمانــن جلــدة وســجنه عشــرة أيــام حتتســب منهــا املــدة التــي أوقــف فيهــا‬\n‫علــى ذمــة هــذه القضيــة كمــا ثبــت لــدي إدانــة املدعــى عليــه الرابــع‬\n‫‪..........‬بشــرب املســكر وحكمــت عليــه لقــاء ذلــك بجلــده حــد املســكر‬\n‫ثمانــن جلــدة ولــم يثبــت لــدي إدانــة املدعــى عليهمــا األول والثانــي بشــرب‬\n‫املســكر أو قيــادة الثانــي للســيارة حتــت تأثيــره وحكمــت بــدرء حــد‬\n‫املســكر عنهمــا وجلــد كل واحــد منهمــا تعزيــر ًا لقــاء تهمــة شــرب‬\n‫املســكر ســبعني جلــدة وصرفــت النظــر عــن بقيــة طلبــات املدعــي العــام‬\n‫وبعــرض احلكــم علــى املدعــى عليهــم قــرروا قناعتهــم بــه وقــرر املدعــي‬\n‫العــام االعتــراض واالكتفــاء مبــا يف أوراق املعاملــة فأجيــب لطلبه وباهلل‬\n      ‫التوفيــق وصلــى اهلل علــى نبينــا محمــد وبــه حــرر يف ‪1434/3/7‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام املكلــف برقــم‬\n‫‪ 33/1429529‬وتاريــخ ‪1434/3/17‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n‫‪ 34715102‬وتاريــخ ‪1434/3/22‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n\n\n                                                                                          ‫‪98‬‬\n\f     ‫فضيلــة القاضــي باحملكمــة الشــيخ ‪.....‬املســجل برقــم ‪3457183‬‬\n     ‫وتاريــخ ‪1434/3/7‬ه ـ اخلــاص بدعوى‪/‬املدعــى العام ضــد‪-2.......... -1/‬‬\n     ‫‪ ..... -4.......... -3.....‬يف قضيــة مســكر وتلفــظ علــى رجــال االمــن وقــد‬\n     ‫تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة‬\n     ‫القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‬\n     ‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم حــرر يف‬\n                                                                  ‫‪1434/5/8‬ه ـ ‪.‬‬\n\n\n\n\n‫‪99‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":92,"source_page_end":99,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"68eb3c68b74ec29c352bc34e5bd28c7913e44b6e23d1751f99c903e83548fb62","normalized_text_hash":"5c83ac1efdc5ee70c1716e368ab3c8ca7f9cd24770d007bd74d77a123a431aac","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p92-3457183"},{"id":"d9186bdb-e12d-5f35-b3d0-5c2516c6bfbf","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حيازة بقصد الشرب -قيادة السيارة حتت تأثير املسكر -هروب من رجال األمن -املدعى عليه مريض نفسي -التوقف يف نظر الدعوى حتى يتم التأكد من مسؤولية املدعى عليه اجلنائية-ورود تقرير املستشفى مبسؤولية املدعى عليه عن تصرفاته -تعزير املدعى عليه بالسجن واجللد .","document_number":"3442764","case_number":"33504822","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف باملنطقة الشرقية وبرفقها قرار أصحاب الفضيلة قضاة الدائرة اجلزائية األولى وهم فضيلة القاضي","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/20","year":"1434","subject":"مسكر -شرب املسكر -حيازة بقصد الشرب -قيادة السيارة حتت تأثير املسكر -هروب من رجال األمن -املدعى عليه مريض نفسي -التوقف يف نظر الدعوى حتى يتم التأكد من مسؤولية املدعى عليه اجلنائية-ورود تقرير املستشفى مبسؤولية املدعى عليه عن تصرفاته -تعزير املدعى عليه بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫رقم الصك‪ 3442764:‬تاريخه‪1434/2/20:‬هـ‬\n                   ‫رقم الدعوى‪33504822:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34387291:‬تاريخه‪1434/12/25:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬حيــازة بقصــد الشــرب ‪ -‬قيــادة الســيارة حتــت‬\n‫تأثيــر املســكر ‪ -‬هــروب مــن رجــال األمــن ‪ -‬املدعــى عليــه مريــض نفســي‬\n‫‪ -‬التوقــف يف نظــر الدعــوى حتــى يتــم التأكــد مــن مســؤولية املدعــى‬\n‫عليــه اجلنائيــة‪-‬ورود تقريــر املستشــفى مبســؤولية املدعــى عليــه عــن‬\n                    ‫تصرفاتــه ‪ -‬تعزيــر املدعــى عليــه بالســجن واجللــد ‪.‬‬\n\n\n\n\n             ‫‪ -1‬املادة الثالثة والثمانني من نظام املرافعات الشرعية ‪.‬‬\n ‫‪ -2‬املادة الرابعة والتسعني بعد املائة من نظام اإلجراءات اجلزائية ‪.‬‬\n‫‪ -3‬املــادة اخلامســة والتســعني بعــد املائــة مــن نظــام اإلجــراءات‬\n                                                        ‫الـجــزائـ ــية ‪.‬‬\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وحيازتــه‬\n‫بقصــد الشــرب وقيــادة الســيارة حتــت تأثيــر املســكر والهــروب مــن‬\n‫رجــال األمــن و طلــب إثبــات مــا أســند إليــه واحلكــم عليــه بحــد املســكر‬\n‫وتعزيــره وتشــديد العقوبــة لقــاء تعــدد ســوابقه‪ ،‬حيــث تلقــت الدوريــات‬\n‫األمنيــة بالغ ـ ًا عــن مركبــة بقيــادة املدعــى عليــه تقــوم مبضايقــة املــارة‬\n‫يف الطريــق ويحــاول صدمهــم أثنــاء الســير ومت متابعتــه مــن قبــل الدوريــة‬\n\n                                                                                      ‫‪100‬‬\n\f      ‫وقــام باملراوغــة بــن املركبــات بســرعة عاليــة فتــم اســتيقافه وكان يف‬\n      ‫حالــة غيــر طبيعيــة وبتفتيشــه لــم يعثــر علــى أي ممنوعــات معــه وبتفتيــش‬\n      ‫املركبــة عثــر علــى قــارورة فيهــا مــادة مســكرة فتــم القبــض عليــه‬\n      ‫وجــرى إتــاف القــارورة وباستشــمامه تبــن انبعــاث رائحــة املســكر‬\n      ‫مــن أنفاســه‪ ،‬تبــن لناظــر القضيــة مــن خــال تصرفــات املدعــى عليــه‬\n      ‫أثنــاء اجللســة أنــه يعانــي مــن أمــراض نفســية ‪ ،‬جــرى الكتابــة ملجمــع‬\n      ‫األمــل للصحــة النفســية للكشــف علــى املدعــى عليــه واإلفــادة عــن‬\n      ‫أهليتــه ومســؤوليته اجلنائيــة ‪ ،‬لــم يــرد جوابهــم بعــد مضــي مــدة طويلــة‪،‬‬\n      ‫قــرر القاضــي التوقــف يف نظــر الدعــوى حتــى ورود التقريــر‪ ،‬بعــد ورود‬\n      ‫التقريــر املثبــت عــدم وجــود أعــراض مرضية نفســية وأنه بحالتــه الراهنة‬\n      ‫مســؤول عــن تصرفاتــه جــرى عرض الدعوى علــى املدعى عليه‪،‬فأنكر‬\n      ‫شــرب املســكر وقيــادة الســيارة حتــت تأثيــر املســكر‪ ،‬وصــادق علــى‬\n      ‫حيازتــه وهروبــه مــن رجــال األمــن ‪ ،‬إثبــات إدانــة املدعــى عليــه بحيــازة‬\n      ‫املســكر وهروبــه مــن رجــال األمــن ‪ ،‬وبنــاء علــى مــا تقــدم حكمــت‬\n      ‫احملكمــة بتعزيــره لقــاء ذلــك كلــه بســجنه تعزيــرا مــدة ســنة وجلــده‬\n      ‫مائــة جلــدة علــى دفعتــن كل دفعــة خمســون جلــدة وقنــع املدعــى عليــه‬\n      ‫واعتــرض املدعــي العــام بالئحــة لــم يقدمهــا يف املــدة املقــررة نظام ـاً‪،‬‬\n           ‫ُصـ ّـدق احلكــم مــن الدائــرة اجلزائيــة األولــى مبحكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلــدي‬\n      ‫أنــا ‪..........‬القاضــي باحملكمــة اجلزئيــة بالدمــام ففــي يــوم الثالثــاء‬\n      ‫املوافــق ‪1434/2/19‬ه ـ افتتحــت اجللســة الســاعة التاســعة والنصــف‬\n\n‫‪101‬‬\n\f‫صباح ـ ًا بنــاء علــى املعاملــة احملالــة إلينــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزئيــة بالدمــام برقــم ‪ 331969046‬وتاريــخ ‪1433/11/1‬ه ـ واملقيــدة‬\n‫بــوارد مكتبنــا برقــم ‪ 331464654‬وتاريــخ ‪1433/ 8 /4‬ه ـ واملتعلقــة‬\n                                            ‫بدعــوى املدعــي العــام ضــد ‪..... /‬‬\n‫وفيهــا حضــر املدعــي العــام ‪ ..... /‬وادعــى على احلاضر معه ‪..... /‬ســعودي‬\n‫اجلنســية مبوجــب الســجل املدنــي ‪ .....‬قائــا يف دعــواه فباالطــاع علــى‬\n‫محضــر تنفيــذ مهمــة املعــد مــن قبــل رجــال الضبــط اجلنائــي بالدوريــات‬\n‫األمنيــة بالدمــام تبــن أنــه يف يــوم الســبت ‪1433/7/12‬ه ـ تلقــت‬\n‫الدوريــات األمنيــة بالغ ـ ًا مــن العمليــات عــن مركبــة تقــوم مبضايقــة‬\n‫املــارة يف الطريــق ويحــاول صدمهــم أثنــاء الســير قبــل كبــري ‪.....‬جنوبـ ًا‬\n‫ثــم دخــل أحــد احملطــات وقــام بالتشــاجر مــع بعــض العمالــة وبعدهــا‬\n‫خــرج بســيارته ‪ ،‬فتــم متابعــة الدوريــة لــه إلــى أن وصــل إلــى طريــق‬\n‫رأس تنــورة جنوب ـ ًا ولــم يقــف وقــام باملراوغــة بــن املركبــات بســرعة‬\n‫عاليــة ومتهــورة ومت متابعتــه مــن قبــل الدوريــة ورفــض الوقــوف ثــم دخــل‬\n‫طريــق إلــى طريــق مقابــل معــارض الســيارات ثــم نــزل مــع كبــري علــى‬\n‫طريــق باجتــاه فتــم اســتيقافه بعــد إشــارة حــي (‪ )..‬مقابــل مســجد وكان‬\n‫الشــخص يف حالــة غيــر طبيعيــة وبتفتيشــه لــم ُيعثــر علــى أي ممنوعــات‬\n‫معــه وبتفتيــش املركبــة ُعثــر علــى قــارورة صغيــرة فيهــا أقــل مــن الربــع‬\n‫مــن احملتمــل أن تكــون مــادة مســكرة فتــم القبــض عليــه ‪ ،‬وقــد جــرى‬\n‫إتــاف القــارورة املضبوطــة مــع املذكــور وفــق احملضــر املــدون مــن قبــل‬\n‫جهــة الضبــط ‪ ،‬وباستشــمامه تبــن انبعــاث رائحــة املســكر من أنفاســه‪.‬‬\n                            ‫وبسماع أقواله أنكر شربه للمسكر وحيازته‪.‬‬\n‫وانتهــى التحقيــق إلــى اتهــام املدعــى عليــه بشــرب املســكر وحيازتــه‬\n\n\n                                                                                    ‫‪102‬‬\n\f      ‫لقــارورة مــاء صحــة صغيــرة بهــا الربــع مــن املســكر بقصــد الشــرب ‪،‬‬\n                    ‫وقيــادة الســيارة حتــت تأثيــره ‪ ،‬والهــروب مــن رجــال األمــن‪.‬‬\n                                                         ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n                                 ‫‪ -1‬محضر تنفيذ املهمة املرفق على اللفة رقم (‪.)2‬‬\n      ‫‪ -2‬محضــر االستشــمام املــدون علــى الصفحــة رقــم (‪ )8‬مــن دفتــر‬\n                                    ‫األحــوال األمنيــة املوحــد املرفــق لفــة رقــم (‪.)1‬‬\n      ‫‪ -3‬محضــر اإلتــاف املــدون علــى الصفحــة رقــم (‪ )10‬مــن دفتــر األحــوال‬\n                                                    ‫األمنيــة املوحــد املرفــق لفــة رقــم (‪.)1‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه ‪ -‬وهــو بكامــل أهليتــه املعتبــرة‬\n      ‫ـب عليــه شــرع ًا ونظامـ ًا لــذا أطلــب مــا يلــي ‪:‬‬‫شــرع ًا ‪ -‬فعــلٌ محــرم ومعاقـ ٌ‬\n      ‫أو ًال ‪ /‬إثبــات إدانتــه مبــا ُنســب إليــه واحلكــم عليــه بعقوبــة تعزيريــة‬\n      ‫تزجــره وتــردع غيــره ‪ ،‬وتشــديد العقوبــة لقــاء ســوابقه املتكــررة التــي‬\n      ‫لــم تردعــه عقوباتهــا الســابقة وفــق تعميــم نائــب وزيــر الداخليــة رقــم‬\n                                                   ‫(‪ )93958‬وتاريــخ ‪1429/8/23‬هــ‪.‬‬\n      ‫ثاني ـ ًا ‪ /‬إثبــات قيادتــه للســيارة حتــت تأثيــر املســكر وفــق الفقــرة رقــم‬\n      ‫(‪ )8‬مــن اجلــدول رقــم (‪ )1‬امللحــق بنظــام املــرور وإفهامــه بــأن عقوبتــه‬\n      ‫الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة رقــم (‪ )68‬مــن نظــام املــرور تقــرر مــن‬\n      ‫اجلهــة املختصــة وفــق الفقــرة (‪ )2‬مــن قــرار مجلــس الوزراء رقــم (‪ )315‬يف‬\n      ‫‪1428/10/24‬ه ـ هــذه دعــواي وعليــه فقــد جــرى إحضــار املدعــى عليــه‬\n      ‫عــدة جلســات إال أنــه ظهــر لــي وتبــن لــي مــن خــال جتاوبــه يف اجللســة‬\n      ‫ومــن خــال بعــض تصرفاتــه أثنــاء اجللســة أن املدعــى عليــه يعانــي مــن‬\n      ‫أمــراض نفســية وإبــراء للذمــة جــرى الكتابــة ملجمــع للصحــة النفســية‬\n      ‫بكتابنــا رقــم ‪ 33/1576223‬وتاريــخ ‪1433/8/20‬ه ـ للكشــف علــى‬\n\n\n‫‪103‬‬\n\f‫املدعــى وبيــان أهليتــه ومســؤوليته اجلنائيــة إال أنــه لــم تــرد إلينــا إفــادة‬\n‫مــن مجمــع األمــل للصحــة النفســية حتــى تاريــخ ‪1434/2/19‬ه ـ وهــذه‬\n‫مــدة طويلــة تلحــق الضــرر باملدعــى عليــه وخصوصــا كــون املدعــى‬\n‫عليــه ســجينا وبنــاء علــى املــادة الثالثــة والثمانــن مــن نظــام املرافعــات‬\n‫الشــرعية ولوائحــه التنفيذيــة ونظــرا إلــى أن التأكــد مــن قبــل القاضــي‬\n‫علــى ســامة املدعــى عليــه واالطمئنــان إلــى كمــال قــواه العقليــة‬\n‫والنفســية مــن األمــور املهمــة والضروريــة ونظــرا إلــى أن إطالــة املــدة يف‬\n‫القضيــة يلحــق الضــرر باملدعــى عليــه ألنــه ســجني والتقريــر الطبــي لــم‬\n‫يــرد والشــريعة اإلســامية جــاءت برفــع الضــرر وال ضــرر وألن الفصــل‬\n‫يف هــذه القضيــة متوقــف علــى التقريــر الطبــي لــذا ولــكل مــا ســبق فقــد‬\n‫قــررت التوقــف يف هــذه القضيــة وبذلــك حكمــت وبعــرض احلكــم علــى‬\n‫املدعــي العــام قــرر املدعــي العــام االعتــراض علــى احلكــم بــدون الئحــة‬\n‫اعتراضيــة ورفعــه حملكمــة االســتئناف مكتفيــا مبــا يف أوراق املعاملــة‬\n‫وعليــه فقــد قــررت رفــع املعاملــة كاملــة حملكمــة االســتئناف لتدقيــق‬\n‫احلكــم وختمــت يف الســاعة العاشــرة وعلــى ذلــك جــرى التوقيــع وبــاهلل‬\n‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                         ‫‪ .‬حــرر يف ‪1434/2/19‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم األحــد املوافــق ‪1434/5/ 19‬ه ـ‬\n‫افتتحــت اجللســة الســاعة التاســعة والنصــف صباحـ ًا وفيهــا عــادت إلينــا‬\n‫املعاملــة مــن مقــام محكمــة االســتئناف باملنطقــة الشــرقية وبرفقهــا‬\n‫قــرار أصحــاب الفضيلــة قضــاة الدائــرة اجلزائيــة األولــى وهــم فضيلــة‬\n      ‫القاضــي ‪ ..... /‬وفضيلــة القاضــي ‪ ..... /‬وفضيلــة القاضــي ‪..... /‬‬\n‫الصــادر منهــم برقــم ‪34199521‬وتاريــخ ‪1434/04/28‬ه ـ ونــص احلاجــة‬\n\n\n                                                                                        ‫‪104‬‬\n\f      ‫منــه بعــد املقدمــة مــا يلــي ‪ ( :‬لوحــظ أن فضيلتــه أوقــف النظــر يف هــذه‬\n      ‫القضيــة ولــم يحــدد مــدة اإليقــاف حســب منطــوق املــادة املشــار إليهــا‬\n      ‫ملالحظــة مــا ذكــر وإكمــال الــازم ومــن ثــم إعــادة املعاملــة ) ونظــرا‬\n      ‫لوجاهــة مــا ذكــره أصحــاب الفضيلــة وعليــه فيكــون قــرار التوقــف‬\n      ‫يف هــذه القضيــة مبــا يلــي‪ :‬قــررت التوقــف عــن النظــر يف هــذه القضيــة‬\n      ‫إلــى حــن ورود التقريــر الطبــي للمدعــى عليــه‪ .‬وبذلــك حكمــت وأمــرت‬\n      ‫بإحلــاق ذلــك بالقــرار وســجله وإعــادة املعاملــة ألصحــاب و أحيــط‬\n      ‫أصحــاب الفضيلــة علم ـ ًا بأنــي قمــت بالكتابــة مــرة أخــرى ألجــراء‬\n      ‫الفحــص علــى املدعــى عليــه وذلــك بتاريــخ ‪1434/04/14‬ه ـ وحتــى‬\n      ‫تاريخ‪1434/05/19‬ه ـ لــم يردنــا التقريــر الطبــي واهلل املوفــق وصلــى‬\n                     ‫اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                   ‫‪1434/5/ 19‬هـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هذا اليوم اخلميــس املوافق ‪1434/08/25‬هـ‬\n      ‫افتتحــت اجللســة يف الســاعة العاشــرة والنصــف صباحــا وفيهــا حضــر‬\n      ‫الطرفــان وقــد افتتحــت بنــاء علــى مــا وردنــا مــن مجمــع للصحــة النفســية‬\n      ‫بالدمــام تقريــر اللجنــة النفســية برقــم (‪ ).....‬وتاريــخ ‪1434/7/26‬ه ـ‬\n      ‫املتضمــن مــا نصــه ‪ « :‬اســم املريــض ‪..... /‬رقــم الهويــة (‪ ).....‬بالفحــص‬\n      ‫علــى املذكــور مــن قبــل اللجنــة النفســية يف يــوم األحــد وتاريــخ‬\n                                                                    ‫‪1434/07/23‬ه ـ‬\n      ‫تبــن عــدم وجــود أعــراض مرضيــة نفســية أو عقليــة يف الوقــت الراهــن‬\n                                      ‫وهــو بحالتــه الراهنــة مســئول عــن تصرفاتــه ‪.‬‬\n      ‫عضــو اللجنــة د‪..... /‬توقيعــه ‪ ،‬عضــو اللجنــة أ‪ ،..... /‬توقيعــه ‪ ،‬عضــو‬\n      ‫اللجنــة د‪..... /‬توقيعــه ‪ ،‬رئيــس اللجنــة الطبيــة د‪..... /‬توقيعــه ‪. ».‬أ‪.‬ه ـ‬\n\n\n‫‪105‬‬\n\f‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه أجــاب قائــا مــا ذكره‬\n‫املدعــي مــن قيامــي بشــرب املســكر وأننــي قمــت بقيــادة الســيارة حتــت‬\n‫تأثيــره كل ذلــك غيــر صحيــح ومــا ذكــره مــن وجــود قــارورة مــاء صحــة‬\n‫صغيــرة بهــا مســكر بالســيارة فصحيــح إال أنهــا ليســت لــي فهــي‬\n‫لصاحــب الســيارة والســيارة ليســت لــي ومــا ذكــره املدعــي العــام مــن‬\n‫هروبــي مــن رجــال األمــن فصحيــح هكــذا أجــاب كمــا جــرى اطالعــي‬\n‫علــى ســوابق املدعــى عليــه وهــي (‪ )3‬شــرب املســكر وعــدد(‪ )1‬ســرقة‬\n‫ســيارات وعــدد (‪ )1‬حيــازة واســتعمال مخــدرات وبعرضهــا علــى املدعــى‬\n‫عليــه صــادق علــى صحتهــا ثــم جــرى ســؤال املدعــي العــام هــل لديــك بينة‬\n‫علــى دعــواك فيمــا يتعلــق بشــرب املســكر وقيــادة الســيارة حتــت تأثيــر‬\n‫املســكر فأجــاب قائــا ليــس لــدي بينــة علــى ذلــك ســوى مــا يف أوراق‬\n‫املعاملــة هكــذا أجــاب ثــم جــرى اطالعــي علــى أوراق املعاملــة كمــا‬\n‫جــرى اطالعــي علــى محضــر تنفيــذ مهمــة وتســليمها جلهــة االختصــاص‬\n                    ‫املرفــق باملعاملــة لفــة رقــم (‪ )4-3‬واملتضمــن مــا نصــه ‪:‬‬\n‫« أثنــاء مســح الدوريــة تلقينــا بــاغ مــن عمليــات أمــان عــن مركبــة‬\n‫والشــخص املوضــح بعاليــه أنــه يضايــق املــارة يف الطريــق ويجــول أثنــاء‬\n‫الســير قبــل كبــري جنــوب ثــم دخــل محطــة ‪.....‬عشــرين وقــام مبهاوشــت‬\n‫العمــال داخــل احملطــة ثــم حلظــه الدوريــة قبــل تنــورة جنــوب وتابعــه ولــم‬\n‫يقــف وثــم يــراوغ بــن املركبــات بســرعة عاليــة ومتهــور ومت متابعتــه‬\n‫مــن قبــل الدوريــة ورفــض الوقــف وحــول اســتيقافه ورفــض ثــم دخــل مــع‬\n‫مخــرج ومت متابعتــه حتــى نــزل مــع طريــق مقابــل املعــارض جنــوب ثــم نــزل‬\n‫مــع كبــري علــى طريــق امللــك فهــد باجتــاه الدمــام ومت اســتيقافه بعــد‬\n‫إشــارة (‪ )..‬مقابــل مســجد وكان الشــخص مــن احملتمــل يف حالــة غيــر‬\n\n\n                                                                                     ‫‪106‬‬\n\f      ‫طبيعيــة كان يســبب خطــر علــى املاريــن واملرتاديــن للطريــق ومت رفــع‬\n      ‫الشــخص واملركبــة للعمليــات بــدون ملخصــات ومت تفتيــش املركبــة‬\n      ‫والشــخص عثــر علــى قــارورة صغيــرة عصيــر فيهــا أقــل مــن الربــع‬\n      ‫محتمــل مــادة مســكرة « أ‪.‬هــ‪ .‬وبعــرض ذلــك علــى املدعــى عليــه أجــاب‬\n      ‫قائــا مــا جــاء يف احملضــر مــن أنــي كنــت يف حالــة غيــر طبيعيــة فغيــر‬\n      ‫صحيــح هكــذا أجــاب فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‬\n      ‫ونظــرا ملــا قــرره الطرفــان ومــا مت رصــده وضبطــه أعــاه وبنــاء علــى‬\n      ‫إقــرار املدعــى عليــه بوجــود قــارورة مــاء صحــة صغيــرة بهــا مســكر‬\n      ‫وهروبــه مــن رجــال األمــن واملــرء مؤاخــذ بإقــراره وال عــذر ملــن أقــر‬\n      ‫ونظــرا إلــى أن دفعــه بــأن القــارورة ليســت لــه دفــع غيــر معتبــر وذلــك‬\n      ‫لوجــود قرينــة وهــي هروبــه مــن رجــال األمــن ونظــرا إلــى لتوجــه التهمــة‬\n      ‫ضــد يف شــربه للمســكر وقيادتــه للســيارة حتــت تأثيــر املســكر وتتمثل‬\n      ‫الشــبهة يف إقــراره بوجــود قــارورة املســكر وهروبــه مــن رجــال األمــن‬\n      ‫وســوابقه املماثلــة لشــرب املســكر وكل هــذه قرائــن تــدل علــى الشــبهة‬\n      ‫القويــة ضــده يف شــرب املســكر وتوجــه التهمــة يف شــرب املســكر‬\n      ‫هــو توجــه التهمــة يف عودتــه لشــرب املســكر ونظــرا إلــى أن احلــدود‬\n      ‫تــدرأ بالشــبهات ونظــرا إلــى أن ســوابق املدعــى عليــه املذكــورة أعــاه‬\n      ‫تســتوجب التشــديد يف عقوبــة املدعــى عليــه لــذا ولــكل مــا ســبق ‪ :‬فقــد‬\n      ‫ثبــت لــدي إدانــة املدعــى عليــه مبــا نســب إليــه مــن حيــازة قــارورة مــاء‬\n      ‫صحــة صغيــرة بهــا مســكر بقصــد الشــرب وهروبــه مــن رجــال األمــن‬\n      ‫وبذلــك حكمــت وتوجهــت التهمــة يف شــربه للمســكر وقيــادة الســيارة‬\n      ‫حتــت تأثيــر املســكر وعودتــه لشــرب املســكر وبذلــك وحكمــت عليــه‬\n      ‫لقــاء ذلــك بســجنه تعزيــرا مــدة ســنة يحتســب منهــا مــا أمضــاه موقوفــا‬\n\n\n‫‪107‬‬\n\f‫يف هــذه القضيــة وجلــده تعزيــرا مائــة جلــدة علــى دفعتــن كل دفعــة‬\n                  ‫خمســون جلــدة بــن كل دفعــة والتــي تليهــا عشــرة أيــام ‪.‬‬\n‫وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه قناعتــه باحلكــم‬\n‫وقــرر املدعــي العــام االعتــراض علــى احلكــم بالئحــة اعتراضيــة فأجبتــه‬\n‫لطلبــه وأفهمــت املدعــي العــام بــأن عليهــم مراجعــة احملكمــة يف يــوم‬\n‫األربعــاء املوافــق ‪1434/ 09 /02‬ه ـ الســتالم نســخة مــن احلكــم لتقــدمي‬\n‫الئحتــه االعتراضيــة خــال ثالثــن يومــا مــن تاريــخ االســتالم وإال ســقط‬\n‫حقــه يف طلــب االســتئناف وختمــت يف الســاعة احلاديــة عشــرة صباحــا‬\n‫وعلــى ذلــك جــرى التوقيــع وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا‬\n         ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/ 08 /25‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده و بعــد ففــي يــوم األربعــاء املوافــق ‪ 1434/09/02‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09:00‬وهــذا اليــوم هــو اليــوم احملــدد لتســليم‬\n‫املدعــي العــام نســخة مصــورة مــن قــرار احلكــم إال أنــه لــم يحضــر وقــد‬\n‫مت االنتهــاء مــن قــرار احلكــم وعليــه فقــد مت إيــداع نســخة مصــورة مــن‬\n‫قــرار احلكــم يف املعاملــة يف هــذا اليــوم نفســه ويعــد اإليــداع بدايــة مليعــاد‬\n‫الثالثــن يومـ ًا املقــررة لطلــب اســتئناف احلكــم وللمعلوميــة فقــد جــرى‬\n‫حتريــره وختمــت يف الســاعة ‪ 09:30‬وعلــى ذلــك جــرى التوقيــع وبــاهلل‬\n‫التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                        ‫حــرر يف ‪1434/09/02‬ه ـ‬\n‫احلمــد هلل وحــده و بعــد ففــي يــوم الثالثــاء املوافــق ‪1434/10/06‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09:00‬و قــد انتهــت املــدة املنصــوص عليهــا يف‬\n‫املــادة الرابعــة والتســعني بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة ولــم‬\n‫يتقــدم املدعــي العــام بالئحتــه االعتراضيــة خــال هــذه املــدة لــذا قــررت‬\n\n\n                                                                                         ‫‪108‬‬\n\f      ‫رفــع كامــل املعاملــة حملكمــة االســتئناف وفقــا ملــا نصــت عليه اخلامســة‬\n      ‫والتســعون بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة و للمعلوميــة فقــد‬\n      ‫جــرى حتريــره وختمــت يف الســاعة ‪ 09:30‬وعلــى ذلــك جــرى التوقيــع‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                                 ‫وســلم حــرر يف ‪ 1434/10/06‬ه ـ‬\n      ‫احلمد هلل وحده وبعد ‪ . . .‬فقد اطلعنـا نحن قـضـاة الدائـرة اجلـزائيـة األولى‬\n      ‫يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة مــن‬\n      ‫فضيلــة رئيــس احملكمــة اجلزائيــة مبدينــة الدمــام برقــم ‪34/1669414‬‬\n      ‫وتاريــخ ‪1434/10/27‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪342502891‬‬\n      ‫وتاريــخ ‪1434/11/4‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n      ‫باحملكمــة الشــيخ ‪.....‬املســجل برقــم ‪ 3442764‬وتاريــخ ‪1434/2/20‬ه ـ‬\n      ‫اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪........../‬يف قضيــة مســكر والهــروب‬\n      ‫مــن رجــال األمــن وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n      ‫ومفصــل فيــه ‪ .‬حيــث ســبق دراســة القــرار وصــورة ضبطــه وباالطــاع‬\n      ‫علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصــورة ضبطــه بنــاء‬\n      ‫علــى قرارنــا رقــم‪ 34251453‬يف ‪1434/6/26‬ه ـ قررنــا املصادقــة علــى‬\n      ‫احلكــم بعــد اإلجــراء األخيــر واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                  ‫وآلــه وصحبــه وســلم حــرر يف ‪1434/12/23‬ه ـ ‪.‬‬\n\n\n\n\n‫‪109‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":100,"source_page_end":109,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"61147a8715644cb1428af5da7379b605012864604301d846c9db509ee7cf7d22","normalized_text_hash":"50a510323af4c3a19d93b6734720f394bf82ab5edc688b2e861dce02824866fb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p100-3442764"},{"id":"f173d19c-192e-5f0b-a6bf-ad03539bb4ac","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -وفاة املدعى عليه -رد الدعوى -انقضاء الدعوى بوفاة املدعى عليه .","document_number":"3447361","case_number":"33547013","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/25","year":"1434","subject":"مسكر -شرب املسكر -قيادة سيارة حتت تأثير املسكر -وفاة املدعى عليه -رد الدعوى -انقضاء الدعوى بوفاة املدعى عليه .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك‪ 3447361 :‬تاريخه‪1434/2/25 :‬هـ‬\n                    ‫رقم الدعوى‪33547013:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n‫االستئناف‪ 34203125:‬تاريخه‪1434/05/01:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب املســكر ‪ -‬قيــادة ســيارة حتــت تأثيــر املســكر ‪ -‬وفــاة املدعــى‬\n             ‫عليــه ‪ -‬رد الدعــوى ‪ -‬انقضــاء الدعــوى بوفــاة املدعــى عليــه ‪.‬‬\n\n\n\n\n                 ‫‪ -1‬األصل براءة الذمة وال يعدل عن ذلك إال بدليل ‪.‬‬\n‫‪ -2‬الفقــرة الرابعــة مــن املــادة الثانيــة والعشــرين مــن نظــام اإلجــراءات‬\n                                                                    ‫اجلزائيــة ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليهمــا بتنــاول األول املســكر وقيــادة‬\n‫املركبــة حتــت تأثيــره والثانــي بتنــاول املســكر وطلــب إثبــات مــا أســند‬\n‫إليهمــا واحلكــم عليهمــا بحــد املســكر وإفهــام املدعــى عليــه األول بــأن‬\n‫عقوبتــه عائــدة للجهــة املختصــة لقيــادة املركبــة حتــت تأثيــر املســكر‬\n‫‪،‬حيــث قبــض علــى املدعــى عليهمــا إثــر ورود بــاغ مــن أحــد املواطنــن‬\n‫باســتيقافه وهــو يقــود ســيارته برفقــة أهلــه مــن قبــل املدعــى عليهمــا وقــد‬\n‫اتضــح أنهمــا بحالــة غيــر طبيعيــة وبحوزتهما قارورة بداخلهــا مادة العرق‬\n‫املســكر كمــا اتضــح انبعــاث رائحــة املســكر منهمــا ‪ ،‬أنكــر املدعــى‬\n‫عليــه الثانــي الدعــوى وأفــاد بــأن املدعــى عليــه األول قــد تــويف وصــدرت‬\n‫لــه شــهادة وفــاة وأبــرز نســختها لــدى القاضــي ‪،‬وحيــث إن املدعــى عليــه‬\n\n                                                                                      ‫‪110‬‬\n\f      ‫الثانــي أنكــر الدعــوى وليــس للمدعــي العــام بينــة عليــه ســوى محضــر‬\n      ‫القبــض وإثبــات احلالــة ولــم يتضمنــا بــأن املدعــى عليــه الثانــي بحالــة غيــر‬\n      ‫طبيعيــة ‪،‬ومبــا أن األصــل بــراءة الذمــة حكمــت احملكمــة بــرد دعــوى‬\n      ‫املدعــي العــام ضــده لعــدم كفايــة األدلــة وقنــع املدعــى عليــه واعتــرض‬\n      ‫املدعــي العــام بالئحــة ‪ ،‬أمــا املدعــى عليــه األول فقــد ورد جواب األحوال‬\n      ‫املدنيــة باملدينــة املنــورة وبرفقــة نســخة موثقــة مــن شــهادة وفــاة املدعــى‬\n      ‫عليــه األول ‪،‬وبنــاء علــى الفقــرة الرابعــة مــن املــادة الثانيــة والعشــرين مــن‬\n      ‫نظــام اإلجــراءات اجلزائيــة ‪،‬فــإن الدعــوى العامــة تكــون منقضيــة بحــق‬\n                 ‫املدعــى عليــه األول وصــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد فلدي أنا‬\n      ‫‪.....‬القاضــي باحملكمــة اجلزئيــة باملدينــة املنــورة حــاال وبنــاء علــى املعاملــة‬\n      ‫احملالــة لنــا مــن فضيلــة الرئيــس برقــم ‪1433/8/25 33547013‬ه ـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331603329‬وتاريــخ ‪1433/8/25‬هـ افتتحت‬\n      ‫اجللســة اخلاصــة بالئحــة الدعــوى العامــة مــن املدعــي العــام ‪ .....‬ضــد‬\n      ‫املدعــى عليهمــا ‪ ..... -1‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪..... -2).....‬ســعودي اجلنســية بالســجل املدنــي رقــم (‪ ).....‬املتضمنــة أنــه‬\n      ‫بتاريــخ ‪1433/6/30‬ه ـ قبــض علــى املدعــى عليهمــا مــن قبــل دوريــات‬\n      ‫األمــن مبوجــب محضرهــم رقــم ‪.....‬املتضمــن دعــوى املواطــن ‪.....‬ضدهمــا‬\n      ‫باســتيقافه أثنــاء ســيره بســيارته مــع أهلــه وقــد اتضــح أن املدعــى عليهمــا‬\n      ‫بحالــة غيــر طبيعيــة وبحوزتهمــا قــارورة عصيــر بداخلهــا مــادة العــرق‬\n      ‫املســكر وجــرى إثبــات حالــة املدعــى عليهمــا واتضــح أن رائحــة العــرق‬\n\n‫‪111‬‬\n\f‫املســكر تنبعــث منهمــا وانتهــى التحقيــق إلــى توجيــه االتهــام إلى املدعى‬\n‫عليــه األول بتنــاول العــرق املســكر وقيــادة املركبــة حتــت تأثيــر العــرق‬\n‫املســكر واتهــام املدعــى عليــه الثانــي بتنــاول العــرق املســكر وبالبحــث‬\n‫عــن ســوابقهما لــم يعثــر للمدعــى عليــه األول ‪.....‬علــى ســوابق مســجلة‬\n‫عليــه وعثــر للمدعــى عليــه الثانــي ‪.....‬علــى أربــع ســوابق ( فاحشــة لــواط‬\n‫‪ -‬مضاربــة ‪ -‬حيــازة أدوات اســتعمال أدوات مخــدرات ‪ -‬اســتعمال‬\n‫مخــدرات ) ويطلــب إثبــات مــا أســند إليهمــا واحلكــم عليهمــا بإقامــة‬\n‫حــد املســكر وإثبــات إدانــة املدعــى عليــه األول ‪.....‬بقيــادة الســيارة حتــت‬\n‫تأثيــر املســكر وإفهامــه أن عقابــه علــى ذلــك عائــد للجهــة املختصــة‬\n‫ويف هــذه اجللســة حضــر املدعــى عليــه الثانــي ‪ .....‬املذكــور ولــم يحضــر‬\n‫املدعــى عليــه األول ‪.....‬املذكــور ثــم جــرى ســؤال املدعــى عليــه الثانــي‬\n‫‪.....‬عمــا جــاء يف دعــوى املدعــي العــام أجــاب صحيــح الســوابق املســجلة‬\n‫علــي وقــد أخــذت جزائــي عليهــا مــن الســابق وصحيــح أننــي كنــت‬\n‫راكبــا مــع املدعــى عليــه ‪.....‬يف الســيارة التــي كان يقودهــا و أمــا‬\n‫مــا جــاء يف دعــوى املدعــي العــام مــن اتهامــه لــي بتنــاول مــادة العــرق‬\n‫ا كمــا أن املدعــى عليــه ‪.....‬‬     ‫املســكر فغيــر صحيــح جملــة وتفصي ـ ً‬\n‫قــد تــويف رحمــه اهلل بعــد هــذه القضيــة يف شــهر رجــب مــن هــذا العــام‬\n‫هــذا مــا لــدي وعليــه أوقــع فســألت املدعــي العــام هــل لديــك بينــة علــى‬\n‫دعــواك وعمــا يذكــره املدعــى عليــه ‪.....‬مــن وفــاة املدعــى عليــه ‪.....‬قــال‬\n‫أمــا وفــاة املدعــى عليــه ‪.....‬فــا علــم لــي بذلــك وأطلــب حتديــد جلســة‬\n‫أخــرى حتــى نتحقــق ممــا ذكــره املدعــى عليــه احلاضــر عــن وفــاة املدعــى‬\n‫عليــه ‪.....‬وحتــى أحضــر بينتــي علــى املدعــى عليــه ‪.....‬فأجيــب لطلبــه‬\n‫وبتاريــخ ‪1434/1/25‬ه ـ حضــر املدعــي العــام واملدعــى عليــه ‪.....‬وقــدم‬\n\n\n                                                                                     ‫‪112‬‬\n\f      ‫لنــا املدعــى عليــه نســخة مــن شــهادة وفــاة برقــم ‪ .....‬يف ‪1433/7/29‬ه ـ‬\n      ‫مكتــوب فيهــا أســم املتوفــى ‪ ..........‬وتاريــخ الوفــاة يف ‪1433/7/21‬ه ـ‬\n      ‫وهــي نســخة غيــر موثقــة وبعــرض ذلــك علــى املدعــي العــام قــال لــم نبلــغ‬\n      ‫بوفــاة املدعــى عليــه ‪.....‬رســميا هــذا مــا لــدي فســألت املدعــي العــام هــل‬\n      ‫لديــك بينــة علــى املدعــى عليــه ‪.....‬قــال بينتــي مــا هــو مذكــور يف الئحــة‬\n      ‫الدعــوى العامــة مــن محضــر القبــض ومحضــر إثبــات حالــة هــذا مــا لــدي‬\n      ‫وبالرجــوع إلــى أوراق املعاملــة وجدنــا علــى اللفــة (‪ )2‬محضــر القبــض‬\n      ‫وليــس فيــه مــا يتضمــن تعاطــي املدعــى عليــه ‪.....‬للمســكر ســوى أنــه‬\n      ‫وجــدوا داخــل الســيارة علبــة بهــا مــادة غيــر طبيعيــة كمــا وجدنــا علــى‬\n      ‫الصحيفــة (‪ )11‬مــن ملــف التحقيــق (‪ )1‬محضــر إثبــات حالــة مــن قبــل‬\n      ‫شــخص واحــد واملتضمــن أنــه بإثبــات حالــة املدعــى عليهمــا اتضــح‬\n      ‫أنهمــا بحالــة طبيعيــة ومتزنــن يف كالمهــم وتصرفاتهــم وتنبعــث مــن‬\n      ‫أفواههــم رائحــة كريهــة احتمــال أن تكــون رائحــة العــرق املســكر‬\n      ‫وقــد وجدنــا علــى الصحيفــة (‪ )12‬مــن ذات امللــف اعترافــات املدعــى‬\n      ‫عليــه ‪.....‬وقــد تضمنــت اعترافــه بتعاطــي املســكر وحيازتــه لــه بغــرض‬\n      ‫الســكر وقيــادة الســيارة حتــت تأثيــر املســكر وأن املدعــى عليــه ‪.....‬‬\n      ‫لــم يتنــاول أي مــادة مســكرة وقــد اقتضــى النظــر التحقــق مــن صحــة‬\n      ‫نســخة شــهادة الوفــاة عــن طريــق مكاتبــة األحــوال املدنيــة فبنــاء علــى‬\n      ‫مــا تقــدم مــن الدعــوى واإلجابــة وكامــل مجريــات القضيــة وحيــث‬\n      ‫أنكــر املدعــى عليــه ‪.....‬تعاطــي املســكر ولــم يكــن للمدعــي العــام مــن‬\n      ‫بينــة علــى املدعــى عليــه ‪.....‬ســوى مــا أورده مــن محضــر القبــض وإثبــات‬\n      ‫احلالــة وحيــث لــم يتضمــن احملضــران وجــود املدعــى عليــه ‪.....‬بحالــة‬\n      ‫غيــر طبيعيــة وإمنــا تضمــن محضــر إثبــات احلالــة انبعــاث رائحــة يحتمــل‬\n\n\n‫‪113‬‬\n\f‫أن تكــون رائحــة العــرق املســكر وهــو محضــر معــد مــن شــخص‬\n‫واحــد ولــم يجــزم معــده بوجــود رائحــة املســكر وإذا تطــرق االحتمــال‬\n‫بطــل االســتدالل وتلــك القرائــن ال ترقــى إلثبــات إدانــة املدعــى عليــه وال‬\n‫حتــى توجــه التهمــة ألن األصــل البــراءة وال يعــدل عــن ذلــك إال بدليــل‬\n‫ولــم يوجــد هــا هنــا ال ســيما وأن أقــوال املدعــى عليــه األول ‪.....‬قائــد‬\n‫الســيارة تضمنــت أن املســكر املضبــوط بالســيارة لــه وأنــه تعاطــاه وأن‬\n‫املدعــى عليــه ‪.....‬لــم يتعاطــى املســكر ولــكل مــا ســلف فلــم يثبــت لــدي‬\n‫إدانــة املدعــى عليــه ‪.....‬بتنــاول العــرق املســكر وحكمــت بــرد دعــوى‬\n‫املدعــي العــام ضــد املدعــى عليــه ‪.....‬لعــدم كفايــة األدلــة وأمــا مــا يخــص‬\n‫املدعــى عليــه ‪.....‬فقــد اقتضــى النظــر حتديــد جلســة أخــرى بعــد ورود‬\n‫اإلفــادة فيمــا يخــص شــهادة الوفــاة مــن األحــوال املدنيــة وســتكون‬\n‫اجللســة القادمــة مبشــيئة اهلل تعالــى يــوم الثالثــاء املوافــق ‪1434/2/26‬ه ـ‬\n‫الســاعة ‪ 11،15‬وبعــرض احلكــم علــى الطرفــن قــرر املدعــى عليــه‬\n‫القناعــة وقــرر املدعــي العــام املعارضــة وأســتعد بتقــدمي الئحــة اعتراضيــة‬\n‫وأفهــم باملراجعــة يف اجللســة القادمــة لتســليمه نســخة احلكــم حتتســب‬\n‫لــه بعــد ذلــك مــدة ثالثــن يومــا لتقــدمي الئحتــه فــإن انقضــت ولــم يتقــدم‬\n‫بالئحتــه فســيتم بعــث القــرار مــع كامــل متعلقــات حملكمــة االســتئناف‬\n‫بــدون الئحــة اعتراضيــة وبتاريــخ ‪1434/2/19‬ه ـ حضــر املدعــي العــام‬\n‫وقــد وردنــا كتــاب مديــر مكتــب األحــوال املدنيــة باملدينــة املنــورة‬\n‫فــرع العاليــة مــول رقــم ‪.....‬يف ‪1434/2/5‬ه ـ واملقيــد باحملكمــة برقــم‬\n‫‪ 34/236074‬يف ‪1434/2/16‬ه ـ واملتضمــن أنــه مت إكمــال الــازم وقد‬\n‫وجدنــا برفقــه نســخة موثقــة مــن شــهادة الوفــاة اخلاصــة باملدعــى عليــه‬\n‫‪.....‬املذكــور وأن تاريــخ الوفــاة يف ‪1433/7/21‬ه ـ فبنــاء علــى مــا تقــدم‬\n\n\n                                                                                       ‫‪114‬‬\n\f      ‫ومــا مت مؤخــرا وبنــاء علــى الفقــرة الرابعــة مــن املــادة الثانيــة والعشــرين‬\n      ‫مــن نظــام اإلجــراءات اجلزائيــة فــإن هــذه الدعــوى العامــة منقضيــة بحــق‬\n      ‫املدعــى عليــه األول ‪.....‬لوفاتــه وبذلــك حكمــت فقــرر املدعــي العــام‬\n      ‫القناعــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                    ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/19‬ه ـ‬\n                  ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪:‬‬\n      ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف‬\n      ‫مبكــة املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى‬\n      ‫هــذه احملكمــة بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة باملدينــة‬\n      ‫املنــورة رقــم(‪ )34198733‬وتاريــخ (‪1434/3/21‬هــ) املرفــق بهــا‬\n      ‫القــرار رقم(‪)3447361‬وتاريخ(‪1432/2/25‬هـ)الصــادر مــن فضيلــة‬\n      ‫الشــيخ‪...../‬القاضي احملكمــة اجلزائيــة باملدينــة املنــورة‪ ،‬املتضمــن‬\n      ‫دعــوى املدعــي العــام ضد‪...../‬ورفيقــه ســعوديي اجلنســية ‪ ،‬املتهمــن‬\n      ‫بتنــاول العــرق املســكر وقيــادة الســيارة حتــت تأثيــره ‪ ،‬احملكــوم فيــه‬\n      ‫مبــا دون باطنــه‪ ،‬وبدراســة القــرار وصــورة ضبطــه والئحتــه االعتراضيــة‬\n      ‫تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل املوفــق‪ ،‬وصلــى اهلل علــى نبينــا‬\n                                                ‫محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪115‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":110,"source_page_end":115,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"e1eacbbfad8f45dbf048ed19d45c99037ead575db3217ebbb7a10f2cd14cea50","normalized_text_hash":"6666d145a5f2baac25ae672aba31e6be6e747e180bafa23be8743b72c44c193b","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p110-3447361"},{"id":"8746e4a5-40b9-5140-9624-b57445e44931","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب مسكر -تعاطي حشيش -قيادة السيارة حتت تأثير املسكر -اشتراك احلشيش مع اخلمر يف مناط احلكم -إقامة حد املسكر -املنع من السفر .","document_number":"33455738","case_number":"33552912","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/25","year":"1434","subject":"مسكر -شرب مسكر -تعاطي حشيش -قيادة السيارة حتت تأثير املسكر -اشتراك احلشيش مع اخلمر يف مناط احلكم -إقامة حد املسكر -املنع من السفر .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 33455738 :‬تاريخه‪1434/1/25 :‬هـ‬\n                    ‫رقم الدعوى‪33552912:‬‬\n             ‫رقم قرار التصديق من محكمة‬\n  ‫االستئناف‪ 3410025:‬تاريخه‪1434/01/25:‬هـ‬\n\n\n‫مســكر ‪ -‬شــرب مســكر ‪ -‬تعاطــي حشــيش ‪ -‬قيــادة الســيارة حتــت تأثيــر‬\n‫املســكر ‪ -‬اشــتراك احلشــيش مــع اخلمــر يف منــاط احلكــم ‪ -‬إقامــة حــد‬\n                                              ‫املســكر ‪ -‬املنــع مــن الســفر ‪.‬‬\n\n\n\n\n                   ‫‪ -1‬قوله صلى اهلل عليه وسلم ( كل مسكر حرام ) ‪.‬‬\n            ‫‪ -2‬املادة ‪ 41‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n            ‫‪ -3‬املادة ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n                                          ‫‪ -4‬املادة ‪ 68‬من نظام املرور ‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام ضــد املدعــى عليــه بشــرب املســكر وتعاطــي‬\n‫احلشــيش املخــدر وقيــادة الســيارة حتــت تأثيرهمــا وطلــب إثبــات مــا‬\n‫أســند إليــه واحلكــم عليــه بحــد املســكر ومعاقبتــه وتشــديد العقوبــة‬\n‫لقــاء قيــادة الســيارة حتــت تأثيــر املســكر وعــدم مباالتــه بــأرواح‬\n‫اآلخريــن ومنعــه مــن الســفر ‪،‬حيــث قبــض علــى املدعــى عليــه مــن قبــل‬\n‫الدوريــة األمنيــة إثــر وقــوع حــادث اصطــدام ســيارة بقيــادة املدعــى عليــه‬\n‫وأثبــت تقريــر الســموم الشــرعي إيجابيــة عينــة ســوائل املدعــى عليــه‬\n‫ملركبــات احلشــيش وصــادق املدعــى عليــه علــى الدعــوى ‪،‬وبنــاء علــى‬\n\n                                                                                    ‫‪116‬‬\n\f      ‫مــا تقــدم حكمــت احملكمــة بجلــده حــد املســكر ثمانــون جلــدة دفعــة‬\n      ‫واحــدة ومنعــه مــن الســفر ور ّد دعــوى املدعــي العــام بخصــوص معاقبــة‬\n      ‫املدعــى عليــه وإفهامــه أن عقوبــة قيــادة الســيارة حتــت تأثيــر املســكر‬\n      ‫عائــد للجهــة املختصــة وقنــع املدعــى عليــه واعتــرض املدعــي العــام بــدون‬\n                               ‫‪،‬وصــدق احلكــم محكمــة االســتئناف ‪.‬‬     ‫الئحــة ُ‬\n\n\n\n\n      ‫اجلزائيــة‬\n         ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة‬\n      ‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة يف محافظــة االحســاء برقــم ‪ 33552912‬وتاريــخ‬\n      ‫‪1433/08/27‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331622202‬وتاريــخ‬\n      ‫‪1433/08/27‬ه ـ ففــي يــوم الثالثــاء املوافق‪1433/11/09‬ه ـ افتتحــت‬\n      ‫اجللســة الســاعة ‪ 10 : 00‬وفيهــا حضــر املدعــي العــام وادعــى ضــد‬\n      ‫احلاضــر ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬إنــه بتاريــخ‬\n      ‫‪1432/11/21‬ه ـ مت القبــض علــى املدعــى عليــه مــن قبــل إحــدى فــرق‬\n      ‫الدوريــات األمنيــة مبحافظــة االحســاء وذلــك إثــر وقــوع حــادث اصطــدام‬\n      ‫ســيارة مــن نــوع (‪ ).....‬ســنة صنعهــا(‪2009‬م) حتمــل اللوحــة رقــم (‪).....‬‬\n      ‫بقيــادة املدعــى عليــه (مت فــرز أوراق مســتقله للحــادث ومعاجلتهــا مــن‬\n      ‫قبــل جهــة االختصــاص) وقــد أثبــت تقريــر الســموم الشــرعي رقــم( ‪).....‬‬\n      ‫لعام‪1433‬ه ـ ايجابيــة عينــة ســوائله ملركبــات احلشــيش املخــدر و املــدرج‬\n      ‫مــن ضمــن املــواد احملظــورة يف اجلــدول رقــم (‪ )1‬فئــة (أ) امللحــق بنظــام‬\n      ‫مكافحــة املخــدرات واملؤثــرات العقليــة و للمــواد الكحوليه (االيثيلي)‪.‬‬\n      ‫وباســتجوابه ‪ /‬أقــر بشــربه اخلمــر املســكر وتعاطيــه للحشــيش املخــدر‬\n\n‫‪117‬‬\n\f                                                ‫و قيادتــه الســيارة حتــت تأثيرهمــا‪.‬‬\n‫وقــد أســفر التحقيــق عــن توجيــه االتهــام لــه بشــرب اخلمــر املســكر‬\n‫وتعاطــي احلشــيش املخــدر وقيادتــه للســيارة حتــت تأثيرهمــا لألدلــة‬\n                                                                   ‫والقرائــن اآلتيــة‪:‬‬\n‫‪1‬ـ إقــراره املــدون علــى الصفحــة رقــم (‪ )3-1‬مــن ملــف التحقيــق املرفــق‬\n                                                              ‫علــى اللفــة رقــم (‪. )25‬‬\n                      ‫‪2‬ـ تقرير السموم الشرعي املرفق على اللفة رقم (‪. )13‬‬\n                    ‫‪3‬ـ محضر القبض املرفق صوره منه على اللفة رقم (‪. )5‬‬\n                        ‫وبالبحث عن سوابقه لم يعثر له على سوابق مسجلة ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املذكور ‪ -‬وهو بكامل أهليته املعتبرة شــرع ًا‬\n‫‪ -‬فعــل محــرم ومعاقــب علي ــه شــرع ًا نظامـ ًا يف ضــوء الفقــرة الثانيــة مــن‬\n‫املــادة الثالثــة مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة الصــادر‬\n‫باملرســوم امللكــي الكــرمي رقــم (م‪ )39/‬وتاريــخ ‪1426/7/8‬هـ ـ اطلــب‬\n                                  ‫إثبــات مــا أســند إليــه واحلكــم عليــه مبــا يلــي‪:‬‬\n                                                     ‫‪ .1‬بحد املسكر لقاء شربه له ‪.‬‬\n‫‪ .2‬بالعقوبــة الــواردة يف الفقــرة األولــى مــن املــادة (‪ )41‬مــن النظــام املشــار‬\n‫إليــه أعــاه لقــاء تعاطيــه احلشــيش املخــدر‪ ،‬وتشــديد العقوبــة عليــه لقــاء‬\n‫قيادتــه الســيارة حتــت تأثيــر شــرب اخلمــر املســكر و تعاطــي احلشــيش‬\n‫املخــدر وعــدم مباالتــه بــأرواح اآلخريــن اســتنادا لتعميــم صاحــب الســمو‬\n         ‫امللكــي أميــر املنطقــة الشــرقية رقــم (‪ )8019‬يف ‪1433/2/24‬ه ـ‬\n‫‪ .3‬منعــه مــن الســفر خــارج البــاد بعــد تنفيــذ محكوميتــه اســتناد ًا‬\n                           ‫للفقــرة األولــى مــن املــادة (‪ )56‬مــن ذات النظــام ‪.‬‬\n                     ‫‪ .4‬تأثير شرب اخلمر املسكر و تعاطي احلشيش املخدر‬\n\n\n                                                                                            ‫‪118‬‬\n\f      ‫‪ .4‬إثبــات قيادتــه للســيارة حتــت تأثيــر شــرب اخلمــر املســكر و تعاطــي‬\n      ‫احلشــيش املخــدر وإفهامــه بــأن عقابــه عائــد للجهــة املختصــة عمــا‬\n      ‫بالفقــرة األولــى مــن املــادة (‪ )68‬مــن نظــام املــرور الصــادر باملرســوم‬\n      ‫امللكــي رقــم (م‪ )85/‬و تاريــخ ‪1428/10/26‬هــ‪ .‬هــذه دعــواي وبســؤال‬\n      ‫املدعــى عليــه أجــاب قائــا مــا ذكــره املدعــي العــام مــن أنــه بتاريــخ‬\n      ‫‪1432/11/21‬ه ـ قبــض علــي مــن قبــل الدوريــات األمنيــة باألحســاء‬\n      ‫وذلــك إثــر وقــوع حــادث تصــادم وأنــه مت التحليــل لــي وأننــي أشــرب‬\n      ‫املســكر وأتعاطــى احلشــيش وأننــي قمــت قيــادة الســيارة حتــت تأثيرهما‬\n      ‫فهــذا كلــه صحيــح وأنــا تائــب هكــذا أجــاب وباالطــاع علــى املعاملــة‬\n      ‫وجــد فيهــا علــى لفــه ‪ 13‬تقريــر الســموم الشــرعية رقــم ‪.....‬واملتضمــن‬\n      ‫إيجابيــة عينــة البــول للمــواد الكحوليــة وملركبــات احلشــيش املخــدر‬\n      ‫واحملظــور دوليــا أ‪.‬ه ـ فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وإقــرار‬\n      ‫املدعــى عليــه وحيــث إن املــرء مؤاخــذ بإقــراره وللتقريــر الشــرعي ولقــول‬\n      ‫النبــي صلــى اهلل عليــة وســلم (كل مســكر حــرام ) وحيــث إن احلشــيش‬\n      ‫يشــترك مــع اخلمــر يف منــاط احلكــم لذلــك كلــه فقــد ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه بشــرب اخلمــر وتعاطــي احلشــيش املخــدر وقيــادة الســيارة‬\n      ‫حتــت تأثيرهمــا ولــم يثبــت لــدي احليــازة لهمــا لذلــك كلــه فقــد حكمــت‬\n                                                                            ‫مبــا يلــي أوال‪:‬‬\n                        ‫جلد املدعى عليه ثمانون جلدة دفعة واحدة حد املسكر‬\n      ‫ثانيــا‪ :‬رد دعــوى املدعــي العــام بخصــوص معاقبــة املدعــى عليــه مبوجــب‬\n      ‫املــادة ‪ 41‬مــن نظــام مكافحــة املخــدرات واملؤثــرات العقليــة لعــدم ثبــوت‬\n                                                                                    ‫احليازة‬\n      ‫ثالثــا‪ :‬منــع املدعــى عليــه مــن الســفر خــارج اململكــة بعــد تنفيــذ‬\n\n\n‫‪119‬‬\n\f‫محكوميــة مــدة ســنتني وذلــك مبوجــب املــادة ‪ 56‬مــن نظــام مكافحــة‬\n‫املخــدرات واملؤثــرات العقليــة رابعــا‪ :‬ثبــت لــدي إدانــة املدعــى عليــه بقيادة‬\n‫الســيارة حتــت تأثيــر اخلمــر واحلشــيش وأفهمتــه بــأن عقابــه عائــد إلــى‬\n‫اجلهــة املختصــة وبنــاء علــى املــادة ‪ 68‬مــن نظــام املــرور هــذا مــا ظهــر لــي‬\n‫وبــه حكمــت وبعــرض احلكــم علــى املدعــي العــام واملدعــى عليــه قــرر‬\n‫املدعــي العــام اعتراضــه وطلــب رفــع املعاملــة إلــى محكمــة االســتئناف‬\n‫بــدون الئحــة وأمــا املدعــى عليــه فقــرر قناعتــه بــه وبــه ختمــت اجللســة يف‬\n‫متــام الســاعة ‪ 10.30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد‬\n                     ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1433/11/09‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قضــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء برقــم‬\n‫‪ 331943304‬وتاريــخ ‪1433/11/20‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n‫‪/33/2095075‬ج‪ 1‬وتاريــخ ‪1433/11/23‬ه ـ املرفــق بهــا القرار الصادر‬\n‫مــن فضيلــة القاضــي باحملكمــة الشــيخ‪..... /‬املســجل برقــم ‪33455738‬‬\n‫وتاريــخ ‪1433/11/16‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪...../‬يف‬\n‫قضيــة مخــدرات ومســكر وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه ؛ وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                             ‫وآلــه وصحبــه وســلم حــرر يف ‪1434 /1/11‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                         ‫‪120‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":116,"source_page_end":120,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"1da277e5ed9a8faf74cfda5de6c3b7caebfb42c3de25bf3ca099fda927d64950","normalized_text_hash":"3405b1f8aca604e09b2dcca3f4a9ec21e9ef986ce86146ca7a95382212185278","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p116-33455738"},{"id":"e06f18c4-f0bb-55fe-b7eb-e5564fe3fc41","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب مسكر -تعاطي حشيش -قيادة السيارة حتت تأثير املسكر -إقامة حد املسكر على متعاطي احلشيش -حترمي كل ما أسكر ولو لم يكن شراب ا كاحلشيش .","document_number":"34177873","case_number":"33581555","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/2","year":"1434","subject":"مسكر -شرب مسكر -تعاطي حشيش -قيادة السيارة حتت تأثير املسكر -إقامة حد املسكر على متعاطي احلشيش -حترمي كل ما أسكر ولو لم يكن شراب ا كاحلشيش .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"         ‫رقم الصك‪ 34177873 :‬تاريخه‪1434/4/2:‬هـ‬\n                         ‫رقم الدعوى‪33581555 :‬‬\n                    ‫رقم قرار التصديق من محكمة‬\n      ‫االستئناف‪ 34214858:‬تاريخه‪1434/05/18 :‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب مســكر ‪ -‬تعاطــي حشــيش ‪ -‬قيــادة الســيارة حتــت تأثيــر‬\n      ‫املســكر ‪ -‬إقامــة حــد املســكر علــى متعاطــي احلشــيش ‪ -‬حتــرمي كل مــا‬\n                                  ‫أســكر ولــو لــم يكــن شــراب ًا كاحلشــيش ‪.‬‬\n\n\n\n\n      ‫‪ -1‬لعــن رســول اهلل صلــى اهلل عليــه وســلم يف اخلمــر ثمانيــة ( شــاربها‬\n      ‫وســاقيها وحاملهــا واحملمولــة إليــه وعاصرهــا ومعتصرهــا وبائعهــا‬\n                                                                 ‫وآكل ثمنهــا ) ‪.‬‬\n      ‫‪ -2‬قــال ابــن حجــر يف فتــح البــاري ‪ (45/10‬واســتدل مبطلــق قولــه صلــى‬\n      ‫اهلل عليــه وســلم ( كل مســكر حــرام ) علــى حتــرمي مــا يســكر ولــو لــم‬\n      ‫يكــن شــراب ًا فيدخــل يف ذلــك احلشيشــة وغيرهــا وقــد جــزم النــووي‬\n                                                           ‫وغيــره بأنــه مســكره ) ‪.‬‬\n                   ‫‪ -3‬املادة ‪ 56‬من نظام مكافحة املخدرات واملؤثرات العقلية ‪.‬‬\n\n\n\n\n      ‫ادعى املدعي العام ضد املدعى عليه بشرب املسكر وتعاطي احلشيش‬\n      ‫املخــدر وقيــادة الســيارة حتــت تأثيــر املســكر ‪ ،‬وطلــب إثبــات مــا أســند‬\n      ‫إليــه واحلكــم عليــه بحــد املســكر وســجنه ومنعــه مــن الســفر ‪،‬حيــث مت‬\n      ‫االشــتباه باملدعــى عليــه مــن قبــل الدوريــة األمنيــة وباستشــمامه اتضــح‬\n\n‫‪121‬‬\n\f‫أن رائحــة كريهــة تفــوح مــن أنفاســه ومت أخــذ عينــة مــن ســوائله أثبــت‬\n‫تقريــر الســموم الشــرعي إيجابيــة عينــة بــول املدعــى عليــه ملركبــات‬\n‫احلشــيش املخــدر ‪،‬وصــادق املدعــى عليــه علــى الدعــوى ‪،‬ولثبــوت شــرب‬\n‫املدعــى عليــه للمســكر واســتعمال احلشــيش املخــدر ‪،‬وبنــاء علــى مــا‬\n‫تقــدم حكمــت احملكمــة بجلــده حــد املســكر ثمانــن جلــدة ومنعــه‬\n‫مــن الســفر مــدة ســنتني بعــد تنفيــذ العقوبــة ‪،‬وثبــوت قيــادة املدعــى‬\n‫عليــه للســيارة حتــت تأثيــر املســكر وإفهامــه أن عقوبتــه عائــدة للجهــة‬\n‫املختصــة وعــدم إجابــة املدعــي العــام يف باقــي طلبــه ‪،‬وقنــع املدعــى‬\n‫‪،‬وصــدق‬\n      ‫ُ‬     ‫عليــه ‪،‬واعتــرض املدعــي العــام مكتفي ـ ًا بالئحــة الدعــوى‬\n                                       ‫احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد لدي أنا ‪.....‬‬\n‫القاضــي باحملكمــة اجلزائيــة باخلبــر وبنــاء علــى املعاملــة احملالــة لنــا مــن‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة يف محافظــة اخلبــر برقــم ‪33581555‬‬\n‫وتاريــخ ‪1433/09/19‬ه ـ املقيــدة باحملكمة برقــم ‪ 331730199‬وتاريخ‬\n‫‪1433/09/19‬ه ـ ففــي يــوم الثالثــاء املوافــق‪ 1434/04/02‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 9 : 20‬وفيهــا قــدم املدعــي العــام ‪.....‬الئحــة دعــوى عامــه‬\n‫ا‬\n‫ضــد ‪ .....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم (‪).....‬قائ ـ ً‬\n‫فيهــا حيــث أنــه باالطــاع علــى خطــاب مديــر شــرطة محافظــة اخلبــر‬\n‫رقــم (‪ ).....‬وتاريــخ ‪1433/8/14‬ه ـ املرفــق بــه محضــر تنفيــذ املهمــة املعد‬\n‫مــن قبــل رجــال الضبــط اجلنائــي بالدوريــات األمنيــة مبحافظــة اخلبــر‬\n‫املتضمــن أنــه يف يــوم اخلميــس املوافــق ‪1432/7/28‬ه ـ لوحــظ املدعــى‬\n\n                                                                                        ‫‪122‬‬\n\f      ‫عليــه وشــخص آخــر يدعــى ‪ (..... /‬مت إطــاق ســراحه مــن قبــل شــرطة‬\n      ‫الدمــام لعــدم صلتــه بالقضيــة ) حيــث كان الشــخصني يف وضــع اشــتباه‬\n      ‫فتــم تســليمهما ملركــز شــرطة شــمال اخلبــر وباستشــمام املدعــى عليــه‬\n      ‫اتضــح أن رائحــة كريهــة تفــوح مــن أنفاســه ومت اإلفــراج عنــه بكفالــة‬\n      ‫احلضوريــة وببعــث عينــة مــن ســوائله (الــدم والبــول) ورد تقريــر املركــز‬\n      ‫اإلقليمــي ملراقبــة الســموم الشــرعية رقــم (‪ )..........‬وتاريــخ ‪1432/8/3‬هـ‬\n      ‫متضمن ـ ًا ايجابيــة عينــة البــول املأخــوذة مــن املدعــى عليــه ملركبــات‬\n      ‫احلشــيش املخــدر املــدرج باجلــدول األول فئــة ( أ ) مــن نظــام مكافحــة‬\n      ‫املخــدرات واملؤثــرات العقليــة ‪ ،‬وبتاريــخ ‪1433/8/14‬ه ـ مت إعــادة‬\n      ‫إيقــاف املدعــى عليــه بشــعبة مكافحــة املخــدرات بالدمــام علــى ذمــة‬\n      ‫القضيــة وأفــرج عنــه بتاريــخ ‪1433/8/19‬ه ـ وباســتجواب املدعــى عليــه‬\n      ‫اقــر بشــربه للمســكر يف ‪ ........‬وبقيادتــه للســيارة بداخــل الســعودية ‪،‬‬\n      ‫وبســماع أقوالــه األوليــة مــن قبــل شــعبة مكافحــة املخــدرات بالدمــام‬\n      ‫أفــاد بــأن كان بحالــة ســكر يف ‪ ........‬وال يعلــم إذا كان وقتهــا قــد‬\n      ‫اســتعمل احلشــيش وانتهــى التحقيــق إلــى توجيــه االتهــام ل‪.....‬بشــرب‬\n      ‫املســكر وتعاطــي احلشــيش املخــدر وقيــادة الســيارة حتــت تأثيــر شــرب‬\n          ‫املســكر وتعاطــي احلشــيش املخــدر وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n      ‫‪ -1‬اعتــراف مبــا نــوه عنــه املرفــق علــى اللفــة رقــم (‪ )12‬من ملــف التحقيق‬\n                                                                        ‫املرفــق لفه (‪)1‬‬\n      ‫‪ -2‬محضــر تنفيــذ املهمــة املنــوه عنــه املرفــق علــى اللفــة رقــم ( ‪)2‬‬\n      ‫‪-3‬محضــر االستشــمام املنــوه عنــه املــدون علــى ص(‪ )11‬مــن ملــف‬\n                                                         ‫التحقيــق املرفــق لفــه (‪)1‬‬\n      ‫‪-4‬اعتــراف املدعــى عليــه بشــربه للمســكر وقيادتــه للســيارة بداخــل‬\n\n\n‫‪123‬‬\n\f‫الســعودية وظهــور رائحــة املســكر مــن أنفاســه بعــد استشــمامه مــع ورود‬\n‫ايجابيــة حتليلــه ملركبــات احلشــيش املخــدر دليــل علــى قيادتــه الســيارة‬\n                      ‫حتــت تأثيــر شــرب املســكر وتعاطــي احلشــيش املخــدر‬\n‫‪ -5‬تقريــر املركــز اإلقليمــي ملراقبــة الســموم الشــرعية املنــوه عنــه‬\n‫واملرفــق علــى لفــه رقــم (‪ )3‬وبالبحــث عمــا إذا كان لــه ســوابق لــم يعثــر‬\n‫لــه علــى ســوابق جنائيــة مســجلة وحيــث إن مــا أقــدم عليــه املدعــى عليــه‬\n‫‪ -‬وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ‪ -‬فعــل محــرم شــرع ًا ومجــرم‬\n                                                        ‫نظام ـ ًا أطلــب مــا يلــي‪:‬‬\n‫أوالً‪ :‬احلكــم عليــه بحــد الســكر لقــاء شــربه للمســكر ثانيــا‪ :‬إثبات ما‬\n‫أســند إليــه وفــق الفقــرة رقــم (‪ )2‬مــن املــادة رقــم (‪ )3‬مــن نظــام مكافحــة‬\n                                  ‫املخــدرات واملؤثــرات العقليــة واحلكم عليه‪:‬‬\n‫‪ -1‬بعقوبــة الســجن الــواردة يف الفقــرة (‪ )1‬مــن املــادة (‪ )41‬مــن النظــام‬\n                  ‫ووفق ـ ًا للمــادة (‪ )30‬مــن الالئحــة التنفيذيــة لــذات النظــام‬\n             ‫‪ -2‬منعه من السفر وفق الفقرة (‪ )1‬من املادة (‪ )56‬من النظام‬\n‫ثالثــا ‪ :‬إثبــات قيادتــه للســيارة حتــت تأثيــر شــرب املســكر وتعاطــي‬\n‫احلشــيش املخــدر وفق ـ ًا للفقــرة رقــم (‪ )8‬مــن اجلــدول رقــم (‪ )1‬امللحــق‬\n‫بنظــام املــرور وإفهامــه أن عقوبتــه الــواردة بالفقــرة رقــم (‪ )1‬مــن املــادة‬\n‫رقــم (‪ )68‬مــن نظــام املــرور تقــرر مــن اجلهــة املختصــة وفــق الفقــرة (‪)2‬‬\n‫مــن قــرار مجلــس الــوزراء رقــم (‪ )315‬يف ‪1428/10/24‬ه ـ هــذه دعــواي‬\n‫وبســؤال املدعــى عليــه عــن الدعــوى أجــاب بقولــه مــا جــاء يف الدعــوى‬\n‫مــن شــربي ملســكر واســتعمالي احلشــيش املخــدر وقيادتــي الســيارة‬\n‫حتــت تأثيــر املســكر واســتعمال احلشــيش املخــدر هــذا كلــه صحيــح‬\n‫ففــي تاريــخ ‪1433/7/28‬ه ـ كنــت متواجــد ًا يف ‪ ........‬وشــربت اخلمــر‬\n\n\n                                                                                       ‫‪124‬‬\n\f      ‫هنــاك كمــا أنــي اســتعملت احلشــيش املخــدر وقمــت بقيــادة الســيارة‬\n      ‫حتــت تأثيــر املســكر واحلشــيش املخــدر ورجعــت للســعودية ومت القبــض‬\n      ‫علــي يف اخلبــر اجلنوبيــة عنــد الســاعة احلاديــة عشــر مســاء تقريب ـ ًا حيــث‬\n      ‫كنــت أقــود الســيارة حتــت تأثيــر املســكر واحلشــيش املخــدر هــذا مــا‬\n      ‫ـاء علــى مــا تقــدم مــن‬\n                              ‫حصــل وأنــا نــادم علــى فعلــي هكــذا أجــاب فبنـ ً‬\n      ‫الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه بشــرب اخلمــر واســتعمال‬\n      ‫احلشــيش املخــدر وحيــث إن فعــل املدعــى عليــه مــن كبائــر الذنــوب‬\n      ‫فقــد لعــن رســول اهلل صلــى اهلل عليــه وســلم يف اخلمــر ثمانيــة ((شــاربها‬\n      ‫وســاقيها وحاملهــا واحملمولــة إليه وعاصرهــا ومعتصرها وبائعها واكل‬\n      ‫ثمنهــا)) واللعــن ال يكــون إال علــى كبيــرة مــن كبائــر الذنــوب وملــا نص‬\n      ‫عليــه أهــل العلــم مــن إقامــة حــد املســكر علــى متنــاول احلشــيش املخــدر‬\n      ‫قــال ابــن حجــر رحمــه اهلل تعالــى يف فتــح البــاري(‪(( )45/10‬واســتدل‬\n      ‫مبطلــق قولــه صلــى اهلل عليــه وســلم ((كل مســكر حرام))علــى حتــرمي‬\n      ‫مــا يســكر ولــو لــم يكــن شــرابا فيدخــل يف ذلــك احلشيشــة وغيرهــا‬\n      ‫وقــد جــزم النــووي وغيــره بأنهــا مســكره))وحيث أقــر املدعــى عليــه‬\n      ‫بقيــادة الســيارة حتــت تأثيــر املســكر واحلشــيش املخــدر وملــا جــاء يف‬\n      ‫املــادة السادســة واخلمســن مــن نظــام مكافحــة املخــدرات وحيــث إن‬\n      ‫املــادة احلاديــة واألربعــن مــن ذات النظــام غيــر منطبقــة يف حــق املدعــى‬\n      ‫عليــه فهــي خاصــة باحليــازة لــذا فقــد قــررت مــا يلــي أو ًال ثبــت لــدي شــرب‬\n      ‫املدعــى عليــه للمســكر واســتعماله احلشــيش املخــدر وقــررت أن يجلــد‬\n      ‫لقــاء ذلــك حــد املســكر ثمانــن جلــدة دفعــة واحــدة كمــا قــررت أن‬\n      ‫مينــع املدعــى عليــه مــن الســفر خــارج اململكــة مــدة ســنتني بعــد تنفيــذ‬\n      ‫عقوبتــه لقــاء اســتعماله احلشــيش املخــدر ثانيـ ًا ثبــت لــدي قيــادة املدعــى‬\n\n\n‫‪125‬‬\n\f‫عليــه للســيارة حتــت تأثيــر املســكر واحلشــيش املخــدر وأفهمتــه أن‬\n‫عقابــه علــى ذلــك عائــد للجهــة املختصــة ثالثـ ًا عــدم إجابــة املدعــي العــام‬\n‫فيمــا طلبــه مــن تطبيــق املــادة احلاديــة واألربعــن مــن نظــام مكافحــة‬\n‫املخــدرات علــى املدعــى عليــه ومبــا تقــدم حكمــت وبعــرض احلكــم‬\n‫قنــع املدعــى عليــه ولــم يقنــع املدعــي العــام مكتفيـ ًا مبــا قــدم يف الئحــة‬\n‫الدعــوى وأقفلــت اجللســة الســاعة العاشــرة إال خمــس دقائــق وصلــى اهلل‬\n                                                         ‫وســلم علــى نبينــا محمــد‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولى مبحكمة االســتئناف باملنطقة الشــرقية على املعاملة الواردة من‬\n‫فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة اخلبــر برقــم ‪34/1730199‬‬\n‫وتاريــخ ‪1434/4/8‬ه ـ املقيــدة لــدى احملكمــة برقــم ‪34/883938‬‬\n‫وتاريــخ ‪1434/4/10‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n‫باحملكمــة الشــيخ ‪.....‬املســجل برقــم ‪ 34177873‬وتاريــخ ‪1434/4/2‬ه ـ‬\n‫اخلــاص بدعــوى‪ /‬املدعــي العــام ضــد‪...../‬يف قضيــة مســكر وقــد تضمــن‬\n‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار‬\n‫وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم واهلل‬\n‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف‬\n                                                                   ‫‪1434/5/14‬ه ـ ‪.‬‬\n\n\n\n\n                                                                                         ‫‪126‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":121,"source_page_end":126,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"cc56160f34167d6d17538819757fb455611dba3061f58ab93bb5e1f454103c85","normalized_text_hash":"1a2559dd2921379637d760ef2a7d0c39328bb6e4450790d499a58ff07c8b3d30","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p121-34177873"},{"id":"ddc28b19-12a4-5962-ad65-7a67bdc98f2b","document_type":"judgment","category":"judicial","subcategory":"general","title":"مسكر -شرب املسكر -حد املسكر -قيادة سيارة حتت تأثير املسكر -هروب من رجال األمن -تهجم على منزل -التعزير بالسجن واجللد -تعهد .","document_number":"34189034","case_number":"33612613","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/4/15","year":"1434","subject":"مسكر -شرب املسكر -حد املسكر -قيادة سيارة حتت تأثير املسكر -هروب من رجال األمن -تهجم على منزل -التعزير بالسجن واجللد -تعهد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34189034:‬تاريخه‪1434/4/15 :‬هـ‬\n        ‫رقم الدعوى‪ 33612613:‬رقم قرار التصديق‬\n           ‫من محكمة االستئناف‪/34223117:‬ج‪2‬‬\n                         ‫تاريخه‪1434/06/07:‬هـ‬\n\n\n      ‫مســكر ‪ -‬شــرب املســكر ‪ -‬حــد املســكر ‪ -‬قيــادة ســيارة حتــت تأثيــر املســكر‬\n      ‫‪ -‬هــروب مــن رجــال األمــن ‪ -‬تهجــم علــى منــزل ‪ -‬التعزيــر بالســجن‬\n                                                           ‫واجللــد ‪ -‬تعهــد ‪.‬‬\n\n\n\n\n                    ‫‪ -1‬قوله تعالى ( وال تفسدوا يف األرض بعد إصالحها ) ‪.‬‬\n                       ‫‪ -2‬قوله تعالى ( وال تعتدوا إن اهلل ال يحب املعتدين ) ‪.‬‬\n      ‫‪ -3‬قولــه صلــى اهلل عليــه وســلم ( كل املســلم عــل املســلم حــرام دمــه‬\n                                                              ‫ومالــه وعرضــه) ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام ضــد املدعــى عليهــم األول والثانــي والثالــث‬\n      ‫بشــرب املســكر وقيــادة األول حتــت تأثيــر املســكر وتســتر الرابــع‬\n      ‫علــى زمالئــه واالجتمــاع معهــم علــى منكــر وهروبهــم مــن رجــال األمــن‬\n      ‫ودخــول منــزل أحــد املواطنــن واللجــوء إلــى ســطحه وطلــب إثبــات مــا‬\n      ‫أســند إليهــم واحلكــم علــى األول والثانــي والثالــث بحــد املســكر‬\n      ‫وعقوبــة تعزيريــة للرابــع لقــاء مــا أســند إليــه ولقــاء هروبهــم مــن رجــال‬\n      ‫األمــن ولــأول كونــه أحــد رجــال األمــن ‪،‬حيــث قبــض علــى املدعــى‬\n      ‫عليهــم مــن قبــل الدوريــات األمنيــة إثــر ورود بــاغ مــن أحــد املواطنــن‬\n\n‫‪127‬‬\n\f‫بتهجــم املدعــى عليهــم علــى منزلــه حيــث قدمــوا علــى ســيارة وباالنتقــال‬\n‫للموقــع الذوا بالهــروب مترجلــن وقــد جلــأوا إلــى ســطح منــزل مواطــن‬\n‫آخــر ومت اســتخراجهم والقبــض عليهــم وكانــوا بحالــة غيــر طبيعيــة‬\n‫‪،‬أجــاب األول باإلنــكار وأجــاب الثانــي والثالــث والرابــع باملصادقــة‬\n‫علــى الدعــوى ‪،‬ومبــا أن املدعــى عليــه األول أنكــر الدعــوى وأقــر بهــا‬\n‫الثانــي والثالــث والرابــع ‪،‬وبنــاء علــى مــا تقــدم حكمــت احملكمــة بعــدم‬\n‫إدانــة املدعــى عليــه األول وبإقامــة حــد املســكر علــى املدعــى عليهــم‬\n‫الثانــي والثالــث والرابــع وتعزيرهــم بالســجن واجللــد ‪ ،‬صــدق احلكــم‬\n                                                ‫مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫ـدي‬\n ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد فلـ َّ‬\n‫ـاء علــى املعاملــة‬\n                   ‫أنــا ‪.....‬القاضــي باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n‫الــواردة إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء‬\n‫برقــم ه ـ ف ‪ 11497/2/2‬وتاريخ‪1433/10/18‬ه ـ واملقيــدة بهــذه‬\n‫احملكمــة برقم‪331848080‬وتاريخ‪1433/10/21‬ه ـ واحملالــة إلينــا من‬\n‫فضيلــة الرئيــس برقم‪33612613‬وتاريخ‪1433/10/21‬ه ـ فتحــت‬\n‫اجللســة األولــى يــوم األربعــاء ‪1433/11/24‬هـ الســاعة التاســعة والنصف‬\n‫وفيهــا حضــر املدعــي العــام ‪.....‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا‬\n‫مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n‫ا‪:‬‬  ‫األحســاء ذي الرقــم ‪.....‬والتاريــخ ‪1431/1/5‬ه ـ وقـ ّـرر دعــواه قائ ـ ً‬\n‫فبصفتــي مدعيـ ًا عامـ َا بدائــرة االدعــاء العــام مبحافظــة االحســاء أدعــي‬\n‫علــى كل مــن ‪ 27..... -1 :‬عام ـ ًا العمــل عســكري ســعودي اجلنســية‬\n\n                                                                                        ‫‪128‬‬\n\f      ‫مبوجــب الســجل املدنــي رقــم ‪.....‬أوقــف بتاريــخ ‪1433/04/29‬ه ـ وأفــرج‬\n      ‫عنــه بالكفالــة بتاريــخ ‪1433/05/01‬ه ـ يقيــم يف محافظــة االحســاء‬\n      ‫حــي ‪20..... -2......‬عامـ ًا املهنــة طالــب ســعودي اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪.....‬أوقــف بتاريــخ ‪1433/04/29‬ه ـ وأفــرج عنــه بكفالــة‬\n      ‫بتاريــخ ‪1433/05/01‬ه ـ يقيــم يف محافظــة االحســاء حــي ‪19..... -3.....‬‬\n      ‫عام ـ ًا عاطــل عــن العمــل ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫‪.....‬أوقــف بتاريــخ ‪1433/04/29‬ه ـ وأفــرج عنــه بالكفالــة بتاريــخ‬\n      ‫‪1433/05/01‬ه ـ يقيــم يف محافظــة االحســاء حــي ‪20..... -4.....‬عام ـ ًا‬\n      ‫عاطــل عــن العمــل ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n      ‫أوقــف بتاريــخ ‪1433/04/29‬ه ـ وأفــرج عنــه بالكفالــة بتاريــخ‬\n      ‫‪1433/05/01‬ه ـ يقيــم يف محافظــة االحســاء حــي ‪ ......‬حيــث انــه بتاريخ‬\n      ‫‪1433/04/29‬ه ــتم القبــض علــى املدعــى عليهــم مــن قبــل رجــال‬\n      ‫الدوريــات األمنيــة مبحافظــة األحســاء إثــر ورود بــاغ مــن املدعــو ‪..... /‬‬\n      ‫يفيــد فيــه بقيــام أربعــة أشــخاص بالتهجــم علــى منزلــه يف حــي ‪.....‬حيــث‬\n      ‫قدمــوا علــى ســيارة مــن صنــع ‪1999‬م حتمــل اللوحــة رقــم (‪ ).....‬بقيــادة‬\n      ‫املدعــى عليــه األول وباالنتقــال للموقــع الذوا جميعـ ًا بالهــروب مترجلــن‬\n      ‫فــور مشــاهدتهم للدوريــات األمنيــة وقــد جلئــوا إلــى ســطح منــزل املدعــو ‪/‬‬\n      ‫‪.....‬حينهــا مت اســتخراجهم مــن املنــزل مــن قبــل أبــن املبلــغ وأحــد اجليــران‬\n      ‫وتســليمهم للدوريــات األمنيــة ولوحــظ بأنهــم يف حالــة غيــر طبيعيــة‬\n      ‫ســكر ‪ .‬وبضبــط إفــادة املبلــغ املدعــو ‪..... /‬أفــاد بقيــام املدعــى عليهــم‬\n      ‫بطــرق بــاب املنــزل وبعــد فتــح البــاب طلبــوا منــه إخــراج أبنائــه لســبب‬\n      ‫غيــر معــروف والذوا بالهــرب بعــد قيامــه بتبليــغ الدوريــات األمنيــة ‪.‬‬\n      ‫وبضبــط إفــادة املدعــو ‪..... /‬أفــاد مبشــاهدة املدعــى عليهــم يهربــون مــن‬\n\n\n‫‪129‬‬\n\f‫الدوريــات األمنيــة وقــد جلئــوا إلــى ســطح منزلــه كونــه ســكن دبلكــس‬\n‫والــدرج مفتــوح مباشــرة علــى الســطح وباستشــمام املدعــى عليــه اتضــح‬\n‫انبعــاث رائحــة املســكر مــن األول والثانــي والثالــث ‪ .‬وباســتجواب‬\n‫املدعــى عليهــم أقــر الثانــي بشــربه ملــادة الكلونيــا املســكرة داخــل‬\n‫املنــزل بعــد مزجهــا باملــاء ‪ .‬وقــد أســفر التحقيــق عــن توجيــه االتهــام‬\n‫لــأول والثانــي والثالــث بشــرب املســكر وقيــادة األول للســيارة حتــت‬\n‫تأثيــره وتســتر الرابــع عــن زمالئــه واالجتمــاع معهــم علــى منكــر‬\n‫وهروبهــم مــن رجــال األمــن ودخــول منــزل أحــد املواطنــن واللجــوء إلــى‬\n‫ســطح منزلــه وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬أقوالهــم املدونــة علــى‬\n‫الصفحــة رقــم (‪ )5-2‬مــن دفتــر التحقيــق لفــه رقــم (‪ )1‬والصفحــة رقــم‬\n‫(‪ )16-13‬مــن دفتــر التحقيــق لفــه رقــم (‪ -2 )2‬محضــر االستشــمام‬\n‫املــدون علــى الصفحــة رقــم (‪ )6‬مــن دفتــر التحقيــق لفــه رقــم (‪-3 . )2‬‬\n‫محضــر القبــض املرفــق علــى لفــه رقــم (‪ -4 . )3‬أقــوال املبلغــن املدونــة‬\n‫علــى الصفحــة رقــم (‪ )12-9‬مــن دفتــر التحقيــق لفــه رقــم (‪ . )2‬وبالبحــث‬\n‫عمــا إذا كان لهــم ســوابق لــم يعثــر علــى ســوابق جنائيــة مســجلة بحــق‬\n‫املدعــى عليهــم األول والثالــث والربــع أمــا الثانــي فقــد عثر على ســابقتني‬\n‫مســجلتني عليــه مــن نــوع ســرقة ‪ .‬وحيــث إن مــا أقــدم عليــه املدعــى عليهم‬\n‫املذكوريــن وهــم بكامــل أهليتهــم املعتبــرة شــرع ًا فعــل محــرم ومعاقــب‬\n‫عليــه شــرع ًا ونظام ـ ًا أطلــب إثبــات مــا أســند إليهــم واحلكــم عليهــم‬\n‫باالتــي ‪ -1 :‬بحــد املســكر لــأول والثانــي والثالــث لقــاء شــربهم لــه ‪.‬‬\n‫‪ -2‬بعقوبــة تعزيريــة للرابــع لقــاء مــا أســند إليــه مــن اتهــام ولقــاء هروبهــم‬\n‫مــن رجــال األمــن ولــأول كونــه احــد رجــال االمــن املؤمــل فيــه حفــظ‬\n‫النظــام ال مخالفتــه اســتناد ًا لتعميــم ولــي العهــد ونائــب رئيــس مجلــس‬\n\n\n                                                                                         ‫‪130‬‬\n\f      ‫الــوزراء ووزيــر الداخليــة ( رحمــه اهلل ) رقــم ( ‪ )19371‬وتاريــخ‬\n      ‫‪1429/03/24‬ه ـ ‪ -3 .‬إثبــات قيــادة األول للســيارة وهــو حتــت تأثيــر‬\n      ‫شــرب املســكر وإفهامــه بــأن عقابــه علــى ذلــك عائــد للجهــة املختصــة‬\n      ‫اســتناد ًا للفقــرة ( أوال ) مــن املــادة ( ‪ )68‬مــن نظــام املــرور ‪ .‬علم ـ ًا بــأن‬\n      ‫احلــق اخلــاص انتهــى بالتنــازل ‪ .‬هكــذا ا َّدعــى ‪ ،‬عليــه فقــد حضــر املدعــى‬\n      ‫عليهــم جميعـ ًا وبعــد التأكــد مــن هوياتهــم جــرى عــرض دعــوى املدعــي‬\n      ‫ا ‪ :‬مــا ذكــره املدعــي‬     ‫العــام عليهــم فأجــاب املدعــى عليــه األول ‪.....‬قائـ ً‬\n      ‫العــام مــن اتهامــي بشــرب املســكر وقيادتــي للســيارة حتــت تأثيــره‬\n      ‫وهروبــي مــن رجــال األمــن ودخــول منــزل أحــد املواطنــن واللجــوء إلــى‬\n      ‫ســطح منزلــه كل ذلــك غيــر صحيــح والصحيــح أننــا ذهبنــا لزيــارة أحــد‬\n      ‫األصدقــاء يف حــي ‪.....‬وكان الطريــق ترابــي فغــرزت ســيارتي وجــاء‬\n      ‫أحــد املواطنــن فقــال ‪ :‬إنكــم ســكرانني فهــرب رفاقــي وأنــا جلســت‬\n      ‫يف ســيارته حتــى جــاءت الدوريــة وســلمت نفســي هكــذا أجــاب كمــا‬\n      ‫ا ‪ :‬مــا ذكــره املدعــي العــام مــن‬      ‫أجــاب املدعــى عليــه الثانــي ‪.....‬قائ ـ ً‬\n      ‫اتهامــي بشــرب املســكر وهروبــي مــن رجــال األمــن ودخولــي منــزل أحــد‬\n      ‫املواطنــن واللجــوء إلــى ســطح منزلــه فصحيــح وصحيــح أيض ـ ًا نســبة‬\n      ‫الســابقتني لــي وقــد أخــذت محكوميتهمــا هكــذا أجــاب كمــا أجــاب‬\n      ‫ا ‪ :‬مــا ذكــره املدعــي العــام مــن اتهامــي‬       ‫املدعــى عليــه الثالــث ‪.....‬قائ ـ ً‬\n      ‫بشــرب املســكر وهروبــي مــن رجــال األمــن ودخولــي منــزل أحــد‬\n      ‫املواطنــن واللجــوء إلــى ســطح منزلــه فصحيــح وأنــا نــادم علــى مــا بــدر‬\n      ‫ا ‪ :‬مــا‬ ‫منــي هكــذا أجــاب كمــا أجــاب املدعــى عليــه الرابــع ‪.....‬قائ ـ ً‬\n      ‫ذكــره املدعــي العــام مــن اتهامــي بالتســتر علــى زمالئــي واالجتمــاع‬\n      ‫معهــم علــى منكــر وهروبــي مــن رجــال األمــن ودخــول منــزل أحــد‬\n\n\n‫‪131‬‬\n\f‫املواطنــن واللجــوء إلــى ســطح منزلــه كل ذلــك صحيــح وقــد هربــت مــن‬\n‫ـب ونــادم علــى مــا بــدر‬  ‫الدوريــة بســبب أننــي كنــت ســكران ًا وأنــا تائـ ٌ‬\n‫منــي هكــذا أجــاب ثــم جــرى ســؤال املدعــي العــام هــل لديــه بينــة علــى‬\n‫ـدي ســوى مــا يف أوراق املعاملــة‬   ‫مــا نفــاه املدعــى عليــه األول قــال ‪ :‬ليــس لـ َّ‬\n‫وأطلــب الرجــوع إليهــا هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع‬\n‫أوراق املعاملــة ومنهــا ‪ :‬تقريــر ســموم شــرعية الصــادرة مــن قســم‬\n‫الكيميــاء الشــرعية باملركــز اإلقليمــي ملراقبة الســموم التابع للمديرية‬\n‫العامــة للشــؤون الصحيــة باملنطقــة الشــرقية برقــم (‪).....‬و( ‪ ).....‬و( ‪).....‬‬\n‫لعــام ‪1433‬ه ـ املتضمنــة ســلبية العينــات املأخــوذة مــن املدعــى عليهــم‬\n‫األول والثانــي والثالــث للمــواد الكحوليــة وللمــواد املخــدرة كمــا جــرى‬\n‫االطــاع علــى إقــرار املدعــى عليــه األول فلــم أجــد فيــه مــا يدينــه مبــا‬\n‫نســب إليــه كمــا جــرى االطــاع علــى كــروت ســوابق املدعــى عليهــم‬\n‫املتضمنــة عــدم وجــود ســوابق عليهــم ســوى الثانــي فلديــه ســابقتي ســرقة‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وبعــد النظــر يف حــال املدعــى‬    ‫فبنـ ً‬\n‫عليهــم والتأكــد مــن أهليتهــم وبعــد دراســة أوراق املعاملــة ودراســتها‬\n‫أن املدعــى عليــه األول ‪.....‬أنكــر دعــوى املدعــي العــام باتهامــه‬         ‫ومبــا َّ‬\n‫بشــرب املســكر وقيادتــه للســيارة حتــت تأثيــره وهروبــه مــن رجــال‬\n‫األمــن ودخولــه منــزل أحــد املواطنــن واللجــوء إلــى ســطح منزلــه وال بينــة‬\n‫للمدعــي العــام علــى ذلــك ممــا يســتوجب عــدم إثبــات إدانتــه بذلــك وال‬\n‫أن املدعــى عليهــم‬ ‫ا ومبــا َّ‬  ‫تعزيــره للتهمــة لعــدم توجــه التهمــة عليــه أص ـ ً‬\n‫الثانــي والثالــث والرابــع أقـ ُّـروا بشــرب املســكر وحـ ُّـد املســكر أن يجلــد‬\n‫ـتقر عليــه عمــل األمــة ممــا يســتوجب‬        ‫صاحبــه ثمانــن جلــدة كمــا اسـ َّ‬\n‫أن املدعــى عليهمــا‬   ‫إقامــة حـ ّـد املســكر علــى كل واحــد منهــم ومبــا َّ‬\n\n                                                                                             ‫‪132‬‬\n\f      ‫الثانــي والثالــث أقـ َّـرا بالهــروب مــن رجــال األمــن ودخولهمــا ملنــزل أحــد‬\n      ‫أن املدعــى عليــه الرابــع أقـ َّـر‬            ‫املواطنــن واللجــوء إلــى ســطح منزلــه ومبــا َّ‬\n      ‫بالتســتر علــى زمالئــه واالجتمــاع معهــم علــى منكــر وهروبــه مــن رجــال‬\n      ‫أن‬‫األمــن ودخــول منــزل أحــد املواطنــن واللجــوء إلــى ســطح منزلــه ومبــا َّ‬\n      ‫ض‬         ‫(و َل ُت ْف ِسـ ُـدوا ِف ْ َ‬\n           ‫ال ْر ِ‬                             ‫مــا صــدر منهــم مــن احملــرم شــرع ًا قــال تعالــى ‪َ :‬‬\n                                           ‫(وال َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n      ‫الل ال ُي ِحـ ُّـب ْال ُْع َتدِ يـ َـن )‬                           ‫َب ْعـ َـد ِإ ْص َلحِ َهــا ) وقــال تعالــى ‪َ :‬‬\n      ‫دم ـ ُه‬\n            ‫ـرام ُ‬‫وقــال صلــى اهلل عليــه وســلم ‪(( :‬كلُّ املســلم علــى املســلم حـ ٌ‬\n      ‫وعرضــه)) ممــا يســتوجب تعزيرهــم ويتوجــه أن يكــون املدعــى‬                                ‫ُ‬       ‫وما ُل ـ ُه‬\n      ‫عليــه الثانــي أشــدهم عقوبــة لعــدم ارتداعــه بالعقوبــات الســابقة عليــه‬\n      ‫لــذا كلــه وألجــل احلــق العــام حكمــت علــى املدعــى عليهــم مبــا يلــي ‪:‬‬\n      ‫ـدي إدانــة املدعــى عليــه األول ‪.....‬بشــرب املســكر وال‬                          ‫أوالً‪ /‬لــم يثبــت لـ َّ‬\n      ‫قيادتــه للســيارة حتــت تأثيــره وال هروبــه مــن رجــال األمــن وال دخولــه‬\n      ‫منــزل أحــد املواطنــن واللجــوء إلــى ســطح منزلــه ر َّد دعــوى املدعــي العــام‬\n      ‫ـدي إدانــة املدعــى عليهــم الثانــي ‪.....‬‬                ‫بإثبــات إدانتــه بذلــك ‪ .‬ثانيـ ًا ‪ /‬ثبــت لـ َّ‬\n      ‫والثالــث ‪.....‬والرابــع ‪.....‬بشــرب املســكر ويجلــد كل واحــد منهمــا حـ َّـد‬\n      ‫ـدي إدانــة‬   ‫املســكر ثمانــون جلــدة دفعــة واحــدة علن ـ ًا ‪ .‬ثالث ـ ًا ‪ /‬ثبــت لـ َّ‬\n      ‫املدعــى عليهمــا الثانــي والثالــث بالهــروب مــن رجــال األمــن ودخولهمــا‬\n      ‫ملنــزل أحــد املواطنــن واللجــوء إلــى ســطح منزلــه ويعــزر املدعــى عليــه‬\n      ‫الثانــي بســجنه ملــدة ســتة أشــهر مــن تاريــخ انتهــاء محكوميتــه يف‬\n      ‫القضيــة املســجون ألجلهــا وبجلــده مائــة وخمســون جلــدة مفرقــة علــى‬\n      ‫ثــاث دفعــات كل دفعــة خمســون جلــدة وبــن كل دفعــة وأخــرى مــدة‬\n      ‫ال تقــل عــن عشــرة أيــام وبــن جلــد احلــد وجلــد التعزيــر مــدة ال تقــل عــن‬\n      ‫عشــرة أيــام ويكــون جلــد احلــد هــو املقــدم ‪ .‬ويعــزر املدعــى عليــه الثالــث‬\n\n\n‫‪133‬‬\n\f‫‪.....‬بســجنه ملــدة أربعــة أشــهر حتتســب منهــا املــدة التــي أوقــف فيهــا علــى‬\n‫ذمــة القضيــة وبجلــده مائــة وعشــرون جلــدة مفرقــة علــى ثــاث دفعــات‬\n‫كل دفعــة أربعــون جلــدة وبــن كل دفعــة وأخــرى مــدة ال تقــل عن عشــرة‬\n‫أيــام وبــن جلــد احلــد وجلــد التعزيــر مــدة ال تقــل عــن عشــرة أيــام ويكــون‬\n‫ـدي إدانــة املدعــى عليــه الرابــع‬‫جلــد احلــد هــو املقــدم ‪ .‬رابع ـ ًا ‪ /‬ثبــت لـ َّ‬\n‫بالتســتر علــى زمالئــه واالجتمــاع معهــم علــى منكــر وهروبــه مــن رجــال‬\n‫األمــن ودخــول منــزل أحــد املواطنــن واللجــوء إلــى ســطح منزلــه بســجنه‬\n‫ملــدة أربعــة أشــهر حتتســب منهــا املــدة التــي أوقــف فيهــا على ذمــة القضية‬\n‫وبجلــده مائــة وعشــرون جلــدة مفرقــة علــى ثــاث دفعــات كل دفعــة‬\n‫أربعــون جلــدة وبــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام وبــن‬\n‫جلــد احلــد وجلــد التعزيــر مــدة ال تقــل عــن عشــرة أيــام ويكــون جلــد احلــد‬\n‫هــو املقــدم ‪ .‬خامسـ ًا ‪ /‬يؤخــذ عليهــم التعهــد بعــدم العــودة ملثــل مــا صــدر‬\n‫منهــم ‪ .‬وبتــاوة احلكــم علــى الطرفــن وإفهــام املدعــى عليهــم بحقهــم يف‬\n‫التمييــز قــرروا قناعتهــم باحلكــم عــدا املدعــى عليــه الثانــي فقــد قــرر‬\n‫عــدم القناعــة دون الئحــة اعتراضيــة وطلــب املدعــي العــام رفــع احلكــم‬\n‫للتمييــز وأن الئحتــه االعتراضيــة هــي الئحــة الدعــوى وصلــى اهلل وســلم‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن حــرر احلكــم يف‬\n                                                                  ‫‪1434/04/15‬هـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة املقيــدة‬\n‫لــدى احملكمــة برقــم ‪/341172187‬ج‪ 2‬وتاريــخ ‪1434/5/13‬ه ـ‬\n‫الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة األحســاء‬\n‫املكلــف برقــم ‪ 34/923343‬وتاريــخ ‪1434/5/7‬ه ـ املرفــق بهــا القــرار‬\n\n\n                                                                                           ‫‪134‬‬\n\f      ‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪...../‬املســجل برقــم‬\n      ‫‪ 34189034‬وتاريــخ ‪1434/4/15‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضد‬\n      ‫كل مــن‪...../1‬و‪...../2‬و‪ ....../3‬و‪...../4‬يف قضيــة ســكر وقــد تضمــن‬  ‫ٍ‬\n      ‫القــرار حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه‪ .‬وبدراســة القــرار‬\n      ‫وصــورة ضبطــه وأوراق املعاملــة قررنــا املصادقــة علــى احلكــم‪ .‬واهلل‬\n      ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم‪ .‬حــرر يف‬\n                                                                 ‫‪1434/5/26‬ه ـ ‪.‬‬\n\n\n\n\n‫‪135‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"42dbac97-4506-51f9-b68e-80dcdaa82148","source_page_start":127,"source_page_end":135,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c7a0e8ab8cd32ba3c1610b35aaa9eec8bb29b442ee12f518c87dc2071f5842c2","normalized_text_hash":"3d8805f462142bb777a22cd995e98f3e94bcdf4f8b3263ce05eb075876c9c28f","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v16-p127-34189034"}]$archive_payload$::jsonb) AS x LIMIT 25
